// Kotonoha v2.5 Step 2 - Textbook Dialogues (Day 1 ~ Day 31, Set 2 & Set 3 = 62 sets, 372 lines, 100% furigana)
window.KOTONOHA_TEXTBOOK_DIALOGUES = {"cafe":[{"badge":"응용·옵션","title":"디카페인·두유 변경과 소품 요청","lines":[{"speaker":"하루카","role":"바리스타","jp":"お<ruby>次<rt>つぎ</rt></ruby>のお<ruby>客様<rt>きゃくさま</rt></ruby>、ご<ruby>注文<rt>ちゅうもん</rt></ruby>をどうぞ！","plain":"お次のお客様、ご注文をどうぞ！","ko":"다음 손님, 주문하시겠어요?","note":""},{"speaker":"나","role":"손님","jp":"アイスのカフェラテをMサイズでお<ruby>願<rt>ねが</rt></ruby>いします。<ruby>牛乳<rt>ぎゅうにゅう</rt></ruby>を<ruby>豆乳<rt>とうにゅう</rt></ruby>に<ruby>変更<rt>へんこう</rt></ruby>できますか？","plain":"アイスのカフェラテをMサイズでお願いします。牛乳を豆乳に変更できますか？","ko":"아이스 카페라떼 M사이즈로 부탁드려요. 우유를 두유로 변경할 수 있나요?","note":"「〜に変更できますか」는 카페 커스텀 만능 패턴!"},{"speaker":"하루카","role":"바리스타","jp":"はい、プラス<ruby>五十円<rt>ごじゅうえん</rt></ruby>で<ruby>豆乳<rt>とうにゅう</rt></ruby>に<ruby>変更<rt>へんこう</rt></ruby>できます。デカフェにもできますよ。","plain":"はい、プラス五十円で豆乳に変更できます。デカフェにもできますよ。","ko":"네, 50엔 추가하시면 두유로 변경 가능합니다. 디카페인도 돼요.","note":""},{"speaker":"나","role":"손님","jp":"<ruby>夜<rt>よる</rt></ruby>なのでデカフェでお<ruby>願<rt>ねが</rt></ruby>いします！あと、ストローと<ruby>紙ナプキン<rt>かみなぷきん</rt></ruby>もいただけますか？","plain":"夜なのでデカフェでお願いします！あと、ストローと紙ナプキンもいただけますか？","ko":"밤이라서 디카페인으로 부탁드릴게요! 그리고 빨대랑 종이 냅킨도 주실 수 있나요?","note":""},{"speaker":"하루카","role":"바리스타","jp":"かしこまりました。<ruby>持ち帰<rt>もちかえ</rt></ruby>りなので<ruby>蓋<rt>ふた</rt></ruby>とカップホルダーもおつけしますね。","plain":"かしこまりました。持ち帰りなので蓋とカップホルダーもおつけしますね。","ko":"알겠습니다. 포장이라 뚜껑과 컵홀더도 같이 챙겨 드릴게요.","note":""},{"speaker":"나","role":"손님","jp":"ありがとうございます！ガムシロップは<ruby>大丈夫<rt>だいじょうぶ</rt></ruby>です。","plain":"ありがとうございます！ガムシロップは大丈夫です。","ko":"감사합니다! 시럽은 괜찮습니다.","note":"거절할 땐 「いりません」보다 「大丈夫です」가 부드러워요."}]},{"badge":"트러블·마무리","title":"콘센트 좌석·디저트 추가와 반납","lines":[{"speaker":"나","role":"손님","jp":"すみません、<ruby>店内<rt>てんない</rt></ruby>で<ruby>少<rt>すこ</rt></ruby>し<ruby>作業<rt>さぎょう</rt></ruby>したいのですが、コンセントが<ruby>使<rt>つか</rt></ruby>える<ruby>席<rt>せき</rt></ruby>はありますか？","plain":"すみません、店内で少し作業したいのですが、コンセントが使える席はありますか？","ko":"저기요, 매장에서 잠깐 작업하고 싶은데 콘센트를 쓸 수 있는 자리가 있나요?","note":""},{"speaker":"하루카","role":"바리스타","jp":"<ruby>窓際<rt>まどぎわ</rt></ruby>のカウンター<ruby>席<rt>せき</rt></ruby>にコンセントがございます。Wi-Fiも<ruby>無料<rt>むりょう</rt></ruby>で<ruby>使<rt>つか</rt></ruby>えますよ。","plain":"窓際のカウンター席にコンセントがございます。Wi-Fiも無料で使えますよ。","ko":"창가 카운터석에 콘센트가 있어요. 와이파이도 무료로 쓰실 수 있습니다.","note":""},{"speaker":"나","role":"손님","jp":"<ruby>助<rt>たす</rt></ruby>かります！あと、クロワッサンを<ruby>追加<rt>ついか</rt></ruby>したいんですが、<ruby>少<rt>すこ</rt></ruby>し<ruby>温<rt>あたた</rt></ruby>めていただけますか？","plain":"助かります！あと、クロワッサンを追加したいんですが、少し温めていただけますか？","ko":"다행이네요! 그리고 크루아상을 추가하고 싶은데 살짝 데워 주실 수 있나요?","note":"「温めて(あたためて)」 발음 교정 완료!"},{"speaker":"하루카","role":"바리스타","jp":"もちろんです！お<ruby>冷<rt>ひや</rt></ruby>も<ruby>一緒<rt>いっしょ</rt></ruby>にお<ruby>持<rt>も</rt></ruby>ちしましょうか？","plain":"もちろんです！お冷も一緒にお持ちしましょうか？","ko":"물론이죠! 찬물도 같이 가져다드릴까요?","note":"「お冷(おひや)」는 식당·카페의 차가운 물."},{"speaker":"나","role":"손님","jp":"お<ruby>願<rt>ねが</rt></ruby>いします！<ruby>飲み終<rt>のみお</rt></ruby>わったらトレイはどこに<ruby>戻<rt>もど</rt></ruby>せばいいですか？","plain":"お願いします！飲み終わったらトレイはどこに戻せばいいですか？","ko":"부탁드려요! 다 마신 뒤에 쟁반은 어디에 돌려놓으면 되나요?","note":""},{"speaker":"하루카","role":"바리스타","jp":"<ruby>出口<rt>でぐち</rt></ruby>の<ruby>横<rt>よこ</rt></ruby>に<ruby>返却口<rt>へんきゃくぐち</rt></ruby>がございます。ごゆっくりどうぞ！","plain":"出口の横に返却口がございます。ごゆっくりどうぞ！","ko":"출구 옆에 반납구가 있습니다. 편히 쉬다 가세요!","note":""}]}],"konbini":[{"badge":"응용·옵션","title":"도시락·간식 결제와 교통카드 충전","lines":[{"speaker":"점원","role":"편의점 직원","jp":"いらっしゃいませ！<ruby>レジ袋<rt>れじぶくろ</rt></ruby>はご<ruby>利用<rt>りよう</rt></ruby>になりますか？","plain":"いらっしゃいませ！レジ袋はご利用になりますか？","ko":"어서 오세요! 비닐봉투 필요하신가요?","note":""},{"speaker":"나","role":"손님","jp":"はい、<ruby>一枚<rt>いちまい</rt></ruby>お<ruby>願<rt>ねが</rt></ruby>いします。あと、このお<ruby>弁当<rt>べんとう</rt></ruby>を<ruby>温<rt>あたた</rt></ruby>めてもらえますか？","plain":"はい、一枚お願いします。あと、このお弁当を温めてもらえますか？","ko":"네, 한 장 부탁드려요. 그리고 이 도시락 데워 주실 수 있나요?","note":""},{"speaker":"점원","role":"편의점 직원","jp":"かしこまりました。<ruby>割り箸<rt>わりばし</rt></ruby>とおしぼりはおつけしますか？","plain":"かしこまりました。割り箸とおしぼりはおつけしますか？","ko":"알겠습니다. 나무젓가락이랑 물티슈 넣어 드릴까요?","note":""},{"speaker":"나","role":"손님","jp":"お<ruby>願<rt>ねが</rt></ruby>いします！ついでにレジ<ruby>横<rt>よこ</rt></ruby>の<ruby>肉<rt>にく</rt></ruby>まんも<ruby>一<rt>ひと</rt></ruby>つください。","plain":"お願いします！ついでにレジ横の肉まんも一つください。","ko":"부탁드려요! 김에 계산대 옆 고기 호빵도 하나 주세요.","note":""},{"speaker":"점원","role":"편의점 직원","jp":"お<ruby>会計<rt>かいけい</rt></ruby>は<ruby>七<rt>なな</rt></ruby><ruby>百<rt>ひゃく</rt></ruby><ruby>八十<rt>はちじゅう</rt></ruby><ruby>円<rt>えん</rt></ruby>です。お<ruby>支払<rt>しはら</rt></ruby>い<ruby>方法<rt>ほうほう</rt></ruby>はいかがなさいますか？","plain":"お会計は七百八十円です。お支払い方法はいかがなさいますか？","ko":"계산 금액은 780엔입니다. 결제는 어떻게 하시겠어요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>交通系IC<rt>こうつうけいあいしー</rt></ruby>カードで<ruby>払<rt>はら</rt></ruby>いたいです。<ruby>千円<rt>せんえん</rt></ruby>チャージも<ruby>一緒<rt>いっしょ</rt></ruby>にできますか？","plain":"交通系ICカードで払いたいです。千円チャージも一緒にできますか？","ko":"교통카드로 결제하고 싶어요. 1,000엔 충전도 같이 할 수 있나요?","note":"편의점 계산대에서 바로 스이카·파스모 충전 가능!"}]},{"badge":"트러블·마무리","title":"복합기 티켓 발권과 역 출구 길 묻기","lines":[{"speaker":"나","role":"손님","jp":"すみません、<ruby>マルチコピー機<rt>まるちこぴーき</rt></ruby>でコンサートのチケットを<ruby>発券<rt>はっけん</rt></ruby>したいんですが。","plain":"すみません、マルチコピー機でコンサートのチケットを発券したいんですが。","ko":"저기요, 복합기에서 콘서트 티켓을 발권하고 싶은데요.","note":""},{"speaker":"점원","role":"편의점 직원","jp":"<ruby>予約番号<rt>よやくばんごう</rt></ruby>を<ruby>入力<rt>にゅうりょく</rt></ruby>すると<ruby>申込券<rt>もうしこみけん</rt></ruby>が<ruby>出<rt>で</rt></ruby>ますので、レジまでお<ruby>持<rt>も</rt></ruby>ちください。","plain":"予約番号を入力すると申込券が出ますので、レジまでお持ちください。","ko":"예약 번호를 입력하면 신청권이 나오니 계산대로 가져오시면 됩니다.","note":""},{"speaker":"나","role":"손님","jp":"わかりました！あと、ここから<ruby>渋谷駅<rt>しぶやえき</rt></ruby>の<ruby>南口<rt>みなみぐち</rt></ruby>まではどう<ruby>行<rt>い</rt></ruby>けばいいですか？","plain":"わかりました！あと、ここから渋谷駅の南口まではどう行けばいいですか？","ko":"알겠습니다! 그리고 여기서 시부야역 남쪽 출구까지는 어떻게 가면 되나요?","note":""},{"speaker":"점원","role":"편의점 직원","jp":"<ruby>店<rt>みせ</rt></ruby>を<ruby>出<rt>で</rt></ruby>て<ruby>次<rt>つぎ</rt></ruby>の<ruby>交差点<rt>こうさてん</rt></ruby>を<ruby>右<rt>みぎ</rt></ruby>に<ruby>曲<rt>ま</rt></ruby>がってください。<ruby>二<rt>ふた</rt></ruby>つ<ruby>目<rt>め</rt></ruby>の<ruby>信号<rt>しんごう</rt></ruby>を<ruby>渡<rt>わた</rt></ruby>るとすぐです。","plain":"店を出て次の交差点を右に曲がってください。二つ目の信号を渡るとすぐです。","ko":"가게를 나와 다음 교차로에서 오른쪽으로 도세요. 두 번째 신호등을 건너면 바로예요.","note":""},{"speaker":"나","role":"손님","jp":"<ruby>雨<rt>あめ</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>ってきたんですが、<ruby>地下通路<rt>ちかつうろ</rt></ruby>から<ruby>行<rt>い</rt></ruby>くこともできますか？","plain":"雨が降ってきたんですが、地下通路から行くこともできますか？","ko":"비가 오기 시작했는데 지하 통로로 갈 수도 있나요?","note":""},{"speaker":"점원","role":"편의점 직원","jp":"はい、あの<ruby>角<rt>かど</rt></ruby>の<ruby>階段<rt>かいだん</rt></ruby>から<ruby>地下通路<rt>ちかつうろ</rt></ruby>に<ruby>入<rt>い</rt></ruby>れますよ。お<ruby>気<rt>き</rt></ruby>をつけて！","plain":"はい、あの角の階段から地下通路に入れますよ。お気をつけて！","ko":"네, 저 모퉁이 계단으로 지하 통로에 들어가실 수 있어요. 조심히 가세요!","note":"「角(かど)」는 길 모퉁이."}]}],"hotel":[{"badge":"응용·옵션","title":"노천탕·가족탕 예약과 유카타 교체","lines":[{"speaker":"프런트","role":"료칸 직원","jp":"お<ruby>荷物<rt>にもつ</rt></ruby>はお<ruby>部屋<rt>へや</rt></ruby>までお<ruby>運<rt>はこ</rt></ruby>びしました。<ruby>温泉<rt>おんせん</rt></ruby>のご<ruby>案内<rt>あんない</rt></ruby>をいたしますね。","plain":"お荷物はお部屋までお運びしました。温泉のご案内をいたしますね。","ko":"짐은 객실로 옮겨 두었습니다. 온천 안내를 해 드릴게요.","note":""},{"speaker":"나","role":"투숙객","jp":"ありがとうございます！<ruby>露天風呂<rt>ろてんぶろ</rt></ruby>と<ruby>貸切風呂<rt>かしきりぶろ</rt></ruby>は<ruby>何時<rt>なんじ</rt></ruby>まで<ruby>入<rt>い</rt></ruby>れますか？","plain":"ありがとうございます！露天風呂と貸切風呂は何時まで入れますか？","ko":"감사합니다! 노천탕이랑 가족탕은 몇 시까지 이용할 수 있나요?","note":""},{"speaker":"프런트","role":"료칸 직원","jp":"<ruby>露天風呂<rt>ろてんぶろ</rt></ruby>は<ruby>夜<rt>よる</rt></ruby><ruby>十二時<rt>じゅうにじ</rt></ruby>までです。<ruby>貸切風呂<rt>かしきりぶろ</rt></ruby>は<ruby>予約制<rt>よやくせい</rt></ruby>で、<ruby>今夜<rt>こんや</rt></ruby><ruby>九時<rt>くじ</rt></ruby>が<ruby>空<rt>あ</rt></ruby>いていますよ。","plain":"露天風呂は夜十二時までです。貸切風呂は予約制で、今夜九時が空いていますよ。","ko":"노천탕은 밤 12시까지입니다. 가족탕은 예약제인데 오늘 밤 9시가 비어 있어요.","note":"「空いて(あいて)」= 비어 있다."},{"speaker":"나","role":"투숙객","jp":"では<ruby>九時<rt>くじ</rt></ruby>でお<ruby>願<rt>ねが</rt></ruby>いします！あと、<ruby>浴衣<rt>ゆかた</rt></ruby>のサイズをLに<ruby>交換<rt>こうかん</rt></ruby>できますか？","plain":"では九時でお願いします！あと、浴衣のサイズをLに交換できますか？","ko":"그럼 9시로 부탁드려요! 그리고 유카타 사이즈를 L로 바꿀 수 있나요?","note":""},{"speaker":"프런트","role":"료칸 직원","jp":"もちろんです。<ruby>夕食<rt>ゆうしょく</rt></ruby>の<ruby>間<rt>ま</rt></ruby>に<ruby>布団<rt>ふとん</rt></ruby>も<ruby>敷<rt>し</rt></ruby>いておきますね。","plain":"もちろんです。夕食の間に布団も敷いておきますね。","ko":"물론이죠. 저녁 식사하시는 동안 이불도 깔아 두겠습니다.","note":""},{"speaker":"나","role":"투숙객","jp":"<ruby>助<rt>たす</rt></ruby>かります！バスタオルを<ruby>追加<rt>ついか</rt></ruby>で<ruby>一枚<rt>いちまい</rt></ruby>いただくことはできますか？","plain":"助かります！バスタオルを追加で一枚いただくことはできますか？","ko":"감사합니다! 큰 수건을 추가로 한 장 더 받을 수 있을까요?","note":""}]},{"badge":"트러블·마무리","title":"객실 기기 문의·레이트 체크아웃·송영 버스","lines":[{"speaker":"나","role":"투숙객","jp":"すみません、<ruby>部屋<rt>へや</rt></ruby>のドライヤーが<ruby>動<rt>うご</rt></ruby>かなくて、Wi-Fiのパスワードも<ruby>確認<rt>かくにん</rt></ruby>したいのですが。","plain":"すみません、部屋のドライヤーが動かなくて、Wi-Fiのパスワードも確認したいのですが。","ko":"저기요, 방 드라이어가 작동하지 않고 와이파이 비밀번호도 확인하고 싶은데요.","note":""},{"speaker":"프런트","role":"료칸 직원","jp":"<ruby>申し訳<rt>もうしわけ</rt></ruby>ございません！すぐ<ruby>新<rt>あたら</rt></ruby>しいドライヤーをお<ruby>持<rt>も</rt></ruby>ちします。パスワードは<ruby>机<rt>つくえ</rt></ruby>の<ruby>案内<rt>あんない</rt></ruby>に<ruby>書<rt>か</rt></ruby>いてあります。","plain":"申し訳ございません！すぐ新しいドライヤーをお持ちします。パスワードは机の案内に書いてあります。","ko":"죄송합니다! 바로 새 드라이어를 가져다드릴게요. 비밀번호는 책상 안내문에 적혀 있습니다.","note":""},{"speaker":"나","role":"투숙객","jp":"ありがとうございます。ちなみに<ruby>明日<rt>あした</rt></ruby>のレイトチェックアウトは<ruby>可能<rt>かのう</rt></ruby>ですか？","plain":"ありがとうございます。ちなみに明日のレイトチェックアウトは可能ですか？","ko":"감사합니다. 혹시 내일 레이트 체크아웃이 가능한가요?","note":""},{"speaker":"프런트","role":"료칸 직원","jp":"<ruby>十二時<rt>じゅうにじ</rt></ruby>まで<ruby>延長<rt>えんちょう</rt></ruby>できます。<ruby>延長料金<rt>えんちょうりょうきん</rt></ruby>は<ruby>二千円<rt>にせんえん</rt></ruby>で、<ruby>入湯税<rt>にゅうとうぜい</rt></ruby>と<ruby>一緒<rt>いっしょ</rt></ruby>にお<ruby>会計<rt>かいけい</rt></ruby>になります。","plain":"十二時まで延長できます。延長料金は二千円で、入湯税と一緒にお会計になります。","ko":"12시까지 연장 가능합니다. 연장 요금은 2천 엔이고 입탕세와 함께 결제됩니다.","note":"일본 온천 료칸은 체크아웃 시 1인당 약 150엔의 입탕세(入湯税)를 따로 받아요."},{"speaker":"나","role":"투숙객","jp":"わかりました。<ruby>駅<rt>えき</rt></ruby>までの<ruby>送迎バス<rt>そうげいばす</rt></ruby>は<ruby>何時<rt>なんじ</rt></ruby>に<ruby>出<rt>で</rt></ruby>ますか？","plain":"わかりました。駅までの送迎バスは何時に出ますか？","ko":"알겠습니다. 역까지 가는 송영 버스는 몇 시에 출발하나요?","note":""},{"speaker":"프런트","role":"료칸 직원","jp":"<ruby>毎時<rt>まいじ</rt></ruby><ruby>三十分<rt>さんじゅっぷん</rt></ruby>に<ruby>出発<rt>しゅっぱつ</rt></ruby>します。<ruby>十二時半<rt>じゅうにじはん</rt></ruby>の<ruby>便<rt>びん</rt></ruby>をご<ruby>予約<rt>よやく</rt></ruby>しておきましょうか？","plain":"毎時三十分に出発します。十二時半の便をご予約しておきましょうか？","ko":"매시 30분에 출발합니다. 12시 반 편으로 예약해 둘까요?","note":""}]}],"shopping":[{"badge":"응용·옵션","title":"재고·소재 문의와 사이즈 착용감 피드백","lines":[{"speaker":"점원","role":"매장 스태프","jp":"いらっしゃいませ！<ruby>気<rt>き</rt></ruby>になるアイテムがあればお<ruby>声<rt>こえ</rt></ruby>がけくださいね。","plain":"いらっしゃいませ！気になるアイテムがあればお声がけくださいね。","ko":"어서 오세요! 마음에 드는 상품이 있으면 말씀해 주세요.","note":""},{"speaker":"나","role":"손님","jp":"マネキンが<ruby>着<rt>き</rt></ruby>ているジャケットのMサイズの<ruby>在庫<rt>ざいこ</rt></ruby>はありますか？","plain":"マネキンが着ているジャケットのMサイズの在庫はありますか？","ko":"마네킹이 입고 있는 재킷 M사이즈 재고가 있나요?","note":""},{"speaker":"점원","role":"매장 스태프","jp":"はい、<ruby>奥<rt>おく</rt></ruby>から<ruby>新<rt>あたら</rt></ruby>しいものをお<ruby>持<rt>も</rt></ruby>ちします。<ruby>試着室<rt>しちゃくしつ</rt></ruby>はこちらです！","plain":"はい、奥から新しいものをお持ちします。試着室はこちらです！","ko":"네, 안쪽에서 새 상품으로 가져다드릴게요. 탈의실은 이쪽입니다!","note":""},{"speaker":"나","role":"손님","jp":"<ruby>着<rt>き</rt></ruby>てみたんですが、<ruby>肩<rt>かた</rt></ruby>が<ruby>少<rt>すこ</rt></ruby>しきついです。Lサイズはありますか？","plain":"着てみたんですが、肩が少しきついです。Lサイズはありますか？","ko":"입어 봤는데 어깨가 조금 꽉 끼네요. L사이즈 있나요?","note":"「きつい(꽉 끼다)」 ↔ 「ゆるい(헐렁하다)」"},{"speaker":"점원","role":"매장 스태프","jp":"ございます！こちらは<ruby>綿<rt>めん</rt></ruby><ruby>百<rt>ひゃく</rt></ruby>パーセントなので<ruby>家<rt>いえ</rt></ruby>で<ruby>洗<rt>あら</rt></ruby>えますよ。","plain":"ございます！こちらは綿百パーセントなので家で洗えますよ。","ko":"있습니다! 이 제품은 면 100%라서 집에서 세탁하실 수 있어요.","note":""},{"speaker":"나","role":"손님","jp":"Lのほうがちょうどいいですね！ズボンの<ruby>丈<rt>たけ</rt></ruby>のお<ruby>直<rt>なお</rt></ruby>しもできますか？","plain":"Lのほうがちょうどいいですね！ズボンの丈のお直しもできますか？","ko":"L 쪽이 딱 좋네요! 바지 기장 수선도 가능한가요?","note":""}]},{"badge":"트러블·마무리","title":"면세 절차·소모품 밀봉과 반품 규정","lines":[{"speaker":"나","role":"손님","jp":"これとこれを<ruby>買<rt>か</rt></ruby>いたいです。セール<ruby>品<rt>ひん</rt></ruby>も<ruby>免税<rt>めんぜい</rt></ruby>の<ruby>対象<rt>たいしょう</rt></ruby>になりますか？","plain":"これとこれを買いたいです。セール品も免税の対象になりますか？","ko":"이거랑 이거 사고 싶어요. 세일 상품도 면세 대상이 되나요?","note":""},{"speaker":"점원","role":"매장 스태프","jp":"はい、<ruby>合計<rt>ごうけい</rt></ruby><ruby>五千円<rt>ごせんえん</rt></ruby><ruby>以上<rt>いじょう</rt></ruby>なので<ruby>免税<rt>めんぜい</rt></ruby>できます。パスポートをお<ruby>願<rt>ねが</rt></ruby>いします。","plain":"はい、合計五千円以上なので免税できます。パスポートをお願いします。","ko":"네, 합계 5천 엔 이상이라 면세 가능합니다. 여권을 부탁드려요.","note":""},{"speaker":"나","role":"손님","jp":"はい、どうぞ。クレジットカードの<ruby>一括払<rt>いっかつばら</rt></ruby>いでお<ruby>願<rt>ねが</rt></ruby>いします。","plain":"はい、どうぞ。クレジットカードの一括払いでお願いします。","ko":"네, 여기 있어요. 신용카드 일시불로 부탁드립니다.","note":""},{"speaker":"점원","role":"매장 스태프","jp":"<ruby>承知<rt>しょうち</rt></ruby>しました。<ruby>化粧品<rt>けしょうひん</rt></ruby>の<ruby>消耗品<rt>しょうもうひん</rt></ruby>は<ruby>出国<rt>しゅっこく</rt></ruby>まで<ruby>開<rt>あ</rt></ruby>けられない<ruby>専用<rt>せんよう</rt></ruby><ruby>袋<rt>ふくろ</rt></ruby>に<ruby>密封<rt>みっぷう</rt></ruby>しますね。","plain":"承知しました。化粧品の消耗品は出国まで開けられない専用袋に密封しますね。","ko":"알겠습니다. 화장품 같은 소모품은 출국 전까지 열면 안 되는 전용 봉투에 밀봉해 드릴게요.","note":"면세 소모품은 일본 체류 중 개봉하면 과세 대상이 되니 주의!"},{"speaker":"나","role":"손님","jp":"わかりました。もしサイズが<ruby>合<rt>あ</rt></ruby>わなかったら<ruby>交換<rt>こうかん</rt></ruby>や<ruby>返品<rt>へんぴん</rt></ruby>はできますか？","plain":"わかりました。もしサイズが合わなかったら交換や返品はできますか？","ko":"알겠습니다. 혹시 사이즈가 안 맞으면 교환이나 반품이 되나요?","note":""},{"speaker":"점원","role":"매장 스태프","jp":"<ruby>免税品<rt>めんぜいひん</rt></ruby>とセール<ruby>品<rt>ひん</rt></ruby>は<ruby>返品<rt>へんぴん</rt></ruby>できませんが、<ruby>タグ付<rt>たぐつ</rt></ruby>きなら<ruby>当日中<rt>とうじつちゅう</rt></ruby>の<ruby>交換<rt>こうかん</rt></ruby>は<ruby>可能<rt>かのう</rt></ruby>です。","plain":"免税品とセール品は返品できませんが、タグ付きなら当日中の交換は可能です。","ko":"면세품과 세일품은 반품이 불가하지만, 택이 붙어 있으면 당일 교환은 가능합니다.","note":""}]}],"izakaya":[{"badge":"응용·옵션","title":"하이볼·야키토리(소금/양념)와 앞접시 요청","lines":[{"speaker":"점원","role":"이자카야 직원","jp":"お<ruby>待<rt>ま</rt></ruby>たせしました！お<ruby>通<rt>とお</rt></ruby>しの<ruby>枝豆<rt>えだまめ</rt></ruby>と<ruby>生ビール<rt>なまびーる</rt></ruby><ruby>二<rt>ふた</rt></ruby>つです。","plain":"お待たせしました！お通しの枝豆と生ビール二つです。","ko":"오래 기다리셨습니다! 기본 안주 에다마메랑 생맥주 두 잔입니다.","note":"「お通し(おとおし)」는 일본 이자카야의 자리세 겸 기본 안주."},{"speaker":"나","role":"손님","jp":"ありがとうございます！<ruby>焼<rt>や</rt></ruby>き<ruby>鳥<rt>とり</rt></ruby>の<ruby>盛<rt>も</rt></ruby>り<ruby>合<rt>あ</rt></ruby>わせと<ruby>鶏<rt>とり</rt></ruby>の<ruby>唐揚<rt>からあ</rt></ruby>げをお<ruby>願<rt>ねが</rt></ruby>いします。","plain":"ありがとうございます！焼き鳥の盛り合わせと鶏の唐揚げをお願いします。","ko":"감사합니다! 야키토리 모둠이랑 닭 가라아게 부탁드려요.","note":""},{"speaker":"점원","role":"이자카야 직원","jp":"<ruby>焼<rt>や</rt></ruby>き<ruby>鳥<rt>とり</rt></ruby>は<ruby>塩<rt>しお</rt></ruby>とタレのどちらになさいますか？","plain":"焼き鳥は塩とタレのどちらになさいますか？","ko":"야키토리는 소금과 양념 중 어느 쪽으로 하시겠어요?","note":""},{"speaker":"나","role":"손님","jp":"つくねはタレで、あとは<ruby>全部<rt>ぜんぶ</rt></ruby><ruby>塩<rt>しお</rt></ruby>にしてください！あと<ruby>取り皿<rt>とりざら</rt></ruby>を<ruby>二枚<rt>にまい</rt></ruby>いただけますか？","plain":"つくねはタレで、あとは全部塩にしてください！あと取り皿を二枚いただけますか？","ko":"츠쿠네는 양념으로, 나머지는 전부 소금으로 해 주세요! 그리고 앞접시 두 개 주실 수 있나요?","note":""},{"speaker":"점원","role":"이자카야 직원","jp":"かしこまりました！お<ruby>飲<rt>の</rt></ruby>み<ruby>物<rt>もの</rt></ruby>のおかわりもいつでも<ruby>呼<rt>よ</rt></ruby>んでくださいね。","plain":"かしこまりました！お飲み物のおかわりもいつでも呼んでくださいね。","ko":"알겠습니다! 음료 추가 주문도 언제든 불러 주세요.","note":""},{"speaker":"나","role":"손님","jp":"じゃあ、<ruby>次<rt>つぎ</rt></ruby>はレモンサワーと<ruby>梅酒<rt>うめしゅ</rt></ruby>のソーダ<ruby>割<rt>わ</rt></ruby>りをお<ruby>願<rt>ねが</rt></ruby>いします！","plain":"じゃあ、次はレモンサワーと梅酒のソーダ割りをお願いします！","ko":"그럼 다음은 레몬 사와랑 매실주 탄산수 타서 부탁드려요!","note":""}]},{"badge":"트러블·마무리","title":"라스트 오더·마무리 식사(시메)와 계산","lines":[{"speaker":"점원","role":"이자카야 직원","jp":"すみません、お<ruby>食事<rt>しょくじ</rt></ruby>のラストオーダーになりますが<ruby>追加<rt>ついか</rt></ruby>はございますか？","plain":"すみません、お食事のラストオーダーになりますが追加はございますか？","ko":"실례합니다, 식사 마지막 주문 시간인데 추가하실 메뉴 있으신가요?","note":""},{"speaker":"나","role":"손님","jp":"じゃあ、シメに<ruby>梅干<rt>うめぼ</rt></ruby>しのお<ruby>茶漬<rt>ちゃづ</rt></ruby>けを<ruby>二<rt>ふた</rt></ruby>つと、<ruby>ウーロン茶<rt>うーろんちゃ</rt></ruby>をお<ruby>願<rt>ねが</rt></ruby>いします。","plain":"じゃあ、シメに梅干しのお茶漬けを二つと、ウーロン茶をお願いします。","ko":"그럼 마무리로 매실장아찌 오차즈케 두 개랑 우롱차 부탁드려요.","note":"술자리 마지막 식사를 일본어로 「シメ(시메)」라고 해요."},{"speaker":"점원","role":"이자카야 직원","jp":"かしこまりました！すぐお<ruby>作<rt>つく</rt></ruby>りしますね。","plain":"かしこまりました！すぐお作りしますね。","ko":"알겠습니다! 금방 만들어 드릴게요.","note":""},{"speaker":"나","role":"손님","jp":"ごちそうさまでした！すみません、お<ruby>会計<rt>かいけい</rt></ruby>をお<ruby>願<rt>ねが</rt></ruby>いします。","plain":"ごちそうさまでした！すみません、お会計をお願いします。","ko":"잘 먹었습니다! 저기요, 계산 부탁드려요.","note":""},{"speaker":"점원","role":"이자카야 직원","jp":"テーブル<ruby>会計<rt>かいけい</rt></ruby>になります。<ruby>合計<rt>ごうけい</rt></ruby><ruby>六千四百円<rt>ろくせんよんひゃくえん</rt></ruby>です。","plain":"テーブル会計になります。合計六千四百円です。","ko":"테이블에서 계산해 드립니다. 합계 6,400엔입니다.","note":""},{"speaker":"나","role":"손님","jp":"カードで<ruby>別々<rt>べつべつ</rt></ruby>に<ruby>割<rt>わ</rt></ruby>り<ruby>勘<rt>かん</rt></ruby>にできますか？<ruby>無理<rt>むり</rt></ruby>ならまとめて<ruby>払<rt>はら</rt></ruby>います。","plain":"カードで別々に割り勘にできますか？無理ならまとめて払います。","ko":"카드로 따로따로 더치페이 되나요? 안 되면 한꺼번에 낼게요.","note":""}]}],"hobby":[{"badge":"응용·옵션","title":"영화·카페 투어 주말 약속 정하기","lines":[{"speaker":"미나","role":"일본 친구","jp":"<ruby>今度<rt>こんど</rt></ruby>の<ruby>土曜日<rt>どようび</rt></ruby>、<ruby>何<rt>なに</rt></ruby>か<ruby>予定<rt>よてい</rt></ruby>ある？<ruby>久<rt>ひさ</rt></ruby>しぶりに<ruby>会<rt>あ</rt></ruby>わない？","plain":"今度の土曜日、何か予定ある？久しぶりに会わない？","ko":"이번 토요일에 무슨 예정 있어? 오랜만에 안 만날래?","note":""},{"speaker":"나","role":"나","jp":"<ruby>土曜日<rt>どようび</rt></ruby>は<ruby>空<rt>あ</rt></ruby>いてるよ！<ruby>映画館<rt>えいがかん</rt></ruby>で<ruby>話題<rt>わだい</rt></ruby>のアニメを<ruby>観<rt>み</rt></ruby>ない？","plain":"土曜日は空いてるよ！映画館で話題のアニメを観ない？","ko":"토요일은 비어 있어! 영화관에서 화제의 애니 보지 않을래?","note":""},{"speaker":"미나","role":"일본 친구","jp":"いいね！<ruby>字幕版<rt>じまくばん</rt></ruby>と<ruby>吹<rt>ふ</rt></ruby>き<ruby>替<rt>か</rt></ruby>え<ruby>版<rt>ばん</rt></ruby>、どっちがいい？<ruby>私<rt>わたし</rt></ruby>はネタバレ<ruby>踏<rt>ふ</rt></ruby>む<ruby>前<rt>まえ</rt></ruby>に<ruby>早<rt>はや</rt></ruby>く<ruby>観<rt>み</rt></ruby>たいんだ！","plain":"いいね！字幕版と吹き替え版、どっちがいい？私はネタバレ踏む前に早く観たいんだ！","ko":"좋아! 자막판이랑 더빙판 중에 뭐가 좋아? 난 스포 당하기 전에 빨리 보고 싶어!","note":"「ネタバレ」= 스포일러."},{"speaker":"나","role":"나","jp":"オリジナル<ruby>音声<rt>おんせい</rt></ruby>がいいな。<ruby>映画<rt>えいが</rt></ruby>のあと、<ruby>口コミ<rt>くちこみ</rt></ruby>で<ruby>評判<rt>ひょうばん</rt></ruby>の<ruby>穴場<rt>あなば</rt></ruby>カフェに<ruby>行<rt>い</rt></ruby>こうよ！","plain":"オリジナル音声がいいな。映画のあと、口コミで評判の穴場カフェに行こうよ！","ko":"오리지널 음성이 좋아. 영화 끝나고 리뷰 좋은 숨은 명소 카페 가자!","note":""},{"speaker":"미나","role":"일본 친구","jp":"<ruby>最高<rt>さいこう</rt></ruby>！そのカフェのパフェ、すごく<ruby>映<rt>ば</rt></ruby>えるって<ruby>聞<rt>き</rt></ruby>いたよ。どこで<ruby>待ち合<rt>まちあ</rt></ruby>わせする？","plain":"最高！そのカフェのパフェ、すごく映えるって聞いたよ。どこで待ち合わせする？","ko":"최고야! 그 카페 파르페 사진 엄청 잘 나온다더라. 어디서 만날까?","note":"「映える(ばえる)」= 사진발이 잘 받다."},{"speaker":"나","role":"나","jp":"<ruby>二時<rt>にじ</rt></ruby>に<ruby>新宿駅<rt>しんじゅくえき</rt></ruby>の<ruby>東口<rt>ひがしぐち</rt></ruby>で<ruby>待ち合<rt>まちあ</rt></ruby>わせしよう！<ruby>楽<rt>たの</rt></ruby>しみにしてるね。","plain":"二時に新宿駅の東口で待ち合わせしよう！楽しみにしてるね。","ko":"2시에 신주쿠역 동쪽 출구에서 만나자! 기대할게.","note":""}]},{"badge":"트러블·마무리","title":"갑작스런 일정 변경과 다음 약속 잡기","lines":[{"speaker":"나","role":"나","jp":"ごめん、ミナ！<ruby>急<rt>きゅう</rt></ruby>に<ruby>仕事<rt>しごと</rt></ruby>が<ruby>入<rt>はい</rt></ruby>っちゃって、<ruby>土曜日<rt>どようび</rt></ruby>に<ruby>行<rt>い</rt></ruby>けなくなりそうなんだ。","plain":"ごめん、ミナ！急に仕事が入っちゃって、土曜日に行けなくなりそうなんだ。","ko":"미안해 미나야! 갑자기 일이 생겨서 토요일에 못 갈 것 같아.","note":""},{"speaker":"미나","role":"일본 친구","jp":"ええっ、<ruby>大変<rt>たいへん</rt></ruby>だね！<ruby>全然<rt>ぜんぜん</rt></ruby><ruby>大丈夫<rt>だいじょうぶ</rt></ruby>だよ、<ruby>無理<rt>むり</rt></ruby>しないでね。","plain":"ええっ、大変だね！全然大丈夫だよ、無理しないでね。","ko":"어머, 큰일이네! 전혀 괜찮아, 무리하지 마.","note":""},{"speaker":"나","role":"나","jp":"<ruby>直前<rt>ちょくぜん</rt></ruby>にドタキャンみたいになって<ruby>本当<rt>ほんとう</rt></ruby>にごめん！<ruby>日曜日<rt>にちようび</rt></ruby>の<ruby>午後<rt>ごご</rt></ruby>なら<ruby>都合<rt>つごう</rt></ruby>がいいんだけど、どう？","plain":"直前にドタキャンみたいになって本当にごめん！日曜日の午後なら都合がいいんだけど、どう？","ko":"직전에 갑자기 취소하는 꼴이 돼서 정말 미안해! 일요일 오후면 시간 괜찮은데 어때?","note":"「ドタキャン」= 약속 직전 갑작스런 취소."},{"speaker":"미나","role":"일본 친구","jp":"<ruby>日曜日<rt>にちようび</rt></ruby>も<ruby>暇<rt>ひま</rt></ruby>だよ！じゃあ<ruby>天気<rt>てんき</rt></ruby>も<ruby>良<rt>よ</rt></ruby>さそうだし、<ruby>鎌倉<rt>かまくら</rt></ruby>へ<ruby>日帰<rt>ひがえ</rt></ruby>りドライブにしない？","plain":"日曜日も暇だよ！じゃあ天気も良さそうだし、鎌倉へ日帰りドライブにしない？","ko":"일요일도 한가해! 그럼 날씨도 좋을 것 같고 가마쿠라 당일치기 드라이브 어때?","note":""},{"speaker":"나","role":"나","jp":"わあ、いいリフレッシュになりそう！<ruby>運転<rt>うんてん</rt></ruby>ありがとう、コーヒーは<ruby>私<rt>わたし</rt></ruby>がおごるね。","plain":"わあ、いいリフレッシュになりそう！運転ありがとう、コーヒーは私がおごるね。","ko":"와, 제대로 기분 전환되겠다! 운전 고마워, 커피는 내가 살게.","note":""},{"speaker":"미나","role":"일본 친구","jp":"やった！じゃあ<ruby>日曜日<rt>にちようび</rt></ruby>の<ruby>朝<rt>あさ</rt></ruby><ruby>十時<rt>じゅうじ</rt></ruby>に<ruby>連絡<rt>れんらく</rt></ruby>するね。","plain":"やった！じゃあ日曜日の朝十時に連絡するね。","ko":"신난다! 그럼 일요일 아침 10시에 연락할게.","note":""}]}],"hair":[{"badge":"응용·옵션","title":"염색·트리트먼트와 곱슬머리 고민 상담","lines":[{"speaker":"료스케","role":"디자이너","jp":"<ruby>今日<rt>きょう</rt></ruby>はカットのほかに、カラーやトリートメントもされますか？","plain":"今日はカットのほかに、カラーやトリートメントもされますか？","ko":"오늘은 커트 외에 염색이나 트리트먼트도 하시겠어요?","note":""},{"speaker":"나","role":"손님","jp":"はい、<ruby>少<rt>すこ</rt></ruby>し<ruby>明<rt>あか</rt></ruby>るめのブラウンでリタッチとトリートメントをお<ruby>願<rt>ねが</rt></ruby>いしたいです。","plain":"はい、少し明るめのブラウンでリタッチとトリートメントをお願いしたいです。","ko":"네, 조금 밝은 브라운으로 뿌리 염색이랑 트리트먼트 부탁드리고 싶어요.","note":""},{"speaker":"료스케","role":"디자이너","jp":"かしこまりました！<ruby>髪<rt>かみ</rt></ruby>のお<ruby>悩<rt>なや</rt></ruby>みはありますか？","plain":"かしこまりました！髪のお悩みはありますか？","ko":"알겠습니다! 모발 고민이 있으신가요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>湿気<rt>しっけ</rt></ruby>があるとくせ<ruby>毛<rt>げ</rt></ruby>が<ruby>広<rt>ひろ</rt></ruby>がりやすくて、<ruby>毛先<rt>けさき</rt></ruby>のダメージも<ruby>気<rt>き</rt></ruby>になります。","plain":"湿気があるとくせ毛が広がりやすくて、毛先のダメージも気になります。","ko":"습기가 있으면 곱슬머리가 잘 부스스해지고, 머리끝 손상도 신경 쓰여요.","note":""},{"speaker":"료스케","role":"디자이너","jp":"それなら<ruby>内側<rt>うちがわ</rt></ruby>を<ruby>少<rt>すこ</rt></ruby>しすいて、<ruby>軽<rt>かる</rt></ruby>めのレイヤーを<ruby>入<rt>い</rt></ruby>れると<ruby>自分<rt>じぶん</rt></ruby>でブローしやすいですよ。","plain":"それなら内側を少しすいて、軽めのレイヤーを入れると自分でブローしやすいですよ。","ko":"그렇다면 안쪽 숱을 조금 치고 가볍게 층을 내면 혼자 드라이하기 편해요.","note":""},{"speaker":"나","role":"손님","jp":"いいですね！サイドは<ruby>耳<rt>みみ</rt></ruby>にかかるくらい<ruby>残<rt>のこ</rt></ruby>して、<ruby>襟足<rt>えりあし</rt></ruby>はすっきりさせてください。","plain":"いいですね！サイドは耳にかかるくらい残して、襟足はすっきりさせてください。","ko":"좋네요! 옆머리는 귀에 걸릴 정도로 남기고 뒷목은 깔끔하게 해 주세요.","note":""}]},{"badge":"트러블·마무리","title":"마무리 스타일링 확인과 다음 예약·지명","lines":[{"speaker":"료스케","role":"디자이너","jp":"お<ruby>疲<rt>つか</rt></ruby>れ<ruby>様<rt>さま</rt></ruby>でした！<ruby>鏡<rt>かがみ</rt></ruby>で<ruby>後<rt>あと</rt></ruby>ろの<ruby>仕上<rt>しあ</rt></ruby>がりも<ruby>確認<rt>かくにん</rt></ruby>してみてください。","plain":"お疲れ様でした！鏡で後ろの仕上がりも確認してみてください。","ko":"수고하셨습니다! 거울로 뒷모습 완성도 확인해 보세요.","note":""},{"speaker":"나","role":"손님","jp":"わあ、すごく<ruby>軽<rt>かる</rt></ruby>くなりました！<ruby>前髪<rt>まえがみ</rt></ruby>だけもう<ruby>少<rt>すこ</rt></ruby>しだけ<ruby>短<rt>みじか</rt></ruby>くしてもらえますか？","plain":"わあ、すごく軽くなりました！前髪だけもう少しだけ短くしてもらえますか？","ko":"와, 엄청 가벼워졌어요! 앞머리만 조금만 더 짧게 해 주실 수 있나요?","note":""},{"speaker":"료스케","role":"디자이너","jp":"もちろんです、<ruby>五<rt>ご</rt></ruby>ミリほど<ruby>整<rt>ととの</rt></ruby>えますね。<ruby>仕上<rt>しあ</rt></ruby>げにヘアオイルかワックスはつけますか？","plain":"もちろんです、五ミリほど整えますね。仕上げにヘアオイルかワックスはつけますか？","ko":"물론이죠, 5밀리 정도 다듬을게요. 마무리로 헤어 오일이나 왁스 발라 드릴까요?","note":""},{"speaker":"나","role":"손님","jp":"ヘアオイルだけでお<ruby>願<rt>ねが</rt></ruby>いします！<ruby>家<rt>いえ</rt></ruby>でもヘアアイロンを<ruby>使<rt>つか</rt></ruby>ったほうがいいですか？","plain":"ヘアオイルだけでお願いします！家でもヘアアイロンを使ったほうがいいですか？","ko":"헤어 오일만 발라 주세요! 집에서도 고데기를 쓰는 게 좋을까요?","note":""},{"speaker":"료스케","role":"디자이너","jp":"<ruby>毛先<rt>けさき</rt></ruby>を<ruby>軽<rt>かる</rt></ruby>く<ruby>内巻<rt>うちま</rt></ruby>きにするだけでまとまりますよ。","plain":"毛先を軽く内巻きにするだけでまとまりますよ。","ko":"머리끝만 살짝 안쪽으로 말아 주시면 차분하게 정리돼요.","note":""},{"speaker":"나","role":"손님","jp":"すごく<ruby>気<rt>き</rt></ruby>に<ruby>入<rt>はい</rt></ruby>りました！<ruby>次回<rt>じかい</rt></ruby>もリョウスケさんを<ruby>指名<rt>しめい</rt></ruby>したいです。","plain":"すごく気に入りました！次回もリョウスケさんを指名したいです。","ko":"정말 마음에 들어요! 다음에도 료스케 씨로 지명하고 싶어요.","note":""}]}],"hospital":[{"badge":"응용·옵션","title":"병원 초진 접수와 상세 증상 설명","lines":[{"speaker":"접수원","role":"병원 접수","jp":"いらっしゃいませ。<ruby>診察券<rt>しんさつけん</rt></ruby>と<ruby>保険証<rt>ほけんしょう</rt></ruby>はお<ruby>持<rt>も</rt></ruby>ちですか？","plain":"いらっしゃいませ。診察券と保険証はお持ちですか？","ko":"어서 오세요. 진료카드와 건강보험증 가지고 계신가요?","note":""},{"speaker":"나","role":"환자","jp":"<ruby>初診<rt>しょしん</rt></ruby>なので<ruby>診察券<rt>しんさつけん</rt></ruby>はまだありません。<ruby>保険証<rt>ほけんしょう</rt></ruby>はこちらです。","plain":"初診なので診察券はまだありません。保険証はこちらです。","ko":"초진이라 진료카드가 아직 없어요. 보험증은 여기 있습니다.","note":""},{"speaker":"접수원","role":"병원 접수","jp":"ありがとうございます。こちらの<ruby>問診票<rt>もんしんひょう</rt></ruby>にご<ruby>記入<rt>きにゅう</rt></ruby>いただき、<ruby>体温計<rt>たいおんけい</rt></ruby>で<ruby>熱<rt>ねつ</rt></ruby>を<ruby>測<rt>はか</rt></ruby>ってください。","plain":"ありがとうございます。こちらの問診票にご記入いただき、体温計で熱を測ってください。","ko":"감사합니다. 이 문진표에 작성해 주시고 체온계로 열을 재 주세요.","note":""},{"speaker":"의사","role":"담당 의사","jp":"こんにちは。<ruby>今日<rt>きょう</rt></ruby>はどのような<ruby>症状<rt>しょうじょう</rt></ruby>ですか？","plain":"こんにちは。今日はどのような症状ですか？","ko":"안녕하세요. 오늘은 어떤 증상으로 오셨나요?","note":""},{"speaker":"나","role":"환자","jp":"<ruby>昨日<rt>きのう</rt></ruby>から<ruby>急<rt>きゅう</rt></ruby>に<ruby>寒気<rt>さむけ</rt></ruby>と<ruby>頭痛<rt>ずつう</rt></ruby>がして、<ruby>咳<rt>せき</rt></ruby>と<ruby>鼻水<rt>はなみず</rt></ruby>も<ruby>止<rt>と</rt></ruby>まりません。","plain":"昨日から急に寒気と頭痛がして、咳と鼻水も止まりません。","ko":"어제부터 갑자기 오한과 두통이 있고, 기침과 콧물도 멈추지 않아요.","note":"「寒気(さむけ)」= 오한 (かんき 아님 주의!)."},{"speaker":"의사","role":"담당 의사","jp":"<ruby>喉<rt>のど</rt></ruby>が<ruby>少<rt>すこ</rt></ruby>し<ruby>赤<rt>あか</rt></ruby>いですね。<ruby>解熱剤<rt>げねつざい</rt></ruby>と<ruby>咳止<rt>せきど</rt></ruby>めを<ruby>出<rt>だ</rt></ruby>しますので、<ruby>処方箋<rt>しょほうせん</rt></ruby>を<ruby>隣<rt>となり</rt></ruby>の<ruby>薬局<rt>やっきょく</rt></ruby>に<ruby>出<rt>だ</rt></ruby>してください。","plain":"喉が少し赤いですね。解熱剤と咳止めを出しますので、処方箋を隣の薬局に出してください。","ko":"목이 조금 붉네요. 해열제랑 기침약을 처방할 테니 처방전을 옆 약국에 내세요.","note":""}]},{"badge":"트러블·마무리","title":"드럭스토어 복약 지도와 알레르기·부작용 확인","lines":[{"speaker":"나","role":"손님","jp":"すみません、<ruby>胃<rt>い</rt></ruby>に<ruby>優<rt>やさ</rt></ruby>しい<ruby>痛<rt>いた</rt></ruby>み<ruby>止<rt>ど</rt></ruby>めと<ruby>喉<rt>のど</rt></ruby><ruby>用<rt>よう</rt></ruby>のうがい<ruby>薬<rt>ぐすり</rt></ruby>を<ruby>探<rt>さが</rt></ruby>しています。","plain":"すみません、胃に優しい痛み止めと喉用のうがい薬を探しています。","ko":"저기요, 위에 부담이 적은 진통제랑 목 가글약을 찾고 있어요.","note":""},{"speaker":"약사","role":"약사","jp":"こちらがおすすめです。<ruby>普段<rt>ふだん</rt></ruby><ruby>飲<rt>の</rt></ruby>んでいるお<ruby>薬<rt>くすり</rt></ruby>やアレルギーはありますか？","plain":"こちらがおすすめです。普段飲んでいるお薬やアレルギーはありますか？","ko":"이 제품 추천해 드려요. 평소 드시는 약이나 알레르기가 있으신가요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>薬<rt>くすり</rt></ruby>のアレルギーはありません。ただ、<ruby>仕事<rt>しごと</rt></ruby>があるので<ruby>眠<rt>ねむ</rt></ruby>くなる<ruby>成分<rt>せいぶん</rt></ruby>は<ruby>避<rt>さ</rt></ruby>けたいです。","plain":"薬のアレルギーはありません。ただ、仕事があるので眠くなる成分は避けたいです。","ko":"약 알레르기는 없어요. 다만 일을 해야 해서 졸린 성분은 피하고 싶어요.","note":""},{"speaker":"약사","role":"약사","jp":"それなら<ruby>眠<rt>ねむ</rt></ruby>くなる<ruby>成分<rt>せいぶん</rt></ruby>が<ruby>入<rt>はい</rt></ruby>っていないタイプにしましょう。<ruby>食後<rt>しょくご</rt></ruby>に<ruby>二錠<rt>にじょう</rt></ruby>ずつ<ruby>飲<rt>の</rt></ruby>んでください。","plain":"それなら眠くなる成分が入っていないタイプにしましょう。食後に二錠ずつ飲んでください。","ko":"그렇다면 졸음 성분이 없는 타입으로 하세요. 식후에 두 알씩 드시면 됩니다.","note":""},{"speaker":"나","role":"손님","jp":"<ruby>強<rt>つよ</rt></ruby>い<ruby>副作用<rt>ふくさよう</rt></ruby>はありますか？あと、<ruby>防水<rt>ぼうすい</rt></ruby>の<ruby>絆創膏<rt>ばんそうこう</rt></ruby>と<ruby>湿布<rt>しっぷ</rt></ruby>も<ruby>一緒<rt>いっしょ</rt></ruby>にください。","plain":"強い副作用はありますか？あと、防水の絆創膏と湿布も一緒にください。","ko":"강한 부작용은 없나요? 그리고 방수 반창고랑 파스도 같이 주세요.","note":""},{"speaker":"약사","role":"약사","jp":"<ruby>胃<rt>い</rt></ruby>が<ruby>荒<rt>あ</rt></ruby>れやすい<ruby>方<rt>かた</rt></ruby>は<ruby>必<rt>かなら</rt></ruby>ず<ruby>食後<rt>しょくご</rt></ruby>に<ruby>服用<rt>ふくよう</rt></ruby>してくださいね。お<ruby>大事<rt>だいじ</rt></ruby>にどうぞ！","plain":"胃が荒れやすい方は必ず食後に服用してくださいね。お大事にどうぞ！","ko":"위가 예민하신 분은 꼭 식후에 복용하세요. 쾌차하시길 바랍니다!","note":""}]}],"phone":[{"badge":"응용·옵션","title":"코스·알레르기·생일 서프라이즈 요청","lines":[{"speaker":"직원","role":"레스토랑 직원","jp":"お<ruby>電話<rt>でんわ</rt></ruby>ありがとうございます。<ruby>青山<rt>あおやま</rt></ruby>ビストロでございます。","plain":"お電話ありがとうございます。青山ビストロでございます。","ko":"전화 감사합니다. 아오야마 비스트로입니다.","note":""},{"speaker":"나","role":"손님","jp":"もしもし、<ruby>来週<rt>らいしゅう</rt></ruby>の<ruby>金曜日<rt>きんようび</rt></ruby>の<ruby>夜<rt>よる</rt></ruby><ruby>七時<rt>しちじ</rt></ruby>に<ruby>二名<rt>にめい</rt></ruby>で<ruby>個室希望<rt>こしつきぼう</rt></ruby>なんですが、<ruby>空<rt>あ</rt></ruby>いていますか？","plain":"もしもし、来週の金曜日の夜七時に二名で個室希望なんですが、空いていますか？","ko":"여보세요, 다음 주 금요일 저녁 7시에 2명 룸 희망인데 비어 있나요?","note":""},{"speaker":"직원","role":"레스토랑 직원","jp":"<ruby>確認<rt>かくにん</rt></ruby>いたしますね…はい、<ruby>禁煙席<rt>きんえんせき</rt></ruby>の<ruby>個室<rt>こしつ</rt></ruby>が<ruby>一<rt>ひと</rt></ruby>つ<ruby>空<rt>あ</rt></ruby>いております！","plain":"確認いたしますね…はい、禁煙席の個室が一つ空いております！","ko":"확인해 보겠습니다… 네, 금연 룸이 하나 비어 있습니다!","note":""},{"speaker":"나","role":"손님","jp":"よかったです！<ruby>料理<rt>りょうり</rt></ruby>は<ruby>当日<rt>とうじつ</rt></ruby><ruby>決<rt>き</rt></ruby>めたいので<ruby>席のみ予約<rt>せきのみよやく</rt></ruby>でもいいですか？","plain":"よかったです！料理は当日決めたいので席のみ予約でもいいですか？","ko":"다행이네요! 요리는 당일에 고르고 싶어서 자리만 예약해도 될까요?","note":""},{"speaker":"직원","role":"레스토랑 직원","jp":"もちろんです。<ruby>アレルギー対応<rt>あれるぎーたいおう</rt></ruby>や<ruby>苦手<rt>にがて</rt></ruby>な<ruby>食材<rt>しょくざい</rt></ruby>はございますか？","plain":"もちろんです。アレルギー対応や苦手な食材はございますか？","ko":"물론이죠. 알레르기 대응이나 못 드시는 식재료가 있으신가요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>連<rt>つ</rt></ruby>れが<ruby>甲殻類<rt>こうかくるい</rt></ruby>アレルギーなんです。あと<ruby>誕生日<rt>たんじょうび</rt></ruby>のサプライズプレートをお<ruby>願<rt>ねが</rt></ruby>いできますか？","plain":"連れが甲殻類アレルギーなんです。あと誕生日のサプライズプレートをお願いできますか？","ko":"동행인이 갑각류 알레르기가 있어요. 그리고 생일 서프라이즈 플레이트 부탁드릴 수 있을까요?","note":""}]},{"badge":"트러블·마무리","title":"지각 연락과 인원 변경·취소 규정 확인","lines":[{"speaker":"나","role":"손님","jp":"もしもし、<ruby>今夜<rt>こんや</rt></ruby><ruby>七時<rt>しちじ</rt></ruby>に<ruby>予約<rt>よやく</rt></ruby>しているキムと<ruby>申<rt>もう</rt></ruby>します。<ruby>電車<rt>でんしゃ</rt></ruby>が<ruby>遅<rt>おく</rt></ruby>れて<ruby>十分<rt>じゅっぷん</rt></ruby>ほど<ruby>遅<rt>おく</rt></ruby>れそうなんです。","plain":"もしもし、今夜七時に予約しているキムと申します。電車が遅れて十分ほど遅れそうなんです。","ko":"여보세요, 오늘 밤 7시에 예약한 김이라고 합니다. 전철이 지연돼서 10분 정도 늦을 것 같아요.","note":"「十分(じゅっぷん)」= 10분 (じゅうぶん 아님 주의!)."},{"speaker":"직원","role":"레스토랑 직원","jp":"ご<ruby>連絡<rt>れんらく</rt></ruby>ありがとうございます！<ruby>十分<rt>じゅっぷん</rt></ruby>ほどでしたら<ruby>全<rt>まった</rt></ruby>く<ruby>問題<rt>もんだい</rt></ruby>ございませんよ。","plain":"ご連絡ありがとうございます！十分ほどでしたら全く問題ございませんよ。","ko":"연락 감사합니다! 10분 정도라면 전혀 문제없습니다.","note":""},{"speaker":"나","role":"손님","jp":"すみません、あと<ruby>人数<rt>にんずう</rt></ruby>が<ruby>一名<rt>いちめい</rt></ruby><ruby>増<rt>ふ</rt></ruby>えるかもしれないのですが<ruby>変更<rt>へんこう</rt></ruby>できますか？","plain":"すみません、あと人数が一名増えるかもしれないのですが変更できますか？","ko":"죄송한데, 그리고 인원이 1명 늘 수도 있는데 변경 가능한가요?","note":""},{"speaker":"직원","role":"레스토랑 직원","jp":"<ruby>確認<rt>かくにん</rt></ruby>しますね…<ruby>三名様<rt>さんめいさま</rt></ruby>でも<ruby>大丈夫<rt>だいじょうぶ</rt></ruby>です！ちなみに<ruby>前日<rt>ぜんじつ</rt></ruby>キャンセルだと<ruby>キャンセル料<rt>きゃんせるりょう</rt></ruby>がかかります。","plain":"確認しますね…三名様でも大丈夫です！ちなみに前日キャンセルだとキャンセル料がかかります。","ko":"확인해 볼게요… 3분도 괜찮습니다! 참고로 전날 취소 시 취소 수수료가 발생합니다.","note":""},{"speaker":"나","role":"손님","jp":"わかりました。お<ruby>電話<rt>でんわ</rt></ruby><ruby>聞き取<rt>ききと</rt></ruby>りにくくてすみません、<ruby>営業時間<rt>えいぎょうじかん</rt></ruby>は<ruby>何時<rt>なんじ</rt></ruby>までですか？","plain":"わかりました。お電話聞き取りにくくてすみません、営業時間は何時までですか？","ko":"알겠습니다. 전화가 잘 안 들려서 죄송해요, 영업시간은 몇 시까지인가요?","note":""},{"speaker":"직원","role":"레스토랑 직원","jp":"<ruby>二十三時<rt>にじゅうさんじ</rt></ruby>まで<ruby>営業<rt>えいぎょう</rt></ruby>しております。お<ruby>気<rt>き</rt></ruby>をつけてお<ruby>越<rt>こ</rt></ruby>しくださいませ。","plain":"二十三時まで営業しております。お気をつけてお越しくださいませ。","ko":"밤 11시까지 영업합니다. 조심히 오세요.","note":""}]}],"rent":[{"badge":"응용·옵션","title":"방 조건(오토록·욕실분리·남향) 구체 상담","lines":[{"speaker":"부동산","role":"중개사","jp":"ご<ruby>希望<rt>きぼう</rt></ruby>の<ruby>間取<rt>まど</rt></ruby>りや<ruby>設備<rt>せつび</rt></ruby>の<ruby>条件<rt>じょうけん</rt></ruby>を<ruby>詳<rt>くわ</rt></ruby>しく<ruby>教<rt>おし</rt></ruby>えていただけますか？","plain":"ご希望の間取りや設備の条件を詳しく教えていただけますか？","ko":"원하시는 방 구조나 설비 조건을 자세히 알려 주실 수 있나요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>家賃<rt>やちん</rt></ruby>は<ruby>管理費<rt>かんりひ</rt></ruby><ruby>込<rt>こ</rt></ruby>みで<ruby>九万円<rt>きゅうまんえん</rt></ruby><ruby>以内<rt>いない</rt></ruby>、<ruby>最寄り駅<rt>もよりえき</rt></ruby>から<ruby>徒歩<rt>とほ</rt></ruby><ruby>十分<rt>じゅっぷん</rt></ruby><ruby>以内<rt>いない</rt></ruby>が<ruby>希望<rt>きぼう</rt></ruby>です。","plain":"家賃は管理費込みで九万円以内、最寄り駅から徒歩十分以内が希望です。","ko":"월세는 관리비 포함 9만 엔 이내, 가장 가까운 역에서 도보 10분 이내를 원해요.","note":""},{"speaker":"부동산","role":"중개사","jp":"<ruby>設備<rt>せつび</rt></ruby><ruby>面<rt>めん</rt></ruby>で<ruby>絶対<rt>ぜったい</rt></ruby>に<ruby>外<rt>はず</rt></ruby>せない<ruby>条件<rt>じょうけん</rt></ruby>はありますか？","plain":"設備面で絶対に外せない条件はありますか？","ko":"설비 면에서 절대 포기 못 하는 조건이 있으신가요?","note":""},{"speaker":"나","role":"손님","jp":"オートロックと<ruby>バストイレ別<rt>ばすといれべつ</rt></ruby>、あと<ruby>独立洗面台<rt>どくりつせんめんだい</rt></ruby>があると<ruby>嬉<rt>うれ</rt></ruby>しいです。","plain":"オートロックとバストイレ別、あと独立洗面台があると嬉しいです。","ko":"공동현관 자동잠금과 욕실·화장실 분리형, 그리고 독립 세면대가 있으면 좋겠어요.","note":""},{"speaker":"부동산","role":"중개사","jp":"それでしたら<ruby>築年数<rt>ちくねんすう</rt></ruby>が<ruby>浅<rt>あさ</rt></ruby>くて<ruby>南向<rt>みなみむ</rt></ruby>きの<ruby>角部屋<rt>かどべや</rt></ruby>が<ruby>一件<rt>いっけん</rt></ruby>ございますよ！","plain":"それでしたら築年数が浅くて南向きの角部屋が一件ございますよ！","ko":"그렇다면 연식이 얼마 안 된 남향 코너 방 매물이 하나 있어요!","note":""},{"speaker":"나","role":"손님","jp":"わあ、<ruby>インターネット無料<rt>いんたーねっとむりょう</rt></ruby>ですか？ぜひ<ruby>今週末<rt>こんしゅうまつ</rt></ruby>に<ruby>内見<rt>ないけん</rt></ruby>したいです！","plain":"わあ、インターネット無料ですか？ぜひ今週末に内見したいです！","ko":"와, 인터넷 무료인가요? 꼭 이번 주말에 집을 보러 가고 싶어요!","note":"「内見(ないけん)」= 실제 방 둘러보기."}]},{"badge":"트러블·마무리","title":"초기 비용(보증금·사례금·갱신료)과 입주 심사","lines":[{"speaker":"나","role":"손님","jp":"<ruby>部屋<rt>へや</rt></ruby>はとても<ruby>気<rt>き</rt></ruby>に<ruby>入<rt>はい</rt></ruby>ったんですが、<ruby>初期費用<rt>しょきひよう</rt></ruby>は<ruby>全部<rt>ぜんぶ</rt></ruby>でいくらになりますか？","plain":"部屋はとても気に入ったんですが、初期費用は全部でいくらになりますか？","ko":"방은 정말 마음에 들었는데, 초기 비용이 전부 얼마가 되나요?","note":""},{"speaker":"부동산","role":"중개사","jp":"<ruby>敷金<rt>しききん</rt></ruby>と<ruby>礼金<rt>れいきん</rt></ruby>が<ruby>一ヶ月分<rt>いっかげつぶん</rt></ruby>ずつ、<ruby>仲介手数料<rt>ちゅうかいてすうりょう</rt></ruby>と<ruby>鍵交換費用<rt>かぎこうかんひよう</rt></ruby>を<ruby>合<rt>あ</rt></ruby>わせて<ruby>約<rt>やく</rt></ruby><ruby>四十万円<rt>よんじゅういちまんえん</rt></ruby>です。","plain":"敷金と礼金が一ヶ月分ずつ、仲介手数料と鍵交換費用を合わせて約四十万円です。","ko":"보증금과 사례금 각 한 달 치, 중개 수수료와 열쇠 교체 비용 합쳐 약 40만 엔입니다.","note":""},{"speaker":"나","role":"손님","jp":"<ruby>外国人<rt>がいこくじん</rt></ruby>なので<ruby>保証人<rt>ほしょうにん</rt></ruby>がいないんですが、<ruby>保証会社<rt>ほしょうがいしゃ</rt></ruby>を<ruby>利用<rt>りよう</rt></ruby>できますか？","plain":"外国人なので保証人がいないんですが、保証会社を利用できますか？","ko":"외국인이라 보증인이 없는데 보증 회사를 이용할 수 있나요?","note":""},{"speaker":"부동산","role":"중개사","jp":"はい、<ruby>保証人<rt>ほしょうにん</rt></ruby><ruby>不要<rt>ふよう</rt></ruby>で<ruby>審査<rt>しんさ</rt></ruby>できますよ。<ruby>審査<rt>しんさ</rt></ruby>には<ruby>三日<rt>みっか</rt></ruby>から<ruby>五日<rt>いつか</rt></ruby>ほどかかります。","plain":"はい、保証人不要で審査できますよ。審査には三日から五日ほどかかります。","ko":"네, 보증인 없이 심사할 수 있어요. 심사는 3일에서 5일 정도 걸립니다.","note":""},{"speaker":"나","role":"손님","jp":"<ruby>二年後<rt>にねんご</rt></ruby>の<ruby>更新料<rt>こうしんりょう</rt></ruby>はいくらですか？あと<ruby>退去<rt>たいきょ</rt></ruby>するときは<ruby>何ヶ月<rt>なんかげつ</rt></ruby><ruby>前<rt>まえ</rt></ruby>に<ruby>連絡<rt>れんらく</rt></ruby>が<ruby>必要<rt>ひつよう</rt></ruby>ですか？","plain":"二年後の更新料はいくらですか？あと退去するときは何ヶ月前に連絡が必要ですか？","ko":"2년 뒤 갱신료는 얼마인가요? 그리고 퇴거할 때는 몇 달 전에 연락해야 하나요?","note":""},{"speaker":"부동산","role":"중개사","jp":"<ruby>更新料<rt>こうしんりょう</rt></ruby>は<ruby>家賃<rt>やちん</rt></ruby>の<ruby>一ヶ月分<rt>いっかげつぶん</rt></ruby>で、<ruby>退去<rt>たいきょ</rt></ruby>は<ruby>一ヶ月前<rt>いっかげつまえ</rt></ruby>までにご<ruby>連絡<rt>れんらく</rt></ruby>いただくルールです。","plain":"更新料は家賃の一ヶ月分で、退去は一ヶ月前までにご連絡いただくルールです。","ko":"갱신료는 월세 한 달 치이고, 퇴거는 한 달 전까지 연락하시는 규정입니다.","note":""}]}],"office":[{"badge":"응용·옵션","title":"보고·연락·상담(호렌소)과 품의·결재 요청","lines":[{"speaker":"나","role":"직원","jp":"<ruby>部長<rt>ぶちょう</rt></ruby>、お<ruby>疲<rt>つか</rt></ruby>れ<ruby>様<rt>さま</rt></ruby>です！<ruby>来月<rt>らいげつ</rt></ruby>の<ruby>予算<rt>よさん</rt></ruby>の<ruby>稟議書<rt>りんぎしょ</rt></ruby>を<ruby>作成<rt>さくせい</rt></ruby>したのですが、ご<ruby>確認<rt>かくにん</rt></ruby>いただけますか？","plain":"部長、お疲れ様です！来月の予算の稟議書を作成したのですが、ご確認いただけますか？","ko":"부장님, 수고하십니다! 다음 달 예산 품의서를 작성했는데 확인해 주실 수 있을까요?","note":"「報連相(ほうれんそう)」= 보고·연락·상담."},{"speaker":"부장","role":"상사","jp":"お<ruby>疲<rt>つか</rt></ruby>れ<ruby>様<rt>さま</rt></ruby>。<ruby>添付ファイル<rt>てんぷふぁいる</rt></ruby>で<ruby>送<rt>おく</rt></ruby>ってくれたやつだね。<ruby>今<rt>いま</rt></ruby>チェックするよ。","plain":"お疲れ様。添付ファイルで送ってくれたやつだね。今チェックするよ。","ko":"수고했어. 첨부 파일로 보내 준 거지? 지금 볼게.","note":""},{"speaker":"나","role":"직원","jp":"はい、<ruby>前回<rt>ぜんかい</rt></ruby>のフィードバックを<ruby>反映<rt>はんえい</rt></ruby>してスケジュールを<ruby>修正<rt>しゅうせい</rt></ruby>しました。","plain":"はい、前回のフィードバックを反映してスケジュールを修正しました。","ko":"네, 지난번 피드백을 반영해서 일정을 수정했습니다.","note":""},{"speaker":"부장","role":"상사","jp":"よくまとまってるね。<ruby>納期<rt>のうき</rt></ruby>だけ<ruby>二日<rt>ふつか</rt></ruby><ruby>前倒<rt>まえだお</rt></ruby>しにできるかな？","plain":"よくまとまってるね。納期だけ二日前倒しにできるかな？","ko":"정리가 잘 됐네. 납기만 이틀 앞당길 수 있을까?","note":"「前倒し(まえだおし)」= 일정을 앞당김."},{"speaker":"나","role":"직원","jp":"<ruby>承知<rt>しょうち</rt></ruby>しました！チーム<ruby>内<rt>ない</rt></ruby>で<ruby>優先順位<rt>ゆうせんじゅんい</rt></ruby>を<ruby>調整<rt>ちょうせい</rt></ruby>して、<ruby>今日中<rt>きょうじゅう</rt></ruby>に<ruby>進捗状況<rt>しんちょくじょうきょう</rt></ruby>をご<ruby>報告<rt>ほうこく</rt></ruby>します。","plain":"承知しました！チーム内で優先順位を調整して、今日中に進捗状況をご報告します。","ko":"알겠습니다! 팀 내에서 우선순위를 조율해서 오늘 안에 진척 상황을 보고드리겠습니다.","note":""},{"speaker":"부장","role":"상사","jp":"<ruby>助<rt>たす</rt></ruby>かるよ。<ruby>問題<rt>もんだい</rt></ruby>なければそのまま<ruby>承認<rt>しょうにん</rt></ruby>しておくね。","plain":"助かるよ。問題なければそのまま承認しておくね。","ko":"고마워. 문제없으면 그대로 결재 승인해 둘게.","note":""}]},{"badge":"트러블·마무리","title":"연차·반차 신청과 업무 인수인계","lines":[{"speaker":"나","role":"직원","jp":"お<ruby>疲<rt>つか</rt></ruby>れ<ruby>様<rt>さま</rt></ruby>です。<ruby>来週<rt>らいしゅう</rt></ruby>の<ruby>金曜日<rt>きんようび</rt></ruby>に<ruby>有給休暇<rt>ゆうきゅうきゅうか</rt></ruby>をいただいてもよろしいでしょうか？","plain":"お疲れ様です。来週の金曜日に有給休暇をいただいてもよろしいでしょうか？","ko":"수고하십니다. 다음 주 금요일에 연차 휴가를 써도 괜찮을까요?","note":""},{"speaker":"동료","role":"팀 리더","jp":"もちろん<ruby>大丈夫<rt>だいじょうぶ</rt></ruby>ですよ！ちなみに<ruby>木曜日<rt>もくようび</rt></ruby>の<ruby>打ち合<rt>うちあ</rt></ruby>わせは<ruby>参加<rt>さんか</rt></ruby>できますか？","plain":"もちろん大丈夫ですよ！ちなみに木曜日の打ち合わせは参加できますか？","ko":"물론 괜찮아요! 혹시 목요일 미팅은 참석 가능하신가요?","note":""},{"speaker":"나","role":"직원","jp":"はい、<ruby>木曜日<rt>もくようび</rt></ruby>は<ruby>在宅勤務<rt>ざいたくきんむ</rt></ruby>ですが<ruby>会議<rt>かいぎ</rt></ruby>には<ruby>参加<rt>さんか</rt></ruby>します。<ruby>業務<rt>ぎょうむ</rt></ruby>の<ruby>引<rt>ひ</rt></ruby>き<ruby>継<rt>つ</rt></ruby>ぎ<ruby>資料<rt>しりょう</rt></ruby>も<ruby>共有<rt>きょうゆう</rt></ruby><ruby>済<rt>ず</rt></ruby>みです。","plain":"はい、木曜日は在宅勤務ですが会議には参加します。業務の引き継ぎ資料も共有済みです。","ko":"네, 목요일은 재택근무지만 회의에는 참석합니다. 업무 인수인계 자료도 공유해 두었어요.","note":""},{"speaker":"동료","role":"팀 리더","jp":"<ruby>完璧<rt>かんぺき</rt></ruby>ですね！あ、<ruby>先月<rt>せんげつ</rt></ruby>の<ruby>出張<rt>しゅっちょう</rt></ruby>の<ruby>経費精算<rt>けいひせいさん</rt></ruby>は<ruby>終<rt>お</rt></ruby>わっていますか？","plain":"完璧ですね！あ、先月の出張の経費精算は終わっていますか？","ko":"완벽하네요! 아, 지난달 출장 경비 정산은 마치셨나요?","note":""},{"speaker":"나","role":"직원","jp":"すみません、<ruby>領収書<rt>りょうしゅうしょ</rt></ruby>が<ruby>一枚<rt>いちまい</rt></ruby><ruby>差し戻<rt>さしもど</rt></ruby>しになっていたので<ruby>今日<rt>きょう</rt></ruby><ruby>定時<rt>ていじ</rt></ruby>までに<ruby>再提出<rt>さいていしゅつ</rt></ruby>します。","plain":"すみません、領収書が一枚差し戻しになっていたので今日定時までに再提出します。","ko":"죄송합니다, 영수증 한 장이 반려되어 있어서 오늘 정시 퇴근 전까지 다시 제출하겠습니다.","note":"「差し戻し(さしもどし)」= 결재 반려."},{"speaker":"동료","role":"팀 리더","jp":"<ruby>承知<rt>しょうち</rt></ruby>しました！<ruby>残業<rt>ざんぎょう</rt></ruby>にならないよう<ruby>気<rt>き</rt></ruby>をつけてくださいね。","plain":"承知しました！残業にならないよう気をつけてくださいね。","ko":"알겠습니다! 야근하지 않도록 조심해서 마무리하세요.","note":""}]}],"trouble":[{"badge":"응용·옵션","title":"인신사고 지연·대체 수송(후리카에) 이용","lines":[{"speaker":"나","role":"승객","jp":"すみません、<ruby>山手線<rt>やまのてせん</rt></ruby>が<ruby>止<rt>と</rt></ruby>まっているようですが、<ruby>復旧<rt>ふっきゅう</rt></ruby>の<ruby>目処<rt>めど</rt></ruby>はいつ<ruby>頃<rt>ころ</rt></ruby>でしょうか？","plain":"すみません、山手線が止まっているようですが、復旧の目処はいつ頃でしょうか？","ko":"저기요, 야마노테선이 멈춰 있는 것 같은데 복구 예정 시각은 언제쯤일까요?","note":"「目処(めど)」= 예상·전망."},{"speaker":"역무원","role":"역무원","jp":"<ruby>人身事故<rt>じんしんじこ</rt></ruby>の<ruby>影響<rt>えいきょう</rt></ruby>で<ruby>一時<rt>いちじ</rt></ruby><ruby>運転見合<rt>うんてんみあ</rt></ruby>わせ<ruby>中<rt>なか</rt></ruby>です。あと<ruby>三<rt>さん</rt></ruby><ruby>十分<rt>じゅっぷん</rt></ruby>ほどかかる<ruby>見込<rt>みこ</rt></ruby>みです。","plain":"人身事故の影響で一時運転見合わせ中です。あと三十分ほどかかる見込みです。","ko":"인신사고 영향으로 일시 운행 중단 중입니다. 30분 정도 더 걸릴 전망입니다.","note":""},{"speaker":"나","role":"승객","jp":"<ruby>急<rt>いそ</rt></ruby>いでいるんですが、<ruby>振替輸送<rt>ふりかえゆそう</rt></ruby>で<ruby>地下鉄<rt>ちかてつ</rt></ruby>を<ruby>使<rt>つか</rt></ruby>って<ruby>迂回<rt>うかい</rt></ruby>できますか？","plain":"急いでいるんですが、振替輸送で地下鉄を使って迂回できますか？","ko":"급한데 대체 수송으로 지하철을 타고 우회할 수 있나요?","note":"「振替輸送(ふりかえゆそう)」= 지연 시 타 노선 무료 대체 이용."},{"speaker":"역무원","role":"역무원","jp":"はい、<ruby>定期券<rt>ていきけん</rt></ruby>をお<ruby>持<rt>も</rt></ruby>ちでしたら<ruby>振<rt>ふ</rt></ruby><ruby>替<rt>か</rt></ruby><ruby>乗車票<rt>じょうしゃひょう</rt></ruby>をお<ruby>渡<rt>わた</rt></ruby>しします。","plain":"はい、定期券をお持ちでしたら振替乗車票をお渡しします。","ko":"네, 정기권이 있으시면 대체 승차표를 드립니다.","note":""},{"speaker":"나","role":"승객","jp":"あと、<ruby>会社<rt>かいしゃ</rt></ruby>に<ruby>提出<rt>ていしゅつ</rt></ruby>したいので<ruby>遅延証明書<rt>ちえんしょうめいしょ</rt></ruby>をいただけますか？","plain":"あと、会社に提出したいので遅延証明書をいただけますか？","ko":"그리고 회사에 제출해야 해서 지연 증명서 받을 수 있을까요?","note":""},{"speaker":"역무원","role":"역무원","jp":"<ruby>改札<rt>かいさつ</rt></ruby>の<ruby>横<rt>よこ</rt></ruby>で<ruby>配布<rt>はいふ</rt></ruby>しています。スマホの<ruby>公式<rt>こうしき</rt></ruby>サイトからもダウンロードできますよ。","plain":"改札の横で配布しています。スマホの公式サイトからもダウンロードできますよ。","ko":"개찰구 옆에서 나눠 드리고 있습니다. 스마트폰 공식 사이트에서도 다운받으실 수 있어요.","note":""}]},{"badge":"트러블·마무리","title":"전철 선반 분실물 접수와 수령 절차","lines":[{"speaker":"나","role":"승객","jp":"すみません、さっきの<ruby>快速<rt>かいそく</rt></ruby><ruby>電車<rt>でんしゃ</rt></ruby>の<ruby>五号車<rt>ごごうしゃ</rt></ruby>の<ruby>網棚<rt>あみだな</rt></ruby>に<ruby>傘<rt>かさ</rt></ruby>と<ruby>紙袋<rt>かみぶくろ</rt></ruby>を<ruby>置き忘<rt>おきわす</rt></ruby>れてしまいました。","plain":"すみません、さっきの快速電車の五号車の網棚に傘と紙袋を置き忘れてしまいました。","ko":"저기요, 방금 탄 쾌속 전철 5호차 선반에 우산이랑 쇼핑백을 두고 내렸어요.","note":""},{"speaker":"역무원","role":"역무원","jp":"すぐ<ruby>終点<rt>しゅうてん</rt></ruby>の<ruby>駅<rt>えき</rt></ruby>と<ruby>忘れ物センタ<rt>わすれものせんた</rt></ruby>ーに<ruby>連絡<rt>れんらく</rt></ruby>しますね。<ruby>特徴<rt>とくちょう</rt></ruby>を<ruby>教<rt>おし</rt></ruby>えていただけますか？","plain":"すぐ終点の駅と忘れ物センターに連絡しますね。特徴を教えていただけますか？","ko":"바로 종점 역과 유실물 센터에 연락해 볼게요. 특징을 알려 주시겠어요?","note":""},{"speaker":"나","role":"승객","jp":"<ruby>紺色<rt>こんいろ</rt></ruby>の<ruby>折<rt>お</rt></ruby>り<ruby>畳<rt>たた</rt></ruby>み<ruby>傘<rt>がさ</rt></ruby>と、<ruby>緑色<rt>みどりいろ</rt></ruby>の<ruby>小<rt>ちい</rt></ruby>さな<ruby>紙袋<rt>かみぶくろ</rt></ruby>です。<ruby>中<rt>なか</rt></ruby>に<ruby>本<rt>ほん</rt></ruby>が<ruby>入<rt>はい</rt></ruby>っています。","plain":"紺色の折り畳み傘と、緑色の小さな紙袋です。中に本が入っています。","ko":"남색 접이식 우산이랑 초록색 작은 쇼핑백이에요. 안에 책이 들어 있어요.","note":""},{"speaker":"역무원","role":"역무원","jp":"あ、ちょうど<ruby>終点<rt>しゅうてん</rt></ruby>で<ruby>見<rt>み</rt></ruby>つかったと<ruby>連絡<rt>れんらく</rt></ruby>が<ruby>入<rt>はい</rt></ruby>りました！<ruby>保管期間<rt>ほかんきかん</rt></ruby>は<ruby>三日間<rt>みっかかん</rt></ruby>です。","plain":"あ、ちょうど終点で見つかったと連絡が入りました！保管期間は三日間です。","ko":"아, 마침 종점에서 발견되었다고 연락이 왔어요! 역 보관 기간은 3일입니다.","note":""},{"speaker":"나","role":"승객","jp":"<ruby>本当<rt>ほんとう</rt></ruby>ですか、<ruby>助<rt>たす</rt></ruby>かりました！<ruby>受<rt>う</rt></ruby>け<ruby>取<rt>と</rt></ruby>りに<ruby>必要<rt>ひつよう</rt></ruby>なものはありますか？","plain":"本当ですか、助かりました！受け取りに必要なものはありますか？","ko":"정말요, 정말 다행이에요! 찾으러 갈 때 필요한 게 있나요?","note":""},{"speaker":"역무원","role":"역무원","jp":"パスポートなどの<ruby>本人確認書類<rt>ほんにんかくにんしょるい</rt></ruby>をお<ruby>持<rt>も</rt></ruby>ちのうえ、こちらの<ruby>受付番号<rt>うけつけばんごう</rt></ruby>をお<ruby>伝<rt>つた</rt></ruby>えください。","plain":"パスポートなどの本人確認書類をお持ちのうえ、こちらの受付番号をお伝えください。","ko":"여권 같은 본인 확인 서류를 지참하시고 이 접수 번호를 말씀해 주세요.","note":""}]}],"ramen":[{"badge":"응용·옵션","title":"돈코츠 커스텀(바리카타·기름·토핑) 주문","lines":[{"speaker":"점원","role":"라멘집 직원","jp":"いらっしゃいませ！<ruby>食券<rt>しょっけん</rt></ruby>をお<ruby>預<rt>あず</rt></ruby>かりします。お<ruby>好<rt>この</rt></ruby>みはございますか？","plain":"いらっしゃいませ！食券をお預かりします。お好みはございますか？","ko":"어서 오세요! 식권 받겠습니다. 원하시는 취향 있으신가요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>麺<rt>めん</rt></ruby>の<ruby>硬<rt>かた</rt></ruby>さはバリカタ、<ruby>油少<rt>あぶらすく</rt></ruby>なめ、<ruby>味薄<rt>あじうす</rt></ruby>めでお<ruby>願<rt>ねが</rt></ruby>いします！","plain":"麺の硬さはバリカタ、油少なめ、味薄めでお願いします！","ko":"면은 아주 꼬들하게(바리카타), 기름 적게, 덜 짜게 부탁드려요!","note":"일본 라멘집 3대 커스텀: 면 익힘·기름·간 세기."},{"speaker":"점원","role":"라멘집 직원","jp":"はい！ニンニクは<ruby>入<rt>い</rt></ruby>れますか？トッピングの<ruby>追加<rt>ついか</rt></ruby>はいかがですか？","plain":"はい！ニンニクは入れますか？トッピングの追加はいかがですか？","ko":"네! 마늘 넣어 드릴까요? 토핑 추가는 어떠세요?","note":""},{"speaker":"나","role":"손님","jp":"ニンニクは<ruby>少<rt>すこ</rt></ruby>しだけお<ruby>願<rt>ねが</rt></ruby>いします。あと<ruby>味玉<rt>あじたま</rt></ruby>とチャーシュー<ruby>一枚<rt>いちまい</rt></ruby><ruby>追加<rt>ついか</rt></ruby>できますか？","plain":"ニンニクは少しだけお願いします。あと味玉とチャーシュー一枚追加できますか？","ko":"마늘은 조금만 넣어 주세요. 그리고 반숙 계란이랑 차슈 한 장 추가할 수 있나요?","note":""},{"speaker":"점원","role":"라멘집 직원","jp":"もちろんです！<ruby>白<rt>しろ</rt></ruby>いシャツなので<ruby>紙エプロン<rt>かみえぷろん</rt></ruby>もどうぞ。","plain":"もちろんです！白いシャツなので紙エプロンもどうぞ。","ko":"물론이죠! 흰 셔츠시니까 종이 앞치마도 쓰세요.","note":""},{"speaker":"나","role":"손님","jp":"わあ、ありがとうございます！お<ruby>水<rt>みず</rt></ruby>はどこにありますか？","plain":"わあ、ありがとうございます！お水はどこにありますか？","ko":"와, 감사합니다! 물은 어디에 있나요?","note":""}]},{"badge":"트러블·마무리","title":"면 추가(카에다마)·탁상 양념과 사이드 주문","lines":[{"speaker":"나","role":"손님","jp":"すごく<ruby>濃厚<rt>のうこう</rt></ruby>で<ruby>美味<rt>おい</rt></ruby>しいですね！すみません、<ruby>替え玉<rt>かえだま</rt></ruby>を<ruby>一<rt>ひと</rt></ruby>つお<ruby>願<rt>ねが</rt></ruby>いします。","plain":"すごく濃厚で美味しいですね！すみません、替え玉を一つお願いします。","ko":"엄청 진하고 맛있네요! 저기요, 면 추가(카에다마) 하나 부탁드려요.","note":"돈코츠 라멘은 국물을 남기고 면만 추가(替え玉)하는 게 정석!"},{"speaker":"점원","role":"라멘집 직원","jp":"<ruby>替え玉<rt>かえだま</rt></ruby><ruby>一丁<rt>いっちょう</rt></ruby>！<ruby>硬<rt>かた</rt></ruby>さはさっきと<ruby>同<rt>おな</rt></ruby>じバリカタでいいですか？","plain":"替え玉一丁！硬さはさっきと同じバリカタでいいですか？","ko":"면 추가 하나요! 익힘은 아까처럼 바리카타로 할까요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>今度<rt>こんど</rt></ruby>は<ruby>普通<rt>ふつう</rt></ruby>の<ruby>硬<rt>かた</rt></ruby>さにしてください。あと<ruby>焼<rt>や</rt></ruby>き<ruby>餃子<rt>ぎょうざ</rt></ruby><ruby>五個<rt>ごこ</rt></ruby>も<ruby>追加<rt>ついか</rt></ruby>できますか？","plain":"今度は普通の硬さにしてください。あと焼き餃子五個も追加できますか？","ko":"이번엔 보통 익힘으로 해 주세요. 그리고 군만두 5개도 추가할 수 있나요?","note":""},{"speaker":"점원","role":"라멘집 직원","jp":"はい、<ruby>現金<rt>げんきん</rt></ruby><ruby>百五十円<rt>ひゃくごじゅうえん</rt></ruby>と<ruby>餃子<rt>ぎょうざ</rt></ruby><ruby>三百円<rt>さんびゃくえん</rt></ruby>になります。<ruby>卓上<rt>たくじょう</rt></ruby>の<ruby>紅生姜<rt>べにしょうが</rt></ruby>や<ruby>辛子高菜<rt>からしたかな</rt></ruby>もどうぞ！","plain":"はい、現金百五十円と餃子三百円になります。卓上の紅生姜や辛子高菜もどうぞ！","ko":"네, 현금 150엔이랑 교자 300엔입니다. 테이블 위 붉은 생강이랑 매운 갓김치도 드세요!","note":"「辛い(からい)」= 맵다."},{"speaker":"나","role":"손님","jp":"<ruby>辛子高菜<rt>からしたかな</rt></ruby>、すごく<ruby>辛<rt>から</rt></ruby>いけどスープによく<ruby>合<rt>あ</rt></ruby>いますね！レンゲをもう<ruby>一<rt>ひと</rt></ruby>ついただけますか？","plain":"辛子高菜、すごく辛いけどスープによく合いますね！レンゲをもう一ついただけますか？","ko":"매운 갓김치, 엄청 매운데 국물이랑 잘 어울리네요! 라멘 숟가락 하나 더 주실 수 있나요?","note":""},{"speaker":"점원","role":"라멘집 직원","jp":"はい、どうぞ！ゆっくり<ruby>召<rt>め</rt></ruby>し<ruby>上<rt>あ</rt></ruby>がってくださいね。","plain":"はい、どうぞ！ゆっくり召し上がってくださいね。","ko":"네, 여기 있습니다! 천천히 맛있게 드세요.","note":""}]}],"taxi":[{"badge":"응용·옵션","title":"고속도로 선택과 교차로 우회전·좌회전 안내","lines":[{"speaker":"기사","role":"택시 기사","jp":"ご<ruby>乗車<rt>じょうしゃ</rt></ruby>ありがとうございます。どちらまで<ruby>参<rt>まい</rt></ruby>りましょうか？","plain":"ご乗車ありがとうございます。どちらまで参りましょうか？","ko":"승차 감사합니다. 어디로 모실까요?","note":""},{"speaker":"나","role":"승객","jp":"<ruby>羽田空港<rt>はねだくうこう</rt></ruby>の<ruby>第<rt>だい</rt></ruby><ruby>三<rt>さん</rt></ruby>ターミナルまでお<ruby>願<rt>ねが</rt></ruby>いします。<ruby>急<rt>いそ</rt></ruby>いでいるので<ruby>高速道路<rt>こうそくどうろ</rt></ruby>を<ruby>使<rt>つか</rt></ruby>ってください。","plain":"羽田空港の第三ターミナルまでお願いします。急いでいるので高速道路を使ってください。","ko":"하네다공항 제3터미널까지 부탁드립니다. 급해서 고속도로를 이용해 주세요.","note":""},{"speaker":"기사","role":"택시 기사","jp":"<ruby>承知<rt>しょうち</rt></ruby>しました！<ruby>高速代<rt>こうそくだい</rt></ruby>が<ruby>別途<rt>べっと</rt></ruby>かかりますがよろしいですか？","plain":"承知しました！高速代が別途かかりますがよろしいですか？","ko":"알겠습니다! 고속도로 통행료가 별도로 드는데 괜찮으신가요?","note":""},{"speaker":"나","role":"승객","jp":"はい、<ruby>大丈夫<rt>だいじょうぶ</rt></ruby>です。<ruby>今<rt>いま</rt></ruby>の<ruby>時間帯<rt>じかんたい</rt></ruby>、<ruby>渋滞<rt>じゅうたい</rt></ruby>はしていませんか？","plain":"はい、大丈夫です。今の時間帯、渋滞はしていませんか？","ko":"네, 괜찮아요. 지금 시간대에 차가 막히지는 않나요?","note":""},{"speaker":"기사","role":"택시 기사","jp":"<ruby>少<rt>すこ</rt></ruby>し<ruby>混<rt>こ</rt></ruby>んでいますが、<ruby>三<rt>さん</rt></ruby><ruby>十分<rt>じゅっぷん</rt></ruby>ほどで<ruby>着<rt>つ</rt></ruby>くと<ruby>思<rt>おも</rt></ruby>います。<ruby>後部座席<rt>こうぶざせき</rt></ruby>もシートベルトをお<ruby>願<rt>ねが</rt></ruby>いしますね。","plain":"少し混んでいますが、三十分ほどで着くと思います。後部座席もシートベルトをお願いしますね。","ko":"조금 밀리긴 하는데 30분 정도면 도착할 거예요. 뒷좌석도 안전벨트 매 주세요.","note":""},{"speaker":"나","role":"승객","jp":"ありがとうございます。<ruby>途中<rt>とちゅう</rt></ruby>でコンビニに<ruby>寄<rt>よ</rt></ruby>る<ruby>時間<rt>じかん</rt></ruby>はなさそうですね。","plain":"ありがとうございます。途中でコンビニに寄る時間はなさそうですね。","ko":"감사합니다. 중간에 편의점에 들를 시간은 없을 것 같네요.","note":""}]},{"badge":"트러블·마무리","title":"하차 위치 미세 조정·QR 결제·영수증 요청","lines":[{"speaker":"기사","role":"택시 기사","jp":"<ruby>間<rt>ま</rt></ruby>もなく<ruby>目的地<rt>もくてきち</rt></ruby>の<ruby>近<rt>ちか</rt></ruby>くですが、この<ruby>辺<rt>あた</rt></ruby>りは<ruby>一方通行<rt>いっぽうつうこう</rt></ruby>が<ruby>多<rt>おお</rt></ruby>いんですよ。","plain":"間もなく目的地の近くですが、この辺りは一方通行が多いんですよ。","ko":"곧 목적지 근처인데 이 주변은 일방통행이 많아요.","note":""},{"speaker":"나","role":"승객","jp":"そうですか！じゃあ<ruby>無理<rt>むり</rt></ruby>にUターンしなくていいので、あのビルの<ruby>少<rt>すこ</rt></ruby>し<ruby>手前<rt>てまえ</rt></ruby>で<ruby>降<rt>お</rt></ruby>ろしてください。","plain":"そうですか！じゃあ無理にUターンしなくていいので、あのビルの少し手前で降ろしてください。","ko":"그래요? 그럼 무리하게 유턴 안 하셔도 되니 저 건물 바로 앞에서 내려 주세요.","note":""},{"speaker":"기사","role":"택시 기사","jp":"かしこまりました、ここで<ruby>止<rt>と</rt></ruby>めますね。<ruby>料金<rt>りょうきん</rt></ruby>は<ruby>二千三百円<rt>にせんさんびゃくえん</rt></ruby>になります。","plain":"かしこまりました、ここで止めますね。料金は二千三百円になります。","ko":"알겠습니다, 여기서 세울게요. 요금은 2,300엔입니다.","note":""},{"speaker":"나","role":"승객","jp":"PayPayなどの<ruby>QR決済<rt>きゅーあーるけっさい</rt></ruby>は<ruby>使<rt>つか</rt></ruby>えますか？あと、<ruby>会社<rt>かいしゃ</rt></ruby><ruby>提出<rt>ていしゅつ</rt></ruby><ruby>用<rt>よう</rt></ruby>の<ruby>領収書<rt>りょうしゅうしょ</rt></ruby>もお<ruby>願<rt>ねが</rt></ruby>いします。","plain":"PayPayなどのQR決済は使えますか？あと、会社提出用の領収書もお願いします。","ko":"페이페이 같은 QR 결제 되나요? 그리고 회사 제출용 영수증도 부탁드립니다.","note":""},{"speaker":"기사","role":"택시 기사","jp":"はい、こちらの<ruby>画面<rt>がめん</rt></ruby>を<ruby>読み取<rt>よみと</rt></ruby>ってください。<ruby>領収書<rt>りょうしゅうしょ</rt></ruby>もどうぞ！","plain":"はい、こちらの画面を読み取ってください。領収書もどうぞ！","ko":"네, 이 화면을 스캔해 주세요. 영수증도 여기 있습니다!","note":""},{"speaker":"나","role":"승객","jp":"トランクにスーツケースが<ruby>入<rt>はい</rt></ruby>っているので<ruby>開<rt>あ</rt></ruby>けていただけますか？ありがとうございました！","plain":"トランクにスーツケースが入っているので開けていただけますか？ありがとうございました！","ko":"트렁크에 캐리어가 들어 있어서 열어 주실 수 있나요? 감사했습니다!","note":""}]}],"post":[{"badge":"응용·옵션","title":"우체국 EMS·항공편·선편 해외 발송 상담","lines":[{"speaker":"직원","role":"우체국 직원","jp":"いらっしゃいませ。どのようなご<ruby>用件<rt>ようけん</rt></ruby>でしょうか？","plain":"いらっしゃいませ。どのようなご用件でしょうか？","ko":"어서 오세요. 어떤 용무로 오셨나요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>韓国<rt>かんこく</rt></ruby>へ<ruby>国際郵便<rt>こくさいゆうびん</rt></ruby>を<ruby>送<rt>おく</rt></ruby>りたいんですが、<ruby>一番<rt>いちばん</rt></ruby><ruby>早<rt>はや</rt></ruby>く<ruby>届<rt>とど</rt></ruby>くEMSだと<ruby>何日<rt>なんにち</rt></ruby>くらいかかりますか？","plain":"韓国へ国際郵便を送りたいんですが、一番早く届くEMSだと何日くらいかかりますか？","ko":"한국으로 국제 우편을 보내고 싶은데, 제일 빠른 EMS면 며칠 정도 걸리나요?","note":""},{"speaker":"직원","role":"우체국 직원","jp":"EMSなら<ruby>三日<rt>みっか</rt></ruby>から<ruby>四日<rt>よっか</rt></ruby>ほどで<ruby>届<rt>とど</rt></ruby>きます。お<ruby>急<rt>いそ</rt></ruby>ぎでなければ<ruby>安<rt>やす</rt></ruby>い<ruby>航空便<rt>こうくうびん</rt></ruby>や<ruby>船便<rt>ふなびん</rt></ruby>もありますよ。","plain":"EMSなら三日から四日ほどで届きます。お急ぎでなければ安い航空便や船便もありますよ。","ko":"EMS면 3~4일 정도면 도착해요. 안 급하시면 저렴한 항공편이나 선편도 있습니다.","note":""},{"speaker":"나","role":"손님","jp":"ではEMSでお<ruby>願<rt>ねが</rt></ruby>いします！<ruby>壊<rt>こわ</rt></ruby>れ<ruby>物<rt>もの</rt></ruby>なのでプチプチで<ruby>包<rt>つつ</rt></ruby>みました。<ruby>重<rt>おも</rt></ruby>さを<ruby>量<rt>はか</rt></ruby>ってもらえますか？","plain":"ではEMSでお願いします！壊れ物なのでプチプチで包みました。重さを量ってもらえますか？","ko":"그럼 EMS로 부탁드려요! 파손 주의 물품이라 뽁뽁이로 쌌어요. 무게를 재 주실 수 있나요?","note":""},{"speaker":"직원","role":"우체국 직원","jp":"<ruby>二<rt>に</rt></ruby>キロですので<ruby>送料<rt>そうりょう</rt></ruby>は<ruby>三千百五十円<rt>さんぜんひゃくごじゅうえん</rt></ruby>です。スプレー<ruby>缶<rt>かん</rt></ruby>や<ruby>電池<rt>でんち</rt></ruby>などの<ruby>禁制品<rt>きんせいひん</rt></ruby>は<ruby>入<rt>はい</rt></ruby>っていませんか？","plain":"二キロですので送料は三千百五十円です。スプレー缶や電池などの禁制品は入っていませんか？","ko":"2kg이라 배송비는 3,150엔입니다. 스프레이 캔이나 배터리 같은 금지 품목은 안 들어 있나요?","note":""},{"speaker":"나","role":"손님","jp":"お<ruby>菓子<rt>かし</rt></ruby>と<ruby>服<rt>ふく</rt></ruby>だけです！<ruby>追跡番号<rt>ついせきばんごう</rt></ruby>はレシートに<ruby>書<rt>か</rt></ruby>いてありますか？","plain":"お菓子と服だけです！追跡番号はレシートに書いてありますか？","ko":"과자랑 옷뿐이에요! 추적 번호는 영수증에 적혀 있나요?","note":""}]},{"badge":"트러블·마무리","title":"부재표 재배송·시간대 지정과 문 앞 배송(오키하이)","lines":[{"speaker":"나","role":"손님","jp":"もしもし、ポストに<ruby>不在<rt>ふざい</rt></ruby><ruby>票<rt>ひょう</rt></ruby>が<ruby>入<rt>はい</rt></ruby>っていたので<ruby>再配達<rt>さいはいたつ</rt></ruby>をお<ruby>願<rt>ねが</rt></ruby>いしたいのですが。","plain":"もしもし、ポストに不在票が入っていたので再配達をお願いしたいのですが。","ko":"여보세요, 우편함에 부재표가 들어 있어서 재배송을 부탁드리고 싶은데요.","note":""},{"speaker":"배달원","role":"택배 기사","jp":"ありがとうございます。<ruby>不在<rt>ふざい</rt></ruby><ruby>票<rt>ひょう</rt></ruby>の<ruby>追跡番号<rt>ついせきばんごう</rt></ruby>と<ruby>郵便番号<rt>ゆうびんばんごう</rt></ruby>を<ruby>教<rt>おし</rt></ruby>えていただけますか？","plain":"ありがとうございます。不在票の追跡番号と郵便番号を教えていただけますか？","ko":"감사합니다. 부재표의 추적 번호와 우편번호를 알려 주시겠어요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>番号<rt>ばんごう</rt></ruby>は<ruby>一二三四<rt>いちにさんよん</rt></ruby>の<ruby>五六七八<rt>ごろくななはち</rt></ruby>です。<ruby>明日<rt>あした</rt></ruby>の<ruby>十九時<rt>じゅうくじ</rt></ruby>から<ruby>二十一時<rt>にじゅういちじ</rt></ruby>の<ruby>時間帯指定<rt>じかんたいしてい</rt></ruby>でお<ruby>願<rt>ねが</rt></ruby>いします。","plain":"番号は一二三四の五六七八です。明日の十九時から二十一時の時間帯指定でお願いします。","ko":"번호는 1234-5678입니다. 내일 오후 7시~9시 시간대 지정으로 부탁드려요.","note":""},{"speaker":"배달원","role":"택배 기사","jp":"かしこまりました！もしご<ruby>不在<rt>ふざい</rt></ruby>だった<ruby>場合<rt>ばあい</rt></ruby>、<ruby>宅配ボックス<rt>たくはいぼっくす</rt></ruby>や<ruby>玄関前<rt>げんかんまえ</rt></ruby>の<ruby>置<rt>お</rt></ruby>き<ruby>配<rt>はい</rt></ruby>はご<ruby>利用<rt>りよう</rt></ruby>になりますか？","plain":"かしこまりました！もしご不在だった場合、宅配ボックスや玄関前の置き配はご利用になりますか？","ko":"알겠습니다! 혹시 안 계시면 무인 택배함이나 현관 앞 비대면 배송(오키하이)을 이용하시겠어요?","note":"「置き配(おきはい)」= 문 앞 비대면 배송."},{"speaker":"나","role":"손님","jp":"はい、<ruby>生<rt>なま</rt></ruby>ものじゃないので<ruby>不在<rt>ふざい</rt></ruby>のときは<ruby>玄関前<rt>げんかんまえ</rt></ruby>に<ruby>置<rt>お</rt></ruby>き<ruby>配<rt>はい</rt></ruby>で<ruby>大丈夫<rt>だいじょうぶ</rt></ruby>です。","plain":"はい、生ものじゃないので不在のときは玄関前に置き配で大丈夫です。","ko":"네, 신선식품이 아니라서 없으면 현관 앞에 두고 가셔도 괜찮아요.","note":""},{"speaker":"배달원","role":"택배 기사","jp":"<ruby>承知<rt>しょうち</rt></ruby>しました。<ruby>着払<rt>ちゃくばら</rt></ruby>いではなく<ruby>元払<rt>もとばら</rt></ruby>い<ruby>済<rt>ず</rt></ruby>みですので、そのままお<ruby>渡<rt>わた</rt></ruby>ししますね。","plain":"承知しました。着払いではなく元払い済みですので、そのままお渡ししますね。","ko":"알겠습니다. 착불이 아니라 선불 결제 완료 상태라 그대로 놓아드리겠습니다.","note":""}]}],"bank":[{"badge":"응용·옵션","title":"은행 계좌 개설·도장·인터넷 뱅킹 신청","lines":[{"speaker":"행원","role":"은행 창구","jp":"<ruby>本日<rt>ほんじつ</rt></ruby>はどのようなお<ruby>手続<rt>てつづ</rt></ruby>きでしょうか？","plain":"本日はどのようなお手続きでしょうか？","ko":"오늘은 어떤 업무로 오셨나요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>普通預金<rt>ふつうよきん</rt></ruby>の<ruby>口座開設<rt>こうざかいせつ</rt></ruby>をお<ruby>願<rt>ねが</rt></ruby>いしたいです。<ruby>在留<rt>ざいりゅう</rt></ruby>カードと<ruby>住民票<rt>じゅうみんひょう</rt></ruby>を<ruby>持<rt>も</rt></ruby>ってきました。","plain":"普通預金の口座開設をお願いしたいです。在留カードと住民票を持ってきました。","ko":"보통예금 계좌 개설을 부탁드리고 싶어요. 재류카드랑 주민표를 가져왔어요.","note":""},{"speaker":"행원","role":"은행 창구","jp":"ありがとうございます。サインではなく<ruby>印鑑<rt>いんかん</rt></ruby>が<ruby>必要<rt>ひつよう</rt></ruby>ですがお<ruby>持<rt>も</rt></ruby>ちですか？","plain":"ありがとうございます。サインではなく印鑑が必要ですがお持ちですか？","ko":"감사합니다. 서명이 아니라 도장이 필요한데 가지고 계신가요?","note":""},{"speaker":"나","role":"손님","jp":"はい、こちらです！ネットバンキングも<ruby>同時<rt>どうじ</rt></ruby>に<ruby>申<rt>もう</rt></ruby>し<ruby>込<rt>こ</rt></ruby>みたいんですができますか？","plain":"はい、こちらです！ネットバンキングも同時に申し込みたいんですができますか？","ko":"네, 여기 있어요! 인터넷 뱅킹도 동시에 신청하고 싶은데 가능한가요?","note":""},{"speaker":"행원","role":"은행 창구","jp":"もちろんです。キャッシュカードの<ruby>暗証番号<rt>あんしょうばんごう</rt></ruby>を<ruby>四桁<rt>よんけた</rt></ruby>で<ruby>決<rt>き</rt></ruby>めていただけますか？","plain":"もちろんです。キャッシュカードの暗証番号を四桁で決めていただけますか？","ko":"물론이죠. 현금카드 비밀번호를 4자리로 정해 주시겠어요?","note":""},{"speaker":"나","role":"손님","jp":"はい！キャッシュカードはいつ<ruby>届<rt>とど</rt></ruby>きますか？あと<ruby>海外送金<rt>かいがいそうきん</rt></ruby>の<ruby>手数料<rt>てすうりょう</rt></ruby>も<ruby>知<rt>し</rt></ruby>りたいです。","plain":"はい！キャッシュカードはいつ届きますか？あと海外送金の手数料も知りたいです。","ko":"네! 현금카드는 언제 도착하나요? 그리고 해외 송금 수수료도 알고 싶어요.","note":""}]},{"badge":"트러블·마무리","title":"일본 eSIM·요금제 개통과 해지 규정 확인","lines":[{"speaker":"나","role":"손님","jp":"すみません、<ruby>即日<rt>そくじつ</rt></ruby><ruby>使<rt>つか</rt></ruby>える<ruby>音声通話付<rt>おんせいつうわつ</rt></ruby>きのeSIMを<ruby>契約<rt>けいやく</rt></ruby>したいのですが。","plain":"すみません、即日使える音声通話付きのeSIMを契約したいのですが。","ko":"저기요, 당일 바로 쓸 수 있는 음성 통화 포함 eSIM을 계약하고 싶은데요.","note":""},{"speaker":"직원","role":"통신사 직원","jp":"<ruby>承知<rt>しょうち</rt></ruby>しました！<ruby>毎月<rt>まいつき</rt></ruby>の<ruby>データ容量<rt>でーたようりょう</rt></ruby>はどれくらいお<ruby>使<rt>つか</rt></ruby>いになりますか？","plain":"承知しました！毎月のデータ容量はどれくらいお使いになりますか？","ko":"알겠습니다! 매달 데이터 용량은 어느 정도 쓰시나요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>月<rt>つき</rt></ruby><ruby>二<rt>に</rt></ruby><ruby>十<rt>じゅう</rt></ruby>ギガくらいあれば<ruby>十分<rt>じゅうぶん</rt></ruby>です。<ruby>月額料金<rt>げつがくりょうきん</rt></ruby>はいくらになりますか？","plain":"月二十ギガくらいあれば十分です。月額料金はいくらになりますか？","ko":"월 20기가 정도면 충분해요. 월정액 요금은 얼마가 되나요?","note":"「十分(じゅうぶん)」= 충분하다."},{"speaker":"직원","role":"통신사 직원","jp":"<ruby>二<rt>に</rt></ruby><ruby>十<rt>じゅう</rt></ruby>ギガで<ruby>月額<rt>げつがく</rt></ruby><ruby>二千九百七十円<rt>にせんきゅうひゃくななじゅうえん</rt></ruby>です。<ruby>使<rt>つか</rt></ruby>い<ruby>切<rt>き</rt></ruby>ると<ruby>速度制限<rt>そくどせいげん</rt></ruby>がかかります。","plain":"二十ギガで月額二千九百七十円です。使い切ると速度制限がかかります。","ko":"20기가에 월 2,970엔입니다. 다 쓰시면 속도 제한이 걸립니다.","note":""},{"speaker":"나","role":"손님","jp":"<ruby>支払<rt>しはら</rt></ruby>いは<ruby>銀行<rt>ぎんこう</rt></ruby>の<ruby>引き落<rt>ひきお</rt></ruby>としにできますか？あと<ruby>途中<rt>とちゅう</rt></ruby>で<ruby>解約<rt>かいやく</rt></ruby>すると<ruby>違約金<rt>いやくきん</rt></ruby>はかかりますか？","plain":"支払いは銀行の引き落としにできますか？あと途中で解約すると違約金はかかりますか？","ko":"결제는 은행 자동이체로 할 수 있나요? 그리고 중간에 해지하면 위약금이 드나요?","note":""},{"speaker":"직원","role":"통신사 직원","jp":"<ruby>口座<rt>こうざ</rt></ruby><ruby>引き落<rt>ひきお</rt></ruby>としも<ruby>可能<rt>かのう</rt></ruby>です。<ruby>解約<rt>かいやく</rt></ruby>の<ruby>違約金<rt>いやくきん</rt></ruby>はかかりませんのでご<ruby>安心<rt>あんしん</rt></ruby>ください。","plain":"口座引き落としも可能です。解約の違約金はかかりませんのでご安心ください。","ko":"계좌 자동이체도 가능합니다. 해지 위약금은 없으니 안심하세요.","note":""}]}],"supermarket":[{"badge":"응용·옵션","title":"마감 할인·정육 코너와 양념 찾기","lines":[{"speaker":"나","role":"손님","jp":"すみません、<ruby>醤油<rt>しょうゆ</rt></ruby>やみりんなどの<ruby>調味料売り場<rt>ちょうみりょううりば</rt></ruby>はどの<ruby>辺<rt>あた</rt></ruby>りですか？","plain":"すみません、醤油やみりんなどの調味料売り場はどの辺りですか？","ko":"저기요, 간장이나 미림 같은 조미료 코너는 어느 쪽인가요?","note":""},{"speaker":"점원","role":"마트 직원","jp":"<ruby>五番<rt>ごばん</rt></ruby>の<ruby>通路<rt>つうろ</rt></ruby>の<ruby>真<rt>ま</rt></ruby>ん<ruby>中<rt>なか</rt></ruby><ruby>辺<rt>あた</rt></ruby>りです。<ruby>国産<rt>こくさん</rt></ruby>の<ruby>無添加<rt>むてんか</rt></ruby>タイプも<ruby>揃<rt>そろ</rt></ruby>っていますよ。","plain":"五番の通路の真ん中辺りです。国産の無添加タイプも揃っていますよ。","ko":"5번 통로 가운데쯤입니다. 일본 국내산 무첨가 제품도 구비되어 있어요.","note":""},{"speaker":"나","role":"손님","jp":"ありがとうございます！あ、<ruby>精肉売り場<rt>せいにくうりば</rt></ruby>で<ruby>豚肉<rt>ぶたにく</rt></ruby>を<ruby>三<rt>さん</rt></ruby><ruby>百<rt>ひゃく</rt></ruby>グラム<ruby>買<rt>か</rt></ruby>いたいんですが<ruby>量り売<rt>はかりう</rt></ruby>りですか？","plain":"ありがとうございます！あ、精肉売り場で豚肉を三百グラム買いたいんですが量り売りですか？","ko":"감사합니다! 아, 정육 코너에서 돼지고기 300g 사고 싶은데 무게 달아 파나요?","note":""},{"speaker":"점원","role":"마트 직원","jp":"パック<ruby>詰<rt>つ</rt></ruby>めになっています。<ruby>夕方<rt>ゆうがた</rt></ruby><ruby>六時<rt>ろくじ</rt></ruby>からはお<ruby>惣菜<rt>そうざい</rt></ruby>のタイムセールも<ruby>始<rt>はじ</rt></ruby>まりますよ！","plain":"パック詰めになっています。夕方六時からはお惣菜のタイムセールも始まりますよ！","ko":"팩 포장되어 있습니다. 저녁 6시부터 반찬 타임 세일도 시작돼요!","note":""},{"speaker":"나","role":"손님","jp":"わあ、<ruby>半額<rt>はんがく</rt></ruby>の<ruby>値引きシール<rt>ねびきしーる</rt></ruby>が<ruby>貼<rt>は</rt></ruby>ってあるお<ruby>刺身<rt>さしみ</rt></ruby>もありますね！<ruby>消費期限<rt>しょうひきげん</rt></ruby>は<ruby>今日<rt>きょう</rt></ruby>までですか？","plain":"わあ、半額の値引きシールが貼ってあるお刺身もありますね！消費期限は今日までですか？","ko":"와, 반값 할인 스티커가 붙은 회도 있네요! 소비기한은 오늘까지인가요?","note":"「賞味期限(맛있게 먹는 기한)」 vs 「消費期限(안전하게 먹는 기한)」."},{"speaker":"점원","role":"마트 직원","jp":"はい、<ruby>本日中<rt>ほんじつちゅう</rt></ruby>にお<ruby>召<rt>め</rt></ruby>し<ruby>上<rt>あ</rt></ruby>がりください。とても<ruby>新鮮<rt>しんせん</rt></ruby>でお<ruby>買<rt>か</rt></ruby>い<ruby>得<rt>どく</rt></ruby>ですよ！","plain":"はい、本日中にお召し上がりください。とても新鮮でお買い得ですよ！","ko":"네, 오늘 안으로 드세요. 아주 신선하고 알뜰합니다!","note":""}]},{"badge":"트러블·마무리","title":"셀프 계산대·아이스팩과 포장대(사카다이)","lines":[{"speaker":"점원","role":"계산대 안내","jp":"セルフレジをご<ruby>利用<rt>りよう</rt></ruby>ですか？バーコードをスキャナーにかざしてください。","plain":"セルフレジをご利用ですか？バーコードをスキャナーにかざしてください。","ko":"셀프 계산대 이용하시나요? 바코드를 스캐너에 대 주세요.","note":""},{"speaker":"나","role":"손님","jp":"すみません、この<ruby>値引きシール<rt>ねびきしーる</rt></ruby>のバーコードがうまく<ruby>読み取<rt>よみと</rt></ruby>れないんですが。","plain":"すみません、この値引きシールのバーコードがうまく読み取れないんですが。","ko":"저기요, 이 할인 스티커 바코드가 잘 안 찍히는데요.","note":""},{"speaker":"점원","role":"계산대 안내","jp":"あ、<ruby>割引<rt>わりびき</rt></ruby>シールがある<ruby>商品<rt>しょうひん</rt></ruby>は<ruby>店員<rt>てんいん</rt></ruby>がスキャンしますね。エコバッグはお<ruby>持<rt>も</rt></ruby>ちですか？","plain":"あ、割引シールがある商品は店員がスキャンしますね。エコバッグはお持ちですか？","ko":"아, 할인 스티커가 붙은 상품은 직원이 찍어 드릴게요. 장바구니 가지고 계신가요?","note":""},{"speaker":"나","role":"손님","jp":"はい、<ruby>持<rt>も</rt></ruby>っています！アイスクリームがあるので<ruby>保冷剤<rt>ほれいざい</rt></ruby>をいただけますか？","plain":"はい、持っています！アイスクリームがあるので保冷剤をいただけますか？","ko":"네, 가지고 있어요! 아이스크림이 있어서 아이스팩 좀 받을 수 있나요?","note":""},{"speaker":"점원","role":"계산대 안내","jp":"<ruby>保冷剤<rt>ほれいざい</rt></ruby>とドライアイスは<ruby>サッカー台<rt>さっかーだい</rt></ruby>の<ruby>横<rt>よこ</rt></ruby>にございます。<ruby>表示価格<rt>ひょうじかかく</rt></ruby>はすべて<ruby>税込<rt>ぜいこみ</rt></ruby>です。","plain":"保冷剤とドライアイスはサッカー台の横にございます。表示価格はすべて税込です。","ko":"아이스팩과 드라이아이스는 포장대 옆에 있습니다. 표시 가격은 모두 세금 포함입니다.","note":"일본 마트에서 물건을 담는 포장대를 「サッカー台(사카다이)」라고 해요."},{"speaker":"나","role":"손님","jp":"<ruby>親切<rt>しんせつ</rt></ruby>に<ruby>教<rt>おし</rt></ruby>えていただきありがとうございます！","plain":"親切に教えていただきありがとうございます！","ko":"친절하게 알려 주셔서 감사합니다!","note":""}]}],"gym":[{"badge":"응용·옵션","title":"헬스장 견학·월회비·렌탈 용품 문의","lines":[{"speaker":"트레이너","role":"헬스장 스태프","jp":"こんにちは！<ruby>今日<rt>きょう</rt></ruby>は<ruby>施設<rt>しせつ</rt></ruby>の<ruby>見学<rt>けんがく</rt></ruby>と<ruby>体験<rt>たいけん</rt></ruby>トレーニングですね。","plain":"こんにちは！今日は施設の見学と体験トレーニングですね。","ko":"안녕하세요! 오늘 시설 견학과 체험 트레이닝이시죠?","note":""},{"speaker":"나","role":"방문자","jp":"はい！<ruby>入会<rt>にゅうかい</rt></ruby><ruby>前<rt>まえ</rt></ruby>に<ruby>月会費<rt>げっかいひ</rt></ruby>とロッカーや<ruby>シャワー室<rt>しゃわーしつ</rt></ruby>の<ruby>設備<rt>せつび</rt></ruby>を<ruby>確認<rt>かくにん</rt></ruby>したくて。","plain":"はい！入会前に月会費とロッカーやシャワー室の設備を確認したくて。","ko":"네! 가입 전에 월 회비랑 사물함, 샤워실 시설을 확인하고 싶어서요.","note":""},{"speaker":"트레이너","role":"헬스장 스태프","jp":"<ruby>月会費<rt>げっかいひ</rt></ruby>は<ruby>八千八百円<rt>はっせんはっぴゃくえん</rt></ruby>で、<ruby>今日<rt>きょう</rt></ruby><ruby>入会<rt>にゅうかい</rt></ruby>すると<ruby>入会金<rt>にゅうかいきん</rt></ruby>が<ruby>無料<rt>むりょう</rt></ruby>になりますよ。","plain":"月会費は八千八百円で、今日入会すると入会金が無料になりますよ。","ko":"월 회비는 8,800엔이고, 오늘 가입하시면 입회비가 무료예요.","note":""},{"speaker":"나","role":"방문자","jp":"ウェアや<ruby>室内シューズ<rt>しつないしゅーず</rt></ruby>、タオルのレンタルはありますか？","plain":"ウェアや室内シューズ、タオルのレンタルはありますか？","ko":"운동복이랑 실내 운동화, 수건 대여가 있나요?","note":""},{"speaker":"트레이너","role":"헬스장 스태프","jp":"はい、<ruby>手<rt>て</rt></ruby>ぶらオプションをつけると<ruby>全部<rt>ぜんぶ</rt></ruby>レンタルできます。","plain":"はい、手ぶらオプションをつけると全部レンタルできます。","ko":"네, 빈손 옵션을 추가하시면 전부 대여 가능합니다.","note":""},{"speaker":"나","role":"방문자","jp":"<ruby>出張<rt>しゅっちょう</rt></ruby>が<ruby>多<rt>おお</rt></ruby>い<ruby>月<rt>つき</rt></ruby>があるんですが、<ruby>一ヶ月<rt>いっかげつ</rt></ruby>だけ<ruby>休会<rt>きゅうかい</rt></ruby>することもできますか？","plain":"出張が多い月があるんですが、一ヶ月だけ休会することもできますか？","ko":"출장이 많은 달이 있는데 한 달만 휴회할 수도 있나요?","note":""}]},{"badge":"트러블·마무리","title":"올바른 자세(폼)·근육통 예방과 쿨다운","lines":[{"speaker":"트레이너","role":"트레이너","jp":"まずは<ruby>怪我<rt>けが</rt></ruby>を<ruby>防<rt>ふせ</rt></ruby>ぐために<ruby>準備運動<rt>じゅんびうんどう</rt></ruby>とストレッチから<ruby>始<rt>はじ</rt></ruby>めましょう。","plain":"まずは怪我を防ぐために準備運動とストレッチから始めましょう。","ko":"먼저 부상을 막기 위해 준비운동과 스트레칭부터 시작합시다.","note":""},{"speaker":"나","role":"회원","jp":"<ruby>腰<rt>こし</rt></ruby>を<ruby>痛<rt>いた</rt></ruby>めないようにスクワットの<ruby>正<rt>ただ</rt></ruby>しいフォームを<ruby>教<rt>おし</rt></ruby>えていただけますか？","plain":"腰を痛めないようにスクワットの正しいフォームを教えていただけますか？","ko":"허리를 다치지 않게 스쿼트 올바른 자세를 알려 주실 수 있나요?","note":""},{"speaker":"트레이너","role":"트레이너","jp":"<ruby>背筋<rt>はいきん</rt></ruby>をまっすぐ<ruby>伸<rt>の</rt></ruby>ばして、<ruby>膝<rt>ひざ</rt></ruby>がつま<ruby>先<rt>さき</rt></ruby>より<ruby>前<rt>まえ</rt></ruby>に<ruby>出<rt>だ</rt></ruby>すぎないようにします。いいフォームですよ！","plain":"背筋をまっすぐ伸ばして、膝がつま先より前に出すぎないようにします。いいフォームですよ！","ko":"등 근육을 곧게 펴고 무릎이 발끝보다 너무 나오지 않게 하세요. 좋은 자세예요!","note":"「背筋(はいきん)」= 등 근육."},{"speaker":"나","role":"회원","jp":"ふう、すごく<ruby>効<rt>き</rt></ruby>きますね！セット<ruby>間<rt>ま</rt></ruby>のインターバルはどれくらいがいいですか？","plain":"ふう、すごく効きますね！セット間のインターバルはどれくらいがいいですか？","ko":"후, 엄청 자극이 오네요! 세트 사이 휴식 시간은 어느 정도가 좋나요?","note":""},{"speaker":"트레이너","role":"트레이너","jp":"<ruby>一分<rt>いっぷん</rt></ruby>ほど<ruby>休<rt>やす</rt></ruby>んで、こまめに<ruby>水分補給<rt>すいぶんほきゅう</rt></ruby>をしてくださいね。<ruby>最後<rt>さいご</rt></ruby>に<ruby>有酸素運動<rt>ゆうさんそうんどう</rt></ruby>を<ruby>二十分<rt>にじゅっぷん</rt></ruby>やりましょう。","plain":"一分ほど休んで、こまめに水分補給をしてくださいね。最後に有酸素運動を二十分やりましょう。","ko":"1분 정도 쉬고 수시로 수분 보충해 주세요. 마지막으로 유산소 운동을 20분 합시다.","note":""},{"speaker":"나","role":"회원","jp":"<ruby>筋肉痛<rt>きんにくつう</rt></ruby>にならないようにしっかりクールダウンして、<ruby>帰<rt>かえ</rt></ruby>りにプロテインを<ruby>飲<rt>の</rt></ruby>みます！","plain":"筋肉痛にならないようにしっかりクールダウンして、帰りにプロテインを飲みます！","ko":"근육통이 안 생기게 확실히 정리운동하고 집에 가서 프로틴 마실게요!","note":""}]}],"kyoto":[{"badge":"응용·옵션","title":"신사 참배 예절·고슈인·오미쿠지 체험","lines":[{"speaker":"가이드","role":"교토 안내인","jp":"ここが<ruby>有名<rt>ゆうめい</rt></ruby>な<ruby>赤<rt>あか</rt></ruby>い<ruby>鳥居<rt>とりい</rt></ruby>の<ruby>入口<rt>いりぐち</rt></ruby>です。<ruby>参拝<rt>さんぱい</rt></ruby>の<ruby>前<rt>まえ</rt></ruby>にまず<ruby>手水舎<rt>ちょうずや</rt></ruby>で<ruby>手<rt>て</rt></ruby>を<ruby>清<rt>きよ</rt></ruby>めましょう。","plain":"ここが有名な赤い鳥居の入口です。参拝の前にまず手水舎で手を清めましょう。","ko":"여기가 유명한 붉은 도리이 입구예요. 참배 전에 먼저 데미즈야에서 손을 씻읍시다.","note":"「手水舎(ちょうずや)」= 손·입 씻는 곳."},{"speaker":"나","role":"여행자","jp":"<ruby>日本<rt>にほん</rt></ruby>の<ruby>神社<rt>じんじゃ</rt></ruby>は<ruby>二礼二拍手一礼<rt>にれいにはくしゅいちれい</rt></ruby>で<ruby>参拝<rt>さんぱい</rt></ruby>するんですよね？お<ruby>賽銭<rt>さいせん</rt></ruby>は<ruby>五円<rt>ごえん</rt></ruby><ruby>玉<rt>たま</rt></ruby>を<ruby>用意<rt>ようい</rt></ruby>しました！","plain":"日本の神社は二礼二拍手一礼で参拝するんですよね？お賽銭は五円玉を用意しました！","ko":"일본 신사는 두 번 절, 두 번 박수, 한 번 절로 참배하는 거죠? 새전으로 5엔 동전을 준비했어요!","note":"5엔(ごえん) = 좋은 인연(ご縁)의 언어유희."},{"speaker":"가이드","role":"교토 안내인","jp":"<ruby>素晴<rt>すば</rt></ruby>らしいです！<ruby>境内<rt>けいだい</rt></ruby>を<ruby>歩<rt>ある</rt></ruby>いたら、お<ruby>守<rt>まも</rt></ruby>りや<ruby>御朱印<rt>ごしゅいん</rt></ruby>も<ruby>見<rt>み</rt></ruby>てみますか？","plain":"素晴らしいです！境内を歩いたら、お守りや御朱印も見てみますか？","ko":"훌륭합니다! 경내를 둘러본 뒤 부적이나 고슈인도 구경해 보실래요?","note":""},{"speaker":"나","role":"여행자","jp":"はい！おみくじを<ruby>引<rt>ひ</rt></ruby>いてみたいです…わあ、<ruby>大吉<rt>だいきち</rt></ruby>が<ruby>出<rt>で</rt></ruby>ました！","plain":"はい！おみくじを引いてみたいです…わあ、大吉が出ました！","ko":"네! 운세 제비를 뽑아 보고 싶어요… 와, 대길이 나왔어요!","note":""},{"speaker":"가이드","role":"교토 안내인","jp":"おめでとうございます！もし<ruby>凶<rt>きょう</rt></ruby>が<ruby>出<rt>で</rt></ruby>たら<ruby>境内<rt>けいだい</rt></ruby>の<ruby>結<rt>むす</rt></ruby>び<ruby>所<rt>ところ</rt></ruby>に<ruby>結<rt>むす</rt></ruby>んで<ruby>帰<rt>かえ</rt></ruby>るんですよ。","plain":"おめでとうございます！もし凶が出たら境内の結び所に結んで帰るんですよ。","ko":"축하드려요! 만약 흉이 나오면 경내 묶는 곳에 묶고 돌아가는 거랍니다.","note":""},{"speaker":"나","role":"여행자","jp":"じゃあ<ruby>合格祈願<rt>ごうかくきがん</rt></ruby>の<ruby>絵馬<rt>えま</rt></ruby>も<ruby>書<rt>か</rt></ruby>いていきます！<ruby>秋<rt>あき</rt></ruby>の<ruby>紅葉<rt>こうよう</rt></ruby>の<ruby>季節<rt>きせつ</rt></ruby>にもまた<ruby>来<rt>き</rt></ruby>たいですね。","plain":"じゃあ合格祈願の絵馬も書いていきます！秋の紅葉の季節にもまた来たいですね。","ko":"그럼 합격 기원 소원 패(에마)도 쓰고 갈게요! 가을 단풍 철에도 또 오고 싶네요.","note":""}]},{"badge":"트러블·마무리","title":"마치야 찻집·말차 다도와 교토 기념품","lines":[{"speaker":"주인","role":"찻집 주인","jp":"いらっしゃいませ。<ruby>古<rt>ふる</rt></ruby>い<ruby>町家<rt>まちや</rt></ruby>を<ruby>改装<rt>かいそう</rt></ruby>した<ruby>茶室<rt>ちゃしつ</rt></ruby>でございます。お<ruby>庭<rt>にわ</rt></ruby>の<ruby>見<rt>み</rt></ruby>える<ruby>席<rt>せき</rt></ruby>へどうぞ。","plain":"いらっしゃいませ。古い町家を改装した茶室でございます。お庭の見える席へどうぞ。","ko":"어서 오세요. 오래된 전통 목조 가옥을 개조한 다실입니다. 정원이 보이는 자리로 오세요.","note":"「町家(まちや)」= 교토 전통 가옥."},{"speaker":"나","role":"여행자","jp":"わあ、<ruby>美<rt>うつく</rt></ruby>しい<ruby>枯山水<rt>かれさんすい</rt></ruby>の<ruby>庭園<rt>ていえん</rt></ruby>ですね！<ruby>静<rt>しず</rt></ruby>かでとても<ruby>落ち着<rt>おちつ</rt></ruby>きます。","plain":"わあ、美しい枯山水の庭園ですね！静かでとても落ち着きます。","ko":"와, 아름다운 돌정원(가레산스이)이네요! 조용하고 정말 마음이 차분해져요.","note":""},{"speaker":"주인","role":"찻집 주인","jp":"ありがとうございます。お<ruby>抹茶<rt>まっちゃ</rt></ruby>と<ruby>季節<rt>きせつ</rt></ruby>の<ruby>和菓子<rt>わがし</rt></ruby>、それともほうじ<ruby>茶<rt>ちゃ</rt></ruby>セットになさいますか？","plain":"ありがとうございます。お抹茶と季節の和菓子、それともほうじ茶セットになさいますか？","ko":"감사합니다. 말차와 계절 화과자, 아니면 호지차 세트로 하시겠어요?","note":""},{"speaker":"나","role":"여행자","jp":"<ruby>本格的<rt>ほんかくてき</rt></ruby>なお<ruby>抹茶<rt>まっちゃ</rt></ruby>と<ruby>和菓子<rt>わがし</rt></ruby>のセットをお<ruby>願<rt>ねが</rt></ruby>いします。<ruby>焼<rt>や</rt></ruby>きたてのみたらし<ruby>団子<rt>だんご</rt></ruby>も<ruby>気<rt>き</rt></ruby>になります！","plain":"本格的なお抹茶と和菓子のセットをお願いします。焼きたてのみたらし団子も気になります！","ko":"본격적인 말차와 화과자 세트로 부탁드려요. 갓 구운 미타라시 당고도 궁금하네요!","note":""},{"speaker":"주인","role":"찻집 주인","jp":"<ruby>茶筅<rt>ちゃせん</rt></ruby>で<ruby>丁寧<rt>ていねい</rt></ruby>に<ruby>点<rt>た</rt></ruby>てたお<ruby>抹茶<rt>まっちゃ</rt></ruby>です。まず<ruby>甘<rt>あま</rt></ruby>い<ruby>和菓子<rt>わがし</rt></ruby>を<ruby>召<rt>め</rt></ruby>し<ruby>上<rt>あ</rt></ruby>がってからどうぞ。","plain":"茶筅で丁寧に点てたお抹茶です。まず甘い和菓子を召し上がってからどうぞ。","ko":"차선으로 정성껏 거품을 낸 말차입니다. 먼저 달콤한 화과자를 드신 뒤 마셔 보세요.","note":""},{"speaker":"나","role":"여행자","jp":"<ruby>抹茶<rt>まっちゃ</rt></ruby>の<ruby>香<rt>かお</rt></ruby>りと<ruby>甘<rt>あま</rt></ruby>さが<ruby>絶妙<rt>ぜつみょう</rt></ruby>ですね！<ruby>帰<rt>かえ</rt></ruby>りにお<ruby>土産<rt>みやげ</rt></ruby>の<ruby>生<rt>なま</rt></ruby><ruby>八<rt>やつ</rt></ruby>ツ<ruby>橋<rt>はし</rt></ruby>も<ruby>買<rt>か</rt></ruby>っていきます。","plain":"抹茶の香りと甘さが絶妙ですね！帰りにお土産の生八ツ橋も買っていきます。","ko":"말차 향이랑 단맛이 절묘하네요! 돌아갈 때 기념품으로 생야츠하시도 사 갈게요.","note":""}]}],"karaoke":[{"badge":"응용·옵션","title":"노래방 요금제(프리타임·음료무제한) 접수","lines":[{"speaker":"직원","role":"가라오케 직원","jp":"いらっしゃいませ！<ruby>何名<rt>なんめい</rt></ruby><ruby>様<rt>さま</rt></ruby>で<ruby>何時間<rt>なんじかん</rt></ruby>ほどご<ruby>利用<rt>りよう</rt></ruby>ですか？","plain":"いらっしゃいませ！何名様で何時間ほどご利用ですか？","ko":"어서 오세요! 몇 분이서 몇 시간 정도 이용하시겠어요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>三名<rt>さんめい</rt></ruby>です。<ruby>二時間<rt>にじかん</rt></ruby>コースとフリータイムはどちらがお<ruby>得<rt>とく</rt></ruby>ですか？","plain":"三名です。二時間コースとフリータイムはどちらがお得ですか？","ko":"3명입니다. 2시간 코스랑 프리타임 중에 어느 쪽이 더 이득인가요?","note":""},{"speaker":"직원","role":"가라오케 직원","jp":"<ruby>三時間<rt>さんじかん</rt></ruby><ruby>以上<rt>いじょう</rt></ruby><ruby>歌<rt>うた</rt></ruby>われるならフリータイムのほうが<ruby>安<rt>やす</rt></ruby>いですよ。ドリンクバー<ruby>付<rt>つ</rt></ruby>きか<ruby>飲み放題<rt>のみほうだい</rt></ruby>か<ruby>選<rt>えら</rt></ruby>べます。","plain":"三時間以上歌われるならフリータイムのほうが安いですよ。ドリンクバー付きか飲み放題か選べます。","ko":"3시간 이상 부르실 거면 프리타임이 훨씬 싸요. 음료 바 포함과 술 무제한 중에 고르실 수 있어요.","note":""},{"speaker":"나","role":"손님","jp":"じゃあ<ruby>飲み放題<rt>のみほうだい</rt></ruby><ruby>付<rt>つ</rt></ruby>きのフリータイムでお<ruby>願<rt>ねが</rt></ruby>いします！<ruby>禁煙<rt>きんえん</rt></ruby>ルームは<ruby>空<rt>あ</rt></ruby>いていますか？","plain":"じゃあ飲み放題付きのフリータイムでお願いします！禁煙ルームは空いていますか？","ko":"그럼 술 무제한 포함 프리타임으로 부탁드려요! 금연 방 비어 있나요?","note":""},{"speaker":"직원","role":"가라오케 직원","jp":"はい、<ruby>三〇五号室<rt>さんまるごごうしつ</rt></ruby>へどうぞ。デンモクで<ruby>食<rt>た</rt></ruby>べ<ruby>物<rt>もの</rt></ruby>も<ruby>注文<rt>ちゅうもん</rt></ruby>できますよ。","plain":"はい、三〇五号室へどうぞ。デンモクで食べ物も注文できますよ。","ko":"네, 305호실로 들어가세요. 리모컨 패드로 음식도 주문하실 수 있습니다.","note":""},{"speaker":"나","role":"손님","jp":"ありがとうございます！タンバリンも<ruby>一<rt>ひと</rt></ruby>つお<ruby>借<rt>か</rt></ruby>りできますか？","plain":"ありがとうございます！タンバリンも一つお借りできますか？","ko":"감사합니다! 탬버린도 하나 빌릴 수 있을까요?","note":""}]},{"badge":"트러블·마무리","title":"키 조절·채점 모드·막차 시간 확인","lines":[{"speaker":"켄지","role":"일본 친구","jp":"うわ、この<ruby>曲<rt>きょく</rt></ruby>めっちゃ<ruby>盛<rt>も</rt></ruby>り<ruby>上<rt>あ</rt></ruby>がるね！あなたの<ruby>十八番<rt>おはこ</rt></ruby>は<ruby>何<rt>なに</rt></ruby>？","plain":"うわ、この曲めっちゃ盛り上がるね！あなたの十八番は何？","ko":"우와, 이 노래 분위기 엄청 달아오른다! 네 애창곡(18번)은 뭐야?","note":"「十八番(おはこ)」= 애창곡 (じゅうはちばん 아님 주의!)."},{"speaker":"나","role":"나","jp":"<ruby>日本<rt>にほん</rt></ruby>の<ruby>有名<rt>ゆうめい</rt></ruby>なアニソンが<ruby>好<rt>す</rt></ruby>きなんだけど、<ruby>少<rt>すこ</rt></ruby>し<ruby>高<rt>たか</rt></ruby>いからキーを<ruby>二<rt>ふた</rt></ruby>つ<ruby>下<rt>さ</rt></ruby>げてくれる？","plain":"日本の有名なアニソンが好きなんだけど、少し高いからキーを二つ下げてくれる？","ko":"일본 유명한 애니 주제가를 좋아하는데 좀 높으니까 키를 두 개 내려줄래?","note":""},{"speaker":"켄지","role":"일본 친구","jp":"オッケー、エコーも<ruby>少<rt>すこ</rt></ruby>し<ruby>強<rt>つよ</rt></ruby>くしたよ！<ruby>採点<rt>さいてん</rt></ruby>モードにして<ruby>九十点<rt>きゅうじゅってん</rt></ruby>を<ruby>目指<rt>めざ</rt></ruby>そう！","plain":"オッケー、エコーも少し強くしたよ！採点モードにして九十点を目指そう！","ko":"오케이, 에코도 좀 세게 했어! 채점 모드로 켜고 90점 도전하자!","note":""},{"speaker":"나","role":"나","jp":"あ、ごめん、<ruby>間違<rt>まちが</rt></ruby>えた<ruby>曲<rt>きょく</rt></ruby>を<ruby>入<rt>い</rt></ruby>れちゃった！<ruby>演奏中止<rt>えんそうちゅうし</rt></ruby>ボタンを<ruby>押<rt>お</rt></ruby>してくれる？","plain":"あ、ごめん、間違えた曲を入れちゃった！演奏中止ボタンを押してくれる？","ko":"아 미안, 잘못된 곡을 넣었어! 연주 중지 버튼 좀 눌러 줄래?","note":""},{"speaker":"켄지","role":"일본 친구","jp":"<ruby>大丈夫<rt>だいじょうぶ</rt></ruby>だよ！サビのところはみんなでハモろう！…あ、もうすぐ<ruby>退室<rt>たいしつ</rt></ruby>の<ruby>時間<rt>じかん</rt></ruby>だ。","plain":"大丈夫だよ！サビのところはみんなでハモろう！…あ、もうすぐ退室の時間だ。","ko":"괜찮아! 후렴구는 다 같이 화음 넣자! …어, 벌써 퇴실 시간이네.","note":""},{"speaker":"나","role":"나","jp":"<ruby>延長<rt>えんちょう</rt></ruby>すると<ruby>終電<rt>しゅうでん</rt></ruby>を<ruby>逃<rt>のが</rt></ruby>しそうだから、<ruby>最後<rt>さいご</rt></ruby>のバラード<ruby>一曲<rt>いっきょく</rt></ruby>で<ruby>締<rt>し</rt></ruby>めて<ruby>帰<rt>かえ</rt></ruby>ろう！","plain":"延長すると終電を逃しそうだから、最後のバラード一曲で締めて帰ろう！","ko":"연장하면 막차를 놓칠 것 같으니 마지막 발라드 한 곡으로 마무리하고 가자!","note":""}]}],"gift":[{"badge":"응용·옵션","title":"백화점 지하 식품관 직장 선물·상온 보관 상담","lines":[{"speaker":"점원","role":"백화점 직원","jp":"いらっしゃいませ！どのような<ruby>用途<rt>ようと</rt></ruby>の<ruby>贈<rt>おく</rt></ruby>り<ruby>物<rt>もの</rt></ruby>をお<ruby>探<rt>さが</rt></ruby>しでしょうか？","plain":"いらっしゃいませ！どのような用途の贈り物をお探しでしょうか？","ko":"어서 오세요! 어떤 용도의 선물을 찾고 계신가요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>職場<rt>しょくば</rt></ruby>のばらまき<ruby>用<rt>よう</rt></ruby>のお<ruby>土産<rt>みやげ</rt></ruby>を<ruby>探<rt>さが</rt></ruby>しています。<ruby>予算<rt>よさん</rt></ruby>は<ruby>三千円<rt>さんぜんえん</rt></ruby><ruby>前後<rt>ぜんご</rt></ruby>で、<ruby>個包装<rt>こほうそう</rt></ruby>のものがいいです。","plain":"職場のばらまき用のお土産を探しています。予算は三千円前後で、個包装のものがいいです。","ko":"직장에서 나눠주기용 선물을 찾고 있어요. 예산은 3천 엔 전후에 개별포장된 게 좋아요.","note":""},{"speaker":"점원","role":"백화점 직원","jp":"それでしたら<ruby>東京駅<rt>とうきょうえき</rt></ruby><ruby>限定<rt>げんてい</rt></ruby>の<ruby>焼<rt>や</rt></ruby>き<ruby>菓子<rt>かし</rt></ruby>の<ruby>詰<rt>つ</rt></ruby>め<ruby>合<rt>あ</rt></ruby>わせが<ruby>定番<rt>ていばん</rt></ruby>で<ruby>一番<rt>いちばん</rt></ruby><ruby>人気<rt>にんき</rt></ruby>ですよ！","plain":"それでしたら東京駅限定の焼き菓子の詰め合わせが定番で一番人気ですよ！","ko":"그렇다면 도쿄역 한정 구움과자 모둠 세트가 스테디셀러로 제일 인기예요!","note":""},{"speaker":"나","role":"손님","jp":"わあ、パッケージも<ruby>可愛<rt>かわい</rt></ruby>いですね！<ruby>飛行機<rt>ひこうき</rt></ruby>に<ruby>乗<rt>の</rt></ruby>るので<ruby>常温<rt>じょうおん</rt></ruby>で<ruby>日持<rt>ひも</rt></ruby>ちしますか？","plain":"わあ、パッケージも可愛いですね！飛行機に乗るので常温で日持ちしますか？","ko":"와, 패키지도 귀엽네요! 비행기를 타야 해서 상온으로 오래 보관할 수 있나요?","note":"「日持ち(ひもち)」= 유통기한이 길어 오래감."},{"speaker":"점원","role":"백화점 직원","jp":"はい、<ruby>常温<rt>じょうおん</rt></ruby>で<ruby>二ヶ月<rt>にかげつ</rt></ruby>ほど<ruby>賞味期限<rt>しょうみきげん</rt></ruby>がございます。よろしければ<ruby>試食<rt>ししょく</rt></ruby>をどうぞ！","plain":"はい、常温で二ヶ月ほど賞味期限がございます。よろしければ試食をどうぞ！","ko":"네, 상온에서 두 달 정도 유통기한이 있어요. 괜찮으시면 시식해 보세요!","note":""},{"speaker":"나","role":"손님","jp":"すごく<ruby>美味<rt>おい</rt></ruby>しいです！これを<ruby>二箱<rt>ふたはこ</rt></ruby>と、<ruby>季節限定<rt>きせつげんてい</rt></ruby>の<ruby>抹茶スイーツ<rt>まっちゃすいーつ</rt></ruby>を<ruby>一箱<rt>ひとはこ</rt></ruby>ください。","plain":"すごく美味しいです！これを二箱と、季節限定の抹茶スイーツを一箱ください。","ko":"정말 맛있네요! 이거 두 상자랑 계절 한정 말차 디저트 한 상자 주세요.","note":""}]},{"badge":"트러블·마무리","title":"노시가미·보냉백·가격표 제거와 소분 봉투","lines":[{"speaker":"점원","role":"백화점 직원","jp":"こちらの<ruby>生菓子<rt>なまがし</rt></ruby>は<ruby>要冷蔵<rt>ようれいぞう</rt></ruby>になりますが、お<ruby>持<rt>も</rt></ruby>ち<ruby>歩<rt>ある</rt></ruby>きは<ruby>何時間<rt>なんじかん</rt></ruby>ほどでしょうか？","plain":"こちらの生菓子は要冷蔵になりますが、お持ち歩きは何時間ほどでしょうか？","ko":"이 생과자는 냉장 보관이 필요한데, 들고 이동하시는 시간이 몇 시간 정도 되시나요?","note":""},{"speaker":"나","role":"손님","jp":"ホテルまで<ruby>二時間<rt>にじかん</rt></ruby>ほどかかるので、<ruby>保冷剤<rt>ほれいざい</rt></ruby>と<ruby>保冷バッグ<rt>ほれいばっぐ</rt></ruby>をつけていただけますか？","plain":"ホテルまで二時間ほどかかるので、保冷剤と保冷バッグをつけていただけますか？","ko":"호텔까지 두 시간 정도 걸려서 아이스팩이랑 보냉백 챙겨 주실 수 있나요?","note":""},{"speaker":"점원","role":"백화점 직원","jp":"かしこまりました！プレゼント<ruby>用<rt>よう</rt></ruby>のラッピングやのし<ruby>紙<rt>がみ</rt></ruby>はおつけしますか？","plain":"かしこまりました！プレゼント用のラッピングやのし紙はおつけしますか？","ko":"알겠습니다! 선물용 포장이나 노시가미(예절 띠지) 붙여 드릴까요?","note":"「のし紙(のしがみ)」= 일본 격식 선물용 띠지."},{"speaker":"나","role":"손님","jp":"<ruby>目上<rt>めうえ</rt></ruby>の<ruby>方<rt>かた</rt></ruby>への<ruby>手土産<rt>てみやげ</rt></ruby>なので<ruby>化粧箱入<rt>けしょうばこい</rt></ruby>りで、<ruby>値札<rt>ねふだ</rt></ruby>は<ruby>外<rt>はず</rt></ruby>してください。","plain":"目上の方への手土産なので化粧箱入りで、値札は外してください。","ko":"윗분께 드리는 방문 선물이라 고급 상자 포장으로 하고 가격표는 떼어 주세요.","note":""},{"speaker":"점원","role":"백화점 직원","jp":"もちろんです。お<ruby>渡<rt>わた</rt></ruby>し<ruby>用<rt>よう</rt></ruby>の<ruby>小分け袋<rt>こわけぶくろ</rt></ruby>は<ruby>何枚<rt>なんまい</rt></ruby>ご<ruby>用意<rt>ようい</rt></ruby>いたしましょうか？","plain":"もちろんです。お渡し用の小分け袋は何枚ご用意いたしましょうか？","ko":"물론이죠. 나눠 드리실 때 쓸 작은 쇼핑백은 몇 장 준비해 드릴까요?","note":""},{"speaker":"나","role":"손님","jp":"<ruby>紙袋<rt>かみぶくろ</rt></ruby>を<ruby>三枚<rt>さんまい</rt></ruby>お<ruby>願<rt>ねが</rt></ruby>いします！<ruby>無料<rt>むりょう</rt></ruby>のメッセージカードもあればいただけますか？","plain":"紙袋を三枚お願いします！無料のメッセージカードもあればいただけますか？","ko":"종이 쇼핑백 세 장 부탁드려요! 무료 메시지 카드도 있으면 받을 수 있을까요?","note":""}]}],"airport":[{"badge":"응용·옵션","title":"수하물 위탁·무게 초과·보조배터리 규정","lines":[{"speaker":"직원","role":"항공사 직원","jp":"パスポートと<ruby>搭乗券<rt>とうじょうけん</rt></ruby>を<ruby>拝見<rt>はいけん</rt></ruby>します。<ruby>受託手荷物<rt>じゅたくてにもつ</rt></ruby>は<ruby>一個<rt>いっこ</rt></ruby>でしょうか？","plain":"パスポートと搭乗券を拝見します。受託手荷物は一個でしょうか？","ko":"여권과 탑승권을 확인하겠습니다. 위탁 수하물은 1개이신가요?","note":""},{"speaker":"나","role":"승객","jp":"はい、スーツケースを<ruby>一<rt>ひと</rt></ruby>つ<ruby>預<rt>あず</rt></ruby>けます。<ruby>事前<rt>じぜん</rt></ruby>にオンラインチェックインを<ruby>済<rt>す</rt></ruby>ませました。","plain":"はい、スーツケースを一つ預けます。事前にオンラインチェックインを済ませました。","ko":"네, 캐리어 하나 부칠게요. 미리 온라인 체크인을 마쳤어요.","note":""},{"speaker":"직원","role":"항공사 직원","jp":"ありがとうございます。あ、<ruby>二<rt>に</rt></ruby><ruby>十<rt>じゅう</rt></ruby><ruby>五<rt>ご</rt></ruby>キロなので<ruby>二<rt>に</rt></ruby>キロ<ruby>重量オーバ<rt>じゅうりょうおーば</rt></ruby>ーになっています。","plain":"ありがとうございます。あ、二十五キロなので二キロ重量オーバーになっています。","ko":"감사합니다. 아, 25kg이라 2kg 무게 초과가 되었네요.","note":""},{"speaker":"나","role":"승객","jp":"すみません！<ruby>少<rt>すこ</rt></ruby>し<ruby>荷物<rt>にもつ</rt></ruby>を<ruby>機内持ち込<rt>きないもちこ</rt></ruby>みのバッグに<ruby>移<rt>うつ</rt></ruby>しますね。あと<ruby>壊<rt>こわ</rt></ruby>れ<ruby>物<rt>もの</rt></ruby>タグもお<ruby>願<rt>ねが</rt></ruby>いします。","plain":"すみません！少し荷物を機内持ち込みのバッグに移しますね。あと壊れ物タグもお願いします。","ko":"죄송합니다! 짐을 좀 기내 반입 가방으로 옮길게요. 그리고 파손 주의 태그도 부탁드려요.","note":""},{"speaker":"직원","role":"항공사 직원","jp":"モバイルバッテリーやリチウム<ruby>電池<rt>でんち</rt></ruby>はスーツケースに<ruby>入<rt>はい</rt></ruby>っていませんか？","plain":"モバイルバッテリーやリチウム電池はスーツケースに入っていませんか？","ko":"보조배터리나 리튬 배터리는 캐리어 안에 안 들어 있나요?","note":""},{"speaker":"나","role":"승객","jp":"はい、パソコンと<ruby>一緒<rt>いっしょ</rt></ruby>に<ruby>手荷物<rt>てにもつ</rt></ruby>で<ruby>持ち込<rt>もちこ</rt></ruby>みます。<ruby>座席<rt>ざせき</rt></ruby>は<ruby>通路側<rt>つうろがわ</rt></ruby>でお<ruby>願<rt>ねが</rt></ruby>いできますか？","plain":"はい、パソコンと一緒に手荷物で持ち込みます。座席は通路側でお願いできますか？","ko":"네, 노트북이랑 같이 기내 수하물로 들고 탑니다. 좌석은 복도 쪽으로 부탁드릴 수 있을까요?","note":""}]},{"badge":"트러블·마무리","title":"비행 지연·환승 시간 확인과 기내 요청","lines":[{"speaker":"나","role":"승객","jp":"すみません、ソウル<ruby>行<rt>ゆ</rt></ruby>きの<ruby>便<rt>びん</rt></ruby>が<ruby>三十分<rt>さんじゅっぷん</rt></ruby><ruby>遅延<rt>ちえん</rt></ruby>していると<ruby>表示<rt>ひょうじ</rt></ruby>が<ruby>出<rt>で</rt></ruby>ていますが、<ruby>搭乗口<rt>とうじょうぐち</rt></ruby>は<ruby>変<rt>か</rt></ruby>わりますか？","plain":"すみません、ソウル行きの便が三十分遅延していると表示が出ていますが、搭乗口は変わりますか？","ko":"저기요, 서울행 비행기가 30분 지연된다고 뜨는데 탑승 게이트가 바뀌나요?","note":""},{"speaker":"직원","role":"항공사 직원","jp":"いいえ、<ruby>百十二番<rt>ひゃくじゅうにばん</rt></ruby>ゲートのままです。<ruby>悪天候<rt>あくてんこう</rt></ruby>のためご<ruby>迷惑<rt>めいわく</rt></ruby>をおかけし<ruby>申し訳<rt>もうしわけ</rt></ruby>ございません。","plain":"いいえ、百十二番ゲートのままです。悪天候のためご迷惑をおかけし申し訳ございません。","ko":"아니요, 112번 게이트 그대로입니다. 악천후로 불편을 드려 죄송합니다.","note":""},{"speaker":"나","role":"승객","jp":"<ruby>保安検査場<rt>ほあんけんさじょう</rt></ruby>が<ruby>混<rt>こ</rt></ruby>んでいたので<ruby>早<rt>はや</rt></ruby>めに<ruby>着<rt>つ</rt></ruby>いてよかったです。<ruby>搭乗時刻<rt>とうじょうじこく</rt></ruby>までラウンジで<ruby>待<rt>ま</rt></ruby>てますか？","plain":"保安検査場が混んでいたので早めに着いてよかったです。搭乗時刻までラウンジで待てますか？","ko":"보안 검색대가 붐벼서 일찍 도착하길 잘했네요. 탑승 시각까지 라운지에서 기다릴 수 있나요?","note":""},{"speaker":"직원","role":"항공사 직원","jp":"はい、<ruby>免税店<rt>めんぜいてん</rt></ruby>のすぐ<ruby>奥<rt>おく</rt></ruby>にラウンジがございます。<ruby>出発<rt>しゅっぱつ</rt></ruby><ruby>二<rt>に</rt></ruby><ruby>十分<rt>じゅっぷん</rt></ruby><ruby>前<rt>まえ</rt></ruby>までにゲートへお<ruby>越<rt>こ</rt></ruby>しください。","plain":"はい、免税店のすぐ奥にラウンジがございます。出発二十分前までにゲートへお越しください。","ko":"네, 면세점 바로 안쪽에 라운지가 있습니다. 출발 20분 전까지 게이트로 와 주세요.","note":""},{"speaker":"나","role":"승객","jp":"わかりました！ちなみに<ruby>機内<rt>きない</rt></ruby>で<ruby>少<rt>すこ</rt></ruby>し<ruby>寒<rt>さむ</rt></ruby>いときブランケットは<ruby>借<rt>か</rt></ruby>りられますか？","plain":"わかりました！ちなみに機内で少し寒いときブランケットは借りられますか？","ko":"알겠습니다! 혹시 기내에서 조금 추울 때 담요를 빌릴 수 있나요?","note":""},{"speaker":"직원","role":"항공사 직원","jp":"もちろんです。<ruby>乗務員<rt>じょうむいん</rt></ruby>にお<ruby>気軽<rt>きがる</rt></ruby>にお<ruby>声<rt>こえ</rt></ruby>がけくださいね。<ruby>良<rt>よ</rt></ruby>いご<ruby>旅行<rt>りょこう</rt></ruby>を！","plain":"もちろんです。乗務員にお気軽にお声がけくださいね。良いご旅行を！","ko":"물론이죠. 승무원에게 편히 말씀해 주세요. 즐거운 여행 되세요!","note":""}]}],"museum":[{"badge":"응용·옵션","title":"미술관 입장·음성 가이드·사진 촬영 규정","lines":[{"speaker":"직원","role":"미술관 안내","jp":"いらっしゃいませ。<ruby>企画展<rt>きかくてん</rt></ruby>の<ruby>日時指定予約<rt>にちじしていよやく</rt></ruby>はお<ruby>済<rt>ず</rt></ruby>みでしょうか？","plain":"いらっしゃいませ。企画展の日時指定予約はお済みでしょうか？","ko":"어서 오세요. 기획전 날짜·시간 지정 예약은 하셨나요?","note":""},{"speaker":"나","role":"관람객","jp":"はい、オンラインで<ruby>前売り券<rt>まえうりけん</rt></ruby>を<ruby>買<rt>か</rt></ruby>いました。<ruby>常設展<rt>じょうせつてん</rt></ruby>もセットで<ruby>見<rt>み</rt></ruby>られますか？","plain":"はい、オンラインで前売り券を買いました。常設展もセットで見られますか？","ko":"네, 온라인으로 사전 예매권을 샀어요. 상설전도 세트로 볼 수 있나요?","note":""},{"speaker":"직원","role":"미술관 안내","jp":"はい、こちらのチケットで<ruby>両方<rt>りょうほう</rt></ruby>ご<ruby>覧<rt>らん</rt></ruby>いただけます。<ruby>韓国語<rt>かんこくご</rt></ruby>の<ruby>音声<rt>おんせい</rt></ruby>ガイドとパンフレットもございますよ。","plain":"はい、こちらのチケットで両方ご覧いただけます。韓国語の音声ガイドとパンフレットもございますよ。","ko":"네, 이 티켓으로 둘 다 관람하실 수 있어요. 한국어 음성 가이드와 안내 책자도 있습니다.","note":""},{"speaker":"나","role":"관람객","jp":"<ruby>音声<rt>おんせい</rt></ruby>ガイドを<ruby>一<rt>ひと</rt></ruby>つお<ruby>借<rt>か</rt></ruby>りします！<ruby>館内<rt>かんない</rt></ruby>は<ruby>写真撮影<rt>しゃしんさつえい</rt></ruby>しても<ruby>大丈夫<rt>だいじょうぶ</rt></ruby>ですか？","plain":"音声ガイドを一つお借りします！館内は写真撮影しても大丈夫ですか？","ko":"음성 가이드 하나 빌릴게요! 관내에서 사진 촬영해도 괜찮나요?","note":""},{"speaker":"직원","role":"미술관 안내","jp":"<ruby>一部<rt>いちぶ</rt></ruby>の<ruby>撮影禁止<rt>さつえいきんし</rt></ruby>エリアを<ruby>除<rt>のぞ</rt></ruby>き、フラッシュなしなら<ruby>撮影<rt>さつえい</rt></ruby><ruby>可能<rt>かのう</rt></ruby>です。<ruby>大<rt>おお</rt></ruby>きいお<ruby>荷物<rt>にもつ</rt></ruby>はコインロッカーへどうぞ。","plain":"一部の撮影禁止エリアを除き、フラッシュなしなら撮影可能です。大きいお荷物はコインロッカーへどうぞ。","ko":"일부 촬영 금지 구역을 제외하고 플래시 없이 촬영 가능합니다. 큰 짐은 코인 라커에 맡겨 주세요.","note":""},{"speaker":"나","role":"관람객","jp":"わかりました！<ruby>今日<rt>きょう</rt></ruby>の<ruby>閉館時間<rt>へいかんじかん</rt></ruby>は<ruby>何時<rt>なんじ</rt></ruby>ですか？","plain":"わかりました！今日の閉館時間は何時ですか？","ko":"알겠습니다! 오늘 폐관 시간은 몇 시인가요?","note":""}]},{"badge":"트러블·마무리","title":"작품 감상 나누기와 뮤지엄 숍 도록 구매","lines":[{"speaker":"유이","role":"일본 친구","jp":"<ruby>今回<rt>こんかい</rt></ruby>の<ruby>印象派<rt>いんしょうは</rt></ruby>の<ruby>展示<rt>てんじ</rt></ruby>、すごく<ruby>感動<rt>かんどう</rt></ruby>したね！どの<ruby>作品<rt>さくひん</rt></ruby>が<ruby>一番<rt>いちばん</rt></ruby><ruby>印象的<rt>いんしょうてき</rt></ruby>だった？","plain":"今回の印象派の展示、すごく感動したね！どの作品が一番印象的だった？","ko":"이번 인상파 전시 정말 감동적이었지! 어떤 작품이 제일 인상적이었어?","note":""},{"speaker":"나","role":"나","jp":"<ruby>光と影<rt>ひかりとかげ</rt></ruby>の<ruby>色使<rt>いろづか</rt></ruby>いが<ruby>繊細<rt>せんさい</rt></ruby>な<ruby>油絵<rt>あぶらえ</rt></ruby>がすごかったよ！<ruby>実物<rt>じつぶつ</rt></ruby>は<ruby>写真<rt>しゃしん</rt></ruby>よりずっと<ruby>迫力<rt>はくりょく</rt></ruby>があるね。","plain":"光と影の色使いが繊細な油絵がすごかったよ！実物は写真よりずっと迫力があるね。","ko":"빛과 그림자 색감이 섬세한 유화가 대단했어! 실물은 사진보다 훨씬 박력이 넘치네.","note":""},{"speaker":"유이","role":"일본 친구","jp":"わかる！<ruby>解説パネル<rt>かいせつぱねる</rt></ruby>と<ruby>学芸員<rt>がくげいいん</rt></ruby>さんの<ruby>説明<rt>せつめい</rt></ruby>を<ruby>聞<rt>き</rt></ruby>いて、<ruby>画家<rt>がか</rt></ruby>の<ruby>世界観<rt>せかいかん</rt></ruby>がもっとよくわかったよ。","plain":"わかる！解説パネルと学芸員さんの説明を聞いて、画家の世界観がもっとよくわかったよ。","ko":"공감해! 해설판이랑 큐레이터 설명을 들으니까 화가의 세계관이 훨씬 잘 이해되더라.","note":""},{"speaker":"나","role":"나","jp":"<ruby>現代アート<rt>げんだいあーと</rt></ruby>の<ruby>彫刻<rt>ちょうこく</rt></ruby>も<ruby>見<rt>み</rt></ruby>る<ruby>人<rt>ひと</rt></ruby>によって<ruby>解釈<rt>かいしゃく</rt></ruby>が<ruby>違<rt>ちが</rt></ruby>って<ruby>面白<rt>おもしろ</rt></ruby>かったね。<ruby>心地<rt>ごこち</rt></ruby>よい<ruby>余韻<rt>よいん</rt></ruby>が<ruby>残<rt>のこ</rt></ruby>るよ。","plain":"現代アートの彫刻も見る人によって解釈が違って面白かったね。心地よい余韻が残るよ。","ko":"현대 미술 조각도 보는 사람마다 해석이 달라서 재미있었어. 기분 좋은 여운이 남네.","note":""},{"speaker":"유이","role":"일본 친구","jp":"<ruby>帰<rt>かえ</rt></ruby>りにミュージアムショップに<ruby>寄<rt>よ</rt></ruby>らない？<ruby>記念<rt>きねん</rt></ruby>に<ruby>図録<rt>ずろく</rt></ruby>とポストカードを<ruby>買<rt>か</rt></ruby>いたいな。","plain":"帰りにミュージアムショップに寄らない？記念に図録とポストカードを買いたいな。","ko":"돌아갈 때 뮤지엄 숍에 들를래? 기념으로 전시 도록이랑 엽서 사고 싶어.","note":"「図録(ずろく)」= 전시 작품집(도록)."},{"speaker":"나","role":"나","jp":"いいね！<ruby>平日<rt>へいじつ</rt></ruby>の<ruby>午前<rt>ごぜん</rt></ruby><ruby>中<rt>なか</rt></ruby>だったから<ruby>混雑<rt>こんざつ</rt></ruby>も<ruby>少<rt>すく</rt></ruby>なくてゆっくり<ruby>見<rt>み</rt></ruby>られて<ruby>最高<rt>さいこう</rt></ruby>だったよ。","plain":"いいね！平日の午前中だったから混雑も少なくてゆっくり見られて最高だったよ。","ko":"좋아! 평일 오전이라 혼잡도 적어서 여유롭게 볼 수 있어서 최고였어.","note":""}]}],"weather":[{"badge":"응용·옵션","title":"장마·소나기·폭염 날씨 스몰토크","lines":[{"speaker":"사토","role":"일본 지인","jp":"おはようございます！<ruby>今日<rt>きょう</rt></ruby>は<ruby>朝<rt>あさ</rt></ruby>から<ruby>蒸<rt>む</rt></ruby>し<ruby>暑<rt>あつ</rt></ruby>いですね。","plain":"おはようございます！今日は朝から蒸し暑いですね。","ko":"안녕하세요! 오늘은 아침부터 후덥지근하네요.","note":""},{"speaker":"나","role":"나","jp":"<ruby>本当<rt>ほんとう</rt></ruby>にそうですね！<ruby>天気予報<rt>てんきよほう</rt></ruby>を<ruby>見<rt>み</rt></ruby>たら、<ruby>今日<rt>きょう</rt></ruby>の<ruby>最高気温<rt>さいこうきおん</rt></ruby>は<ruby>三十五度<rt>さんじゅうごど</rt></ruby>らしいですよ。","plain":"本当にそうですね！天気予報を見たら、今日の最高気温は三十五度らしいですよ。","ko":"정말 그렇네요! 일기예보를 보니 오늘 최고 기온이 35도라고 해요.","note":""},{"speaker":"사토","role":"일본 지인","jp":"うわ、<ruby>連日<rt>れんじつ</rt></ruby><ruby>猛暑<rt>もうしょ</rt></ruby>が<ruby>続<rt>つづ</rt></ruby>いていますね。<ruby>午後<rt>ごご</rt></ruby>の<ruby>降水確率<rt>こうすいかくりつ</rt></ruby>も<ruby>高<rt>たか</rt></ruby>いんですか？","plain":"うわ、連日猛暑が続いていますね。午後の降水確率も高いんですか？","ko":"우와, 연일 폭염이 이어지고 있네요. 오후 강수 확률도 높은가요?","note":""},{"speaker":"나","role":"나","jp":"<ruby>夕方<rt>ゆうがた</rt></ruby>から<ruby>急<rt>きゅう</rt></ruby>なにわか<ruby>雨<rt>あめ</rt></ruby>が<ruby>降<rt>ふ</rt></ruby>るそうなので、<ruby>念<rt>ねん</rt></ruby>のため<ruby>折<rt>お</rt></ruby>り<ruby>畳<rt>たた</rt></ruby>み<ruby>傘<rt>がさ</rt></ruby>を<ruby>持<rt>も</rt></ruby>ってきました。","plain":"夕方から急なにわか雨が降るそうなので、念のため折り畳み傘を持ってきました。","ko":"저녁부터 갑자기 소나기가 내린다고 해서 혹시 몰라 접이식 우산을 챙겨 왔어요.","note":""},{"speaker":"사토","role":"일본 지인","jp":"さすがですね！<ruby>梅雨<rt>つゆ</rt></ruby>の<ruby>時期<rt>じき</rt></ruby>は<ruby>湿気<rt>しっけ</rt></ruby>がすごくて<ruby>大変<rt>たいへん</rt></ruby>ですが、そろそろ<ruby>梅雨明<rt>つゆあ</rt></ruby>けしそうです。","plain":"さすがですね！梅雨の時期は湿気がすごくて大変ですが、そろそろ梅雨明けしそうです。","ko":"역시 준비성 좋으시네요! 장마철엔 습기가 심해 힘든데 슬슬 장마가 끝날 것 같아요.","note":""},{"speaker":"나","role":"나","jp":"<ruby>熱中症<rt>ねっちゅうしょう</rt></ruby><ruby>対策<rt>たいさく</rt></ruby>に<ruby>日焼け止<rt>ひやけど</rt></ruby>めと<ruby>水分補給<rt>すいぶんほきゅう</rt></ruby>を<ruby>忘<rt>わす</rt></ruby>れないようにしないとですね。","plain":"熱中症対策に日焼け止めと水分補給を忘れないようにしないとですね。","ko":"열사병 예방으로 선크림이랑 수분 보충을 잊지 말아야겠어요.","note":""}]},{"badge":"트러블·마무리","title":"일교차·꽃가루 알레르기와 사계절 화제","lines":[{"speaker":"사토","role":"일본 지인","jp":"<ruby>最近<rt>さいきん</rt></ruby>、<ruby>朝晩<rt>あさばん</rt></ruby>の<ruby>寒暖差<rt>かんだんさ</rt></ruby>が<ruby>大<rt>おお</rt></ruby>きいですね。<ruby>体調<rt>たいちょう</rt></ruby>は<ruby>大丈夫<rt>だいじょうぶ</rt></ruby>ですか？","plain":"最近、朝晩の寒暖差が大きいですね。体調は大丈夫ですか？","ko":"요즘 아침저녁 일교차가 크네요. 컨디션은 괜찮으세요?","note":""},{"speaker":"나","role":"나","jp":"ありがとうございます。<ruby>夜<rt>よる</rt></ruby>はぐっと<ruby>冷<rt>ひ</rt></ruby>え<ruby>込<rt>こ</rt></ruby>むので、<ruby>週末<rt>しゅうまつ</rt></ruby>に<ruby>衣替<rt>ころもが</rt></ruby>えをしました。","plain":"ありがとうございます。夜はぐっと冷え込むので、週末に衣替えをしました。","ko":"감사합니다. 밤에는 부쩍 추워져서 주말에 계절 옷 정리를 했어요.","note":"「衣替え(ころもがえ)」= 계절 바뀔 때 옷 정리."},{"speaker":"사토","role":"일본 지인","jp":"<ruby>私<rt>わたし</rt></ruby>は<ruby>春先<rt>はるさき</rt></ruby>の<ruby>花粉症<rt>かふんしょう</rt></ruby>が<ruby>少<rt>すこ</rt></ruby>しつらいんですが、<ruby>日本<rt>にほん</rt></ruby>は<ruby>十月<rt>じゅうがつ</rt></ruby>が<ruby>一番<rt>いちばん</rt></ruby><ruby>過<rt>す</rt></ruby>ごしやすい<ruby>季節<rt>きせつ</rt></ruby>ですよ。","plain":"私は春先の花粉症が少しつらいんですが、日本は十月が一番過ごしやすい季節ですよ。","ko":"저는 초봄 꽃가루 알레르기가 좀 힘든데, 일본은 10월이 제일 지내기 좋은 계절이에요.","note":""},{"speaker":"나","role":"나","jp":"<ruby>十一月<rt>じゅういちがつ</rt></ruby>に<ruby>日光<rt>にっこう</rt></ruby>へ<ruby>紅葉狩<rt>もみじが</rt></ruby>りに<ruby>行<rt>い</rt></ruby>く<ruby>予定<rt>よてい</rt></ruby>なんです！<ruby>防寒対策<rt>ぼうかんたいさく</rt></ruby>はどれくらい<ruby>必要<rt>ひつよう</rt></ruby>ですか？","plain":"十一月に日光へ紅葉狩りに行く予定なんです！防寒対策はどれくらい必要ですか？","ko":"11월에 닛코로 단풍 구경 갈 예정이에요! 방한 대비는 어느 정도 필요할까요?","note":""},{"speaker":"사토","role":"일본 지인","jp":"<ruby>山<rt>やま</rt></ruby>のほうは<ruby>体感温度<rt>たいかんおんど</rt></ruby>が<ruby>低<rt>ひく</rt></ruby>いので、<ruby>厚手<rt>あつで</rt></ruby>のコートとマフラーがあると<ruby>安心<rt>あんしん</rt></ruby>ですよ。","plain":"山のほうは体感温度が低いので、厚手のコートとマフラーがあると安心ですよ。","ko":"산 쪽은 체감 온도가 낮으니까 두꺼운 코트랑 목도리가 있으면 안심이에요.","note":""},{"speaker":"나","role":"나","jp":"<ruby>教<rt>おし</rt></ruby>えていただきありがとうございます！<ruby>来年<rt>らいねん</rt></ruby>の<ruby>春<rt>はる</rt></ruby>は<ruby>満開<rt>まんかい</rt></ruby>の<ruby>桜前線<rt>さくらぜんせん</rt></ruby>も<ruby>見<rt>み</rt></ruby>てみたいです。","plain":"教えていただきありがとうございます！来年の春は満開の桜前線も見てみたいです。","ko":"알려 주셔서 감사합니다! 내년 봄에는 만개한 벚꽃 전선도 보고 싶어요.","note":""}]}],"intro":[{"badge":"응용·옵션","title":"네트워킹·명함 교환 예절과 업무 소개","lines":[{"speaker":"타나카","role":"교류회 참가자","jp":"はじめまして！IT<ruby>企業<rt>きぎょう</rt></ruby>で<ruby>企画<rt>きかく</rt></ruby>を<ruby>担当<rt>たんとう</rt></ruby>している<ruby>田中<rt>たなか</rt></ruby>と<ruby>申<rt>もう</rt></ruby>します。よろしければ<ruby>名刺<rt>めいし</rt></ruby>をどうぞ。","plain":"はじめまして！IT企業で企画を担当している田中と申します。よろしければ名刺をどうぞ。","ko":"처음 뵙겠습니다! IT 기업에서 기획을 담당하는 다나카라고 합니다. 괜찮으시면 명함 받으세요.","note":""},{"speaker":"나","role":"나","jp":"<ruby>頂戴<rt>ちょうだい</rt></ruby>いたします！<ruby>田中<rt>たなか</rt></ruby><ruby>様<rt>さま</rt></ruby>ですね。<ruby>私<rt>わたし</rt></ruby>は<ruby>韓国<rt>かんこく</rt></ruby>から<ruby>参<rt>まい</rt></ruby>りました。<ruby>普段<rt>ふだん</rt></ruby>は<ruby>監査<rt>かんさ</rt></ruby>とコンプライアンスの<ruby>仕事<rt>しごと</rt></ruby>をしています。","plain":"頂戴いたします！田中様ですね。私は韓国から参りました。普段は監査とコンプライアンスの仕事をしています。","ko":"감사히 받겠습니다! 다나카 님이시군요. 저는 한국에서 왔습니다. 평소에는 감사와 컴플라이언스 업무를 하고 있어요.","note":"명함은 두 손으로 받으며 「頂戴いたします(ちょうだいいたします)」."},{"speaker":"타나카","role":"교류회 참가자","jp":"すごいご<ruby>専門<rt>せんもん</rt></ruby>ですね！<ruby>日本語<rt>にほんご</rt></ruby>がとてもお<ruby>上手<rt>じょうず</rt></ruby>ですが、<ruby>勉強<rt>べんきょう</rt></ruby>のきっかけは<ruby>何<rt>なん</rt></ruby>だったんですか？","plain":"すごいご専門ですね！日本語がとてもお上手ですが、勉強のきっかけは何だったんですか？","ko":"대단한 전문 분야시네요! 일본어를 정말 잘하시는데 공부하신 계기가 무엇이었나요?","note":""},{"speaker":"나","role":"나","jp":"<ruby>日本旅行<rt>にほんりょこう</rt></ruby>と<ruby>仕事<rt>しごと</rt></ruby>での<ruby>交流<rt>こうりゅう</rt></ruby>がきっかけで、<ruby>毎日<rt>まいにち</rt></ruby><ruby>少<rt>すこ</rt></ruby>しずつ<ruby>語学学習<rt>ごがくがくしゅう</rt></ruby>を<ruby>続<rt>つづ</rt></ruby>けています。","plain":"日本旅行と仕事での交流がきっかけで、毎日少しずつ語学学習を続けています。","ko":"일본 여행과 업무 교류가 계기가 되어 매일 조금씩 외국어 학습을 이어가고 있어요.","note":""},{"speaker":"타나카","role":"교류회 참가자","jp":"<ruby>素晴<rt>すば</rt></ruby>らしい<ruby>継続力<rt>けいぞくりょく</rt></ruby>ですね！<ruby>今日<rt>きょう</rt></ruby>は<ruby>異業種交流会<rt>いぎょうしゅこうりゅうかい</rt></ruby>なので、いろいろな<ruby>方<rt>かた</rt></ruby>と<ruby>情報交換<rt>じょうほうこうかん</rt></ruby>できると<ruby>嬉<rt>うれ</rt></ruby>しいです。","plain":"素晴らしい継続力ですね！今日は異業種交流会なので、いろいろな方と情報交換できると嬉しいです。","ko":"훌륭한 꾸준함이시네요! 오늘 이업종 교류회라 다양한 분들과 정보 교류할 수 있으면 좋겠어요.","note":""},{"speaker":"나","role":"나","jp":"こちらこそ<ruby>素敵<rt>すてき</rt></ruby>なご<ruby>縁<rt>えん</rt></ruby>に<ruby>感謝<rt>かんしゃ</rt></ruby>です！<ruby>肩書<rt>かたが</rt></ruby>きを<ruby>気<rt>き</rt></ruby>にせず<ruby>気軽<rt>きがる</rt></ruby>に<ruby>話<rt>はな</rt></ruby>しましょう。","plain":"こちらこそ素敵なご縁に感謝です！肩書きを気にせず気軽に話しましょう。","ko":"저야말로 멋진 인연에 감사합니다! 직함 신경 쓰지 말고 편하게 이야기 나눠요.","note":""}]},{"badge":"트러블·마무리","title":"공통점 찾기·연락처 교환과 다음 만남 기약","lines":[{"speaker":"타나카","role":"교류회 참가자","jp":"ちなみに<ruby>最近<rt>さいきん</rt></ruby>ハマっている<ruby>趣味<rt>しゅみ</rt></ruby>やマイブームはありますか？","plain":"ちなみに最近ハマっている趣味やマイブームはありますか？","ko":"혹시 요즘 푹 빠져 있는 취미나 관심사가 있으신가요?","note":""},{"speaker":"나","role":"나","jp":"<ruby>最近<rt>さいきん</rt></ruby>はAIツールを<ruby>使<rt>つか</rt></ruby>って<ruby>学習<rt>がくしゅう</rt></ruby>アプリを<ruby>作<rt>つく</rt></ruby>ったり、カフェ<ruby>巡<rt>めぐ</rt></ruby>りをしたりしています。","plain":"最近はAIツールを使って学習アプリを作ったり、カフェ巡りをしたりしています。","ko":"요즘은 AI 도구를 써서 학습 앱을 만들거나 카페 투어를 다니고 있어요.","note":""},{"speaker":"타나카","role":"교류회 참가자","jp":"ええっ、<ruby>私<rt>わたし</rt></ruby>もAI<ruby>開発<rt>かいはつ</rt></ruby>に<ruby>興味<rt>きょうみ</rt></ruby>があるんです！<ruby>思<rt>おも</rt></ruby>わぬ<ruby>共通点<rt>きょうつうてん</rt></ruby>があって<ruby>意気投合<rt>いきとうごう</rt></ruby>しましたね。","plain":"ええっ、私もAI開発に興味があるんです！思わぬ共通点があって意気投合しましたね。","ko":"어머, 저도 AI 개발에 관심이 많아요! 뜻밖의 공통점이 있어서 금방 의기투합했네요.","note":""},{"speaker":"나","role":"나","jp":"とても<ruby>話<rt>はな</rt></ruby>しやすくて<ruby>時間<rt>じかん</rt></ruby>が<ruby>経<rt>た</rt></ruby>つのが<ruby>早<rt>はや</rt></ruby>いです！よければSNSかLINEを<ruby>交換<rt>こうかん</rt></ruby>しませんか？","plain":"とても話しやすくて時間が経つのが早いです！よければSNSかLINEを交換しませんか？","ko":"말씀 나누기 너무 편해서 시간이 금방 가네요! 괜찮으시면 SNS나 라인 교환할까요?","note":""},{"speaker":"타나카","role":"교류회 참가자","jp":"ぜひ！いつもSNSでご<ruby>活躍<rt>かつやく</rt></ruby>を<ruby>拝見<rt>はいけん</rt></ruby>できたら<ruby>嬉<rt>うれ</rt></ruby>しいです。また<ruby>今度<rt>こんど</rt></ruby>ゆっくりお<ruby>話<rt>はな</rt></ruby>ししましょう。","plain":"ぜひ！いつもSNSでご活躍を拝見できたら嬉しいです。また今度ゆっくりお話ししましょう。","ko":"꼭이요! SNS에서 활약하시는 모습 자주 볼 수 있으면 좋겠어요. 다음에 또 여유롭게 이야기 나눠요.","note":""},{"speaker":"나","role":"나","jp":"はい、ぜひ<ruby>仲良<rt>なかよ</rt></ruby>くしてください！<ruby>今日<rt>きょう</rt></ruby>は<ruby>本当<rt>ほんとう</rt></ruby>にありがとうございました、またお<ruby>会<rt>あ</rt></ruby>いしましょう！","plain":"はい、ぜひ仲良くしてください！今日は本当にありがとうございました、またお会いしましょう！","ko":"네, 앞으로 친하게 지내요! 오늘 정말 감사했습니다, 꼭 또 봬요!","note":""}]}],"interview":[{"badge":"응용·옵션","title":"자기 어필·강점·단점 보완과 이직 사유 답변","lines":[{"speaker":"면접관","role":"인사 담당자","jp":"<ruby>本日<rt>ほんじつ</rt></ruby>はお<ruby>越<rt>こ</rt></ruby>しいただきありがとうございます。まずは<ruby>一分<rt>いっぷん</rt></ruby><ruby>程度<rt>ていど</rt></ruby>で<ruby>自己PR<rt>じこぴーあーる</rt></ruby>をお<ruby>願<rt>ねが</rt></ruby>いします。","plain":"本日はお越しいただきありがとうございます。まずは一分程度で自己PRをお願いします。","ko":"오늘 와 주셔서 감사합니다. 먼저 1분 정도로 자기 어필을 부탁드립니다.","note":""},{"speaker":"나","role":"지원자","jp":"はい。<ruby>私<rt>わたし</rt></ruby>の<ruby>強<rt>つよ</rt></ruby>みはデータに<ruby>基<rt>もと</rt></ruby>づいた<ruby>課題解決力<rt>かだいかいけつりょく</rt></ruby>とチームワークです。<ruby>前職<rt>ぜんしょく</rt></ruby>では<ruby>業務<rt>ぎょうむ</rt></ruby><ruby>効率<rt>こうりつ</rt></ruby>を<ruby>三<rt>さん</rt></ruby><ruby>十<rt>じゅう</rt></ruby>パーセント<ruby>改善<rt>かいぜん</rt></ruby>した<ruby>実績<rt>じっせき</rt></ruby>があります。","plain":"はい。私の強みはデータに基づいた課題解決力とチームワークです。前職では業務効率を三十パーセント改善した実績があります。","ko":"네. 제 강점은 데이터 기반의 문제 해결력과 팀워크입니다. 전 직장에서는 업무 효율을 30% 개선한 실적이 있습니다.","note":""},{"speaker":"면접관","role":"인사 담당자","jp":"<ruby>素晴<rt>すば</rt></ruby>らしい<ruby>実績<rt>じっせき</rt></ruby>ですね。<ruby>反対<rt>はんたい</rt></ruby>に、ご<ruby>自身<rt>じしん</rt></ruby>の<ruby>短所<rt>たんしょ</rt></ruby>とそれをどう<ruby>補<rt>おぎな</rt></ruby>っているかも<ruby>教<rt>おし</rt></ruby>えていただけますか？","plain":"素晴らしい実績ですね。反対に、ご自身の短所とそれをどう補っているかも教えていただけますか？","ko":"훌륭한 실적이시네요. 반대로 본인의 단점과 그것을 어떻게 보완하고 계신지도 알려 주실 수 있나요?","note":""},{"speaker":"나","role":"지원자","jp":"<ruby>慎重<rt>しんちょう</rt></ruby>になりすぎる<ruby>面<rt>めん</rt></ruby>があるため、<ruby>優先順位<rt>ゆうせんじゅんい</rt></ruby>を<ruby>決<rt>き</rt></ruby>めてチェックリストで<ruby>管理<rt>かんり</rt></ruby>するよう<ruby>心<rt>こころ</rt></ruby>がけています。","plain":"慎重になりすぎる面があるため、優先順位を決めてチェックリストで管理するよう心がけています。","ko":"지나치게 신중해지는 면이 있어서 우선순위를 정해 체크리스트로 관리하려고 노력하고 있습니다.","note":""},{"speaker":"면접관","role":"인사 담당자","jp":"なるほど。<ruby>今回<rt>こんかい</rt></ruby>、<ruby>転職<rt>てんしょく</rt></ruby>を<ruby>決意<rt>けつい</rt></ruby>された<ruby>理由<rt>りゆう</rt></ruby>と<ruby>御社<rt>おんしゃ</rt></ruby>への<ruby>志望動機<rt>しぼうどうき</rt></ruby>をお<ruby>聞<rt>き</rt></ruby>かせください。","plain":"なるほど。今回、転職を決意された理由と御社への志望動機をお聞かせください。","ko":"그렇군요. 이번에 이직을 결심하신 이유와 당사에 지원하신 동기를 들려주세요.","note":"지원자는 상대 회사를 「御社(おんしゃ)」라고 높여 불러요."},{"speaker":"나","role":"지원자","jp":"<ruby>御社<rt>おんしゃ</rt></ruby>の<ruby>企業理念<rt>きぎょうりねん</rt></ruby>に<ruby>深<rt>ふか</rt></ruby>く<ruby>共感<rt>きょうかん</rt></ruby>し、これまでの<ruby>経験<rt>けいけん</rt></ruby>を<ruby>活<rt>い</rt></ruby>かして<ruby>即戦力<rt>そくせんりょく</rt></ruby>として<ruby>貢献<rt>こうけん</rt></ruby>したいと<ruby>考<rt>かんが</rt></ruby>え<ruby>志望<rt>しぼう</rt></ruby>いたしました。","plain":"御社の企業理念に深く共感し、これまでの経験を活かして即戦力として貢献したいと考え志望いたしました。","ko":"귀사의 기업 이념에 깊이 공감했고, 지금까지의 경험을 살려 즉시 전력으로 기여하고 싶어 지원했습니다.","note":""}]},{"badge":"트러블·마무리","title":"커리어 플랜·역질문과 퇴실 예절","lines":[{"speaker":"면접관","role":"인사 담당자","jp":"<ruby>入社後<rt>にゅうしゃご</rt></ruby>、どのようなキャリアプランを<ruby>描<rt>えが</rt></ruby>いていますか？また、<ruby>入社時期<rt>にゅうしゃじき</rt></ruby>のご<ruby>希望<rt>きぼう</rt></ruby>はありますか？","plain":"入社後、どのようなキャリアプランを描いていますか？また、入社時期のご希望はありますか？","ko":"입사 후 어떤 커리어 플랜을 그리고 계신가요? 그리고 희망하시는 입사 시기가 있으신가요?","note":""},{"speaker":"나","role":"지원자","jp":"<ruby>入社後<rt>にゅうしゃご</rt></ruby>はまず<ruby>現場<rt>げんば</rt></ruby>の<ruby>業務<rt>ぎょうむ</rt></ruby>を<ruby>正確<rt>せいかく</rt></ruby>に<ruby>把握<rt>はあく</rt></ruby>し、<ruby>将来的<rt>しょうらいてき</rt></ruby>にはプロジェクトを<ruby>牽引<rt>けんいん</rt></ruby>したいです。<ruby>引<rt>ひ</rt></ruby>き<ruby>継<rt>つ</rt></ruby>ぎのため<ruby>来月<rt>らいげつ</rt></ruby>から<ruby>入社<rt>にゅうしゃ</rt></ruby><ruby>可能<rt>かのう</rt></ruby>です。","plain":"入社後はまず現場の業務を正確に把握し、将来的にはプロジェクトを牽引したいです。引き継ぎのため来月から入社可能です。","ko":"입사 후엔 먼저 현장 업무를 정확히 파악하고, 장래에는 프로젝트를 이끌고 싶습니다. 인수인계 때문에 다음 달부터 입사 가능합니다.","note":""},{"speaker":"면접관","role":"인사 담당자","jp":"<ruby>承知<rt>しょうち</rt></ruby>しました。<ruby>最後<rt>さいご</rt></ruby>に<ruby>質疑応答<rt>しつぎおうとう</rt></ruby>の<ruby>時間<rt>じかん</rt></ruby>です。<ruby>何<rt>なに</rt></ruby>か<ruby>逆質問<rt>ぎゃくしつもん</rt></ruby>はございますか？","plain":"承知しました。最後に質疑応答の時間です。何か逆質問はございますか？","ko":"알겠습니다. 마지막으로 질의응답 시간입니다. 혹시 궁금한 점(역질문)이 있으신가요?","note":""},{"speaker":"나","role":"지원자","jp":"はい。<ruby>配属<rt>はいぞく</rt></ruby><ruby>予定<rt>よてい</rt></ruby>のチームで<ruby>現在<rt>げんざい</rt></ruby><ruby>最<rt>もっと</rt></ruby>も<ruby>重視<rt>じゅうし</rt></ruby>されている<ruby>課題<rt>かだい</rt></ruby>や、<ruby>活躍<rt>かつやく</rt></ruby>されている<ruby>方<rt>かた</rt></ruby>の<ruby>共通点<rt>きょうつうてん</rt></ruby>を<ruby>教<rt>おし</rt></ruby>えていただけますか？","plain":"はい。配属予定のチームで現在最も重視されている課題や、活躍されている方の共通点を教えていただけますか？","ko":"네. 배치 예정 팀에서 현재 가장 중시하는 과제나 활약하시는 분들의 공통점을 여쭤봐도 될까요?","note":"일본 면접에서 역질문(逆質問)은 입사 의지를 보여주는 핵심 기회!"},{"speaker":"면접관","role":"인사 담당자","jp":"<ruby>主体性<rt>しゅたいせい</rt></ruby>を<ruby>持<rt>も</rt></ruby>って<ruby>報連相<rt>ほうれんそう</rt></ruby>できる<ruby>方<rt>かた</rt></ruby>が<ruby>活躍<rt>かつやく</rt></ruby>しています。<ruby>選考<rt>せんこう</rt></ruby><ruby>結果<rt>けっか</rt></ruby>は<ruby>一週間<rt>いっしゅうかん</rt></ruby><ruby>以内<rt>いない</rt></ruby>にご<ruby>連絡<rt>れんらく</rt></ruby>いたします。","plain":"主体性を持って報連相できる方が活躍しています。選考結果は一週間以内にご連絡いたします。","ko":"주도성을 가지고 보고·연락·상담을 잘하는 분이 활약하고 있습니다. 전형 결과는 일주일 이내에 연락드리겠습니다.","note":""},{"speaker":"나","role":"지원자","jp":"<ruby>本日<rt>ほんじつ</rt></ruby>は<ruby>貴重<rt>きちょう</rt></ruby>なお<ruby>時間<rt>じかん</rt></ruby>をいただき<ruby>本当<rt>ほんとう</rt></ruby>にありがとうございました。<ruby>失礼<rt>しつれい</rt></ruby>いたします。","plain":"本日は貴重なお時間をいただき本当にありがとうございました。失礼いたします。","ko":"오늘 귀한 시간 내어 주셔서 정말 감사했습니다. 실례하겠습니다.","note":""}]}],"meeting":[{"badge":"응용·옵션","title":"화상회의 시작·화면 공유·결론 우선 보고","lines":[{"speaker":"진행자","role":"프로젝트 매니저","jp":"<ruby>皆様<rt>みなさま</rt></ruby>お<ruby>集<rt>あつ</rt></ruby>まりいただきありがとうございます。<ruby>音声<rt>おんせい</rt></ruby>ははっきり<ruby>聞<rt>き</rt></ruby>こえますか？","plain":"皆様お集まりいただきありがとうございます。音声ははっきり聞こえますか？","ko":"모두 모여 주셔서 감사합니다. 음성은 선명하게 잘 들리시나요?","note":""},{"speaker":"나","role":"참석자","jp":"はい、よく<ruby>聞<rt>き</rt></ruby>こえています！<ruby>本日<rt>ほんじつ</rt></ruby>のアジェンダを<ruby>チャット欄<rt>ちゃっとらん</rt></ruby>に<ruby>共有<rt>きょうゆう</rt></ruby>しました。","plain":"はい、よく聞こえています！本日のアジェンダをチャット欄に共有しました。","ko":"네, 잘 들립니다! 오늘 회의 안건을 채팅창에 공유했습니다.","note":""},{"speaker":"진행자","role":"프로젝트 매니저","jp":"ありがとうございます。<ruby>議事録作成<rt>ぎじろくさくせい</rt></ruby>のため<ruby>録画<rt>ろくが</rt></ruby>してもよろしいでしょうか？では<ruby>本題<rt>ほんだい</rt></ruby>に<ruby>入<rt>はい</rt></ruby>りましょう。","plain":"ありがとうございます。議事録作成のため録画してもよろしいでしょうか？では本題に入りましょう。","ko":"감사합니다. 회의록 작성을 위해 녹화해도 괜찮을까요? 그럼 본론으로 들어갑시다.","note":""},{"speaker":"나","role":"참석자","jp":"<ruby>画面共有<rt>がめんきょうゆう</rt></ruby>しますね。<ruby>結論から言<rt>けつろんからい</rt></ruby>うと、<ruby>来週<rt>らいしゅう</rt></ruby>のリリースは<ruby>予定<rt>よてい</rt></ruby><ruby>通<rt>とお</rt></ruby>り<ruby>可能<rt>かのう</rt></ruby>です。","plain":"画面共有しますね。結論から言うと、来週のリリースは予定通り可能です。","ko":"화면 공유하겠습니다. 결론부터 말씀드리면 다음 주 출시는 예정대로 가능합니다.","note":"비즈니스 보고는 「結論から言うと」로 핵심부터!"},{"speaker":"진행자","role":"프로젝트 매니저","jp":"よかったです！<ruby>今<rt>いま</rt></ruby>の<ruby>点<rt>た</rt></ruby>について<ruby>一点<rt>いってん</rt></ruby>だけ<ruby>補足<rt>ほそく</rt></ruby>していただけますか？","plain":"よかったです！今の点について一点だけ補足していただけますか？","ko":"다행이네요! 방금 내용에 대해 한 가지만 보충 설명해 주실 수 있을까요?","note":""},{"speaker":"나","role":"참석자","jp":"はい、<ruby>関係部署<rt>かんけいぶしょ</rt></ruby>との<ruby>認識合<rt>にんしきあ</rt></ruby>わせも<ruby>完了<rt>かんりょう</rt></ruby>しており、ネクストアクションを<ruby>資料<rt>しりょう</rt></ruby>に<ruby>落とし込<rt>おとしこ</rt></ruby>みました。","plain":"はい、関係部署との認識合わせも完了しており、ネクストアクションを資料に落とし込みました。","ko":"네, 관련 부서와 인식 맞추기도 완료했고 후속 조치를 자료에 구체적으로 반영해 두었습니다.","note":""}]},{"badge":"트러블·마무리","title":"음소거·하울링·화면 멈춤 대처와 회의 퇴장","lines":[{"speaker":"진행자","role":"프로젝트 매니저","jp":"すみません、<ruby>少<rt>すこ</rt></ruby>しミュートになっているようです。マイクをオンにしていただけますか？","plain":"すみません、少しミュートになっているようです。マイクをオンにしていただけますか？","ko":"죄송합니다, 잠깐 음소거가 되어 있는 것 같아요. 마이크를 켜 주실 수 있을까요?","note":""},{"speaker":"나","role":"참석자","jp":"<ruby>失礼<rt>しつれい</rt></ruby>しました！<ruby>今<rt>いま</rt></ruby><ruby>聞<rt>き</rt></ruby>こえますか？<ruby>少<rt>すこ</rt></ruby>しハウリングしているのでイヤホンに<ruby>切<rt>き</rt></ruby>り<ruby>替<rt>か</rt></ruby>えますね。","plain":"失礼しました！今聞こえますか？少しハウリングしているのでイヤホンに切り替えますね。","ko":"실례했습니다! 지금 들리시나요? 조금 하울링이 생겨서 이어폰으로 전환할게요.","note":""},{"speaker":"진행자","role":"프로젝트 매니저","jp":"あ、<ruby>先<rt>さき</rt></ruby>ほど<ruby>電波<rt>でんぱ</rt></ruby>の<ruby>関係<rt>かんけい</rt></ruby>で<ruby>画面<rt>がめん</rt></ruby>が<ruby>固<rt>かた</rt></ruby>まり、<ruby>最後<rt>さいご</rt></ruby>の<ruby>音声<rt>おんせい</rt></ruby>が<ruby>途切<rt>とぎ</rt></ruby>れてしまいました。","plain":"あ、先ほど電波の関係で画面が固まり、最後の音声が途切れてしまいました。","ko":"아, 방금 전파 문제로 화면이 멈춰서 마지막 음성이 끊겨 버렸어요.","note":""},{"speaker":"나","role":"참석자","jp":"<ruby>申し訳<rt>もうしわけ</rt></ruby>ありません、<ruby>一度<rt>いちど</rt></ruby><ruby>退出<rt>たいしつ</rt></ruby>してすぐ<ruby>再接続<rt>さいせつぞく</rt></ruby>します！スライドの<ruby>右側<rt>みぎがわ</rt></ruby>が<ruby>見切<rt>みき</rt></ruby>れていませんか？","plain":"申し訳ありません、一度退出してすぐ再接続します！スライドの右側が見切れていませんか？","ko":"죄송합니다, 한 번 나갔다가 바로 재접속할게요! 슬라이드 오른쪽이 잘려 보이지는 않나요?","note":""},{"speaker":"진행자","role":"프로젝트 매니저","jp":"<ruby>今<rt>いま</rt></ruby>はバッチリ<ruby>見<rt>み</rt></ruby>えています！では<ruby>時間厳守<rt>じかんげんしゅ</rt></ruby>のため<ruby>本日<rt>ほんじつ</rt></ruby>の<ruby>会議<rt>かいぎ</rt></ruby>は<ruby>以上<rt>いじょう</rt></ruby>とします。","plain":"今はバッチリ見えています！では時間厳守のため本日の会議は以上とします。","ko":"지금은 완벽하게 잘 보여요! 그럼 시간 엄수를 위해 오늘 회의는 여기까지 하겠습니다.","note":""},{"speaker":"나","role":"참석자","jp":"ありがとうございます！<ruby>次<rt>つぎ</rt></ruby>の<ruby>会議<rt>かいぎ</rt></ruby>があるためお<ruby>先<rt>さき</rt></ruby>に<ruby>失礼<rt>しつれい</rt></ruby>します。お<ruby>疲<rt>つか</rt></ruby>れ<ruby>様<rt>さま</rt></ruby>でした！","plain":"ありがとうございます！次の会議があるためお先に失礼します。お疲れ様でした！","ko":"감사합니다! 다음 회의가 있어서 먼저 실례하겠습니다. 수고하셨습니다!","note":""}]}],"dinner":[{"badge":"응용·옵션","title":"상석 안내·건배사와 술·음식 배려 매너","lines":[{"speaker":"거래처","role":"거래처 임원","jp":"<ruby>本日<rt>ほんじつ</rt></ruby>はお<ruby>忙<rt>いそが</rt></ruby>しいところお<ruby>越<rt>こ</rt></ruby>しいただき、<ruby>誠<rt>まこと</rt></ruby>にありがとうございます。","plain":"本日はお忙しいところお越しいただき、誠にありがとうございます。","ko":"오늘 바쁘신 와중에 와 주셔서 진심으로 감사합니다.","note":""},{"speaker":"나","role":"참석자","jp":"こちらこそ、いつも<ruby>大変<rt>たいへん</rt></ruby>お<ruby>世話<rt>せわ</rt></ruby>になっております。どうぞ<ruby>奥<rt>おく</rt></ruby>の<ruby>上座<rt>かみざ</rt></ruby>にお<ruby>掛<rt>か</rt></ruby>けください。","plain":"こちらこそ、いつも大変お世話になっております。どうぞ奥の上座にお掛けください。","ko":"저야말로 늘 큰 신세를 지고 있습니다. 부디 안쪽 상석에 앉아 주세요.","note":"「上座(かみざ)」= 출입구에서 가장 먼 안쪽 상석."},{"speaker":"거래처","role":"거래처 임원","jp":"<ruby>恐れ入<rt>おそれい</rt></ruby>ります。それでは<ruby>恐れ入<rt>おそれい</rt></ruby>りますが<ruby>乾杯の音頭<rt>かんぱいのおんど</rt></ruby>をお<ruby>願<rt>ねが</rt></ruby>いしてもよろしいでしょうか？","plain":"恐れ入ります。それでは恐れ入りますが乾杯の音頭をお願いしてもよろしいでしょうか？","ko":"송구스럽습니다. 그럼 죄송하지만 건배사를 부탁드려도 될까요?","note":""},{"speaker":"나","role":"참석자","jp":"<ruby>光栄<rt>こうえい</rt></ruby>です！<ruby>皆様<rt>みなさま</rt></ruby>のご<ruby>健勝<rt>けんしょう</rt></ruby>と<ruby>今後<rt>こんご</rt></ruby>のさらなる<ruby>発展<rt>はってん</rt></ruby>を<ruby>祈念<rt>きねん</rt></ruby>いたしまして、<ruby>乾杯<rt>かんぱい</rt></ruby>！","plain":"光栄です！皆様のご健勝と今後のさらなる発展を祈念いたしまして、乾杯！","ko":"영광입니다! 여러분의 건승과 앞으로의 더 큰 발전을 기원하며, 건배!","note":""},{"speaker":"거래처","role":"거래처 임원","jp":"こちらは<ruby>旬<rt>しゅん</rt></ruby>の<ruby>食材<rt>しょくざい</rt></ruby>を<ruby>使<rt>つか</rt></ruby>ったお<ruby>店<rt>みせ</rt></ruby>の<ruby>名物<rt>めいぶつ</rt></ruby>です。お<ruby>口<rt>くち</rt></ruby>に<ruby>合<rt>あ</rt></ruby>うといいのですが。","plain":"こちらは旬の食材を使ったお店の名物です。お口に合うといいのですが。","ko":"이것은 제철 식재료를 쓴 이 가게의 명물입니다. 입맛에 맞으시면 좋겠네요.","note":""},{"speaker":"나","role":"참석자","jp":"<ruby>本当<rt>ほんとう</rt></ruby>に<ruby>絶品<rt>ぜっぴん</rt></ruby>ですね！<ruby>大皿<rt>おおざら</rt></ruby>の<ruby>料理<rt>りょうり</rt></ruby>、<ruby>私<rt>わたし</rt></ruby>からお<ruby>取<rt>と</rt></ruby>り<ruby>分<rt>わ</rt></ruby>けいたしましょうか？","plain":"本当に絶品ですね！大皿の料理、私からお取り分けいたしましょうか？","ko":"정말 일품이네요! 큰 접시 요리, 제가 덜어드릴까요?","note":"「お取り分け」= 음식을 앞접시에 덜어드리는 일본 회식 매너."}]},{"badge":"트러블·마무리","title":"무알코올 양해·계산 배려·배웅과 다음 날 인사","lines":[{"speaker":"거래처","role":"거래처 임원","jp":"よろしければ<ruby>日本酒<rt>にほんしゅ</rt></ruby>を<ruby>一杯<rt>いっぱい</rt></ruby>お<ruby>酌<rt>しゃく</rt></ruby>させてください。お<ruby>飲<rt>の</rt></ruby>み<ruby>物<rt>もの</rt></ruby>のお<ruby>代<rt>か</rt></ruby>わりはいかがですか？","plain":"よろしければ日本酒を一杯お酌させてください。お飲み物のお代わりはいかがですか？","ko":"괜찮으시면 사케 한 잔 따라드리겠습니다. 음료 한 잔 더 하시겠어요?","note":""},{"speaker":"나","role":"참석자","jp":"お<ruby>気遣<rt>きづか</rt></ruby>いありがとうございます！<ruby>明日<rt>あした</rt></ruby>の<ruby>朝<rt>あさ</rt></ruby><ruby>早<rt>はや</rt></ruby>いので、<ruby>次<rt>つぎ</rt></ruby>はノンアルコールで<ruby>失礼<rt>しつれい</rt></ruby>します。","plain":"お気遣いありがとうございます！明日の朝早いので、次はノンアルコールで失礼します。","ko":"세심한 배려 감사합니다! 내일 아침이 일찍 있어서 다음은 무알코올로 실례하겠습니다.","note":""},{"speaker":"거래처","role":"거래처 임원","jp":"もちろんです、<ruby>無礼講<rt>ぶれいこう</rt></ruby>でゆっくり<ruby>楽<rt>たの</rt></ruby>しんでくださいね。<ruby>苦手<rt>にがて</rt></ruby>なものはありませんでしたか？","plain":"もちろんです、無礼講でゆっくり楽しんでくださいね。苦手なものはありませんでしたか？","ko":"물론이죠, 격식 없이 편하게 즐기세요. 못 드시는 음식은 없으셨나요?","note":"「無礼講(ぶれいこう)」= 상하 격식 없이 편히 즐김."},{"speaker":"나","role":"참석자","jp":"どれも<ruby>大変<rt>たいへん</rt></ruby><ruby>美味<rt>おい</rt></ruby>しくいただきました。ささやかですが<ruby>韓国<rt>かんこく</rt></ruby>の<ruby>手土産<rt>てみやげ</rt></ruby>をお<ruby>持<rt>も</rt></ruby>ちしました。","plain":"どれも大変美味しくいただきました。ささやかですが韓国の手土産をお持ちしました。","ko":"어느 것 하나 빠짐없이 정말 맛있게 먹었습니다. 소소하지만 한국 답례 선물을 준비해 왔습니다.","note":""},{"speaker":"거래처","role":"거래처 임원","jp":"まあ、<ruby>恐縮<rt>きょうしゅく</rt></ruby>です！お<ruby>会計<rt>かいけい</rt></ruby>はすでに<ruby>済<rt>す</rt></ruby>んでおりますので、どうぞこのままお<ruby>立<rt>た</rt></ruby>ちください。","plain":"まあ、恐縮です！お会計はすでに済んでおりますので、どうぞこのままお立ちください。","ko":"어머, 몸 둘 바를 모르겠습니다! 계산은 이미 마쳤으니 편히 일어나세요.","note":""},{"speaker":"나","role":"참석자","jp":"ご<ruby>馳走様<rt>ちそうさま</rt></ruby>でした！おかげさまで<ruby>親睦<rt>しんぼく</rt></ruby>を<ruby>深<rt>ふか</rt></ruby>められました。<ruby>今後<rt>こんご</rt></ruby>ともよろしくお<ruby>願<rt>ねが</rt></ruby>いいたします。","plain":"ご馳走様でした！おかげさまで親睦を深められました。今後ともよろしくお願いいたします。","ko":"잘 먹었습니다! 덕분에 친목을 깊이 다질 수 있었습니다. 앞으로도 잘 부탁드립니다.","note":""}]}],"apology":[{"badge":"응용·옵션","title":"일정 중복(더블부킹) 사과와 대안 후보일 조율","lines":[{"speaker":"나","role":"담당자","jp":"お<ruby>忙<rt>いそが</rt></ruby>しいところ<ruby>恐れ入<rt>おそれい</rt></ruby>りますが、<ruby>来週<rt>らいしゅう</rt></ruby><ruby>火曜日<rt>かようび</rt></ruby>の<ruby>打ち合<rt>うちあ</rt></ruby>わせの<ruby>件<rt>けん</rt></ruby>でご<ruby>相談<rt>そうだん</rt></ruby>があります。","plain":"お忙しいところ恐れ入りますが、来週火曜日の打ち合わせの件でご相談があります。","ko":"바쁘신 와중에 송구스럽지만 다음 주 화요일 미팅 건으로 상의드릴 일이 있습니다.","note":"「恐れ入りますが」= 일본 비즈니스 대표 쿠션어."},{"speaker":"상대방","role":"파트너사","jp":"はい、どうなさいましたか？","plain":"はい、どうなさいましたか？","ko":"네, 무슨 일이신가요?","note":""},{"speaker":"나","role":"담당자","jp":"<ruby>誠<rt>まこと</rt></ruby>に<ruby>申し訳<rt>もうしわけ</rt></ruby>ございません。<ruby>急遽<rt>きゅうきょ</rt></ruby>、<ruby>役員<rt>やくいん</rt></ruby><ruby>会議<rt>かいぎ</rt></ruby>とバッティングしてしまいリスケをお<ruby>願<rt>ねが</rt></ruby>いしたいのです。","plain":"誠に申し訳ございません。急遽、役員会議とバッティングしてしまいリスケをお願いしたいのです。","ko":"진심으로 죄송합니다. 갑작스레 임원 회의와 일정이 겹쳐서 일정 변경을 부탁드리고 싶습니다.","note":""},{"speaker":"상대방","role":"파트너사","jp":"そうでしたか。ご<ruby>都合<rt>つごう</rt></ruby>のよろしい<ruby>候補日<rt>こうほび</rt></ruby>をいくつかいただけますか？","plain":"そうでしたか。ご都合のよろしい候補日をいくつかいただけますか？","ko":"그러셨군요. 편하신 후보 날짜를 몇 개 알려 주실 수 있나요?","note":""},{"speaker":"나","role":"담당자","jp":"<ruby>差<rt>さ</rt></ruby>し<ruby>支<rt>つか</rt></ruby>えなければ<ruby>水曜日<rt>すいようび</rt></ruby>の<ruby>十四時<rt>じゅうよじ</rt></ruby>、または<ruby>木曜日<rt>もくようび</rt></ruby>の<ruby>午前<rt>ごぜん</rt></ruby><ruby>中<rt>なか</rt></ruby>はいかがでしょうか？","plain":"差し支えなければ水曜日の十四時、または木曜日の午前中はいかがでしょうか？","ko":"괜찮으시다면 수요일 오후 2시, 또는 목요일 오전은 어떠신가요?","note":""},{"speaker":"상대방","role":"파트너사","jp":"<ruby>水曜日<rt>すいようび</rt></ruby>の<ruby>十四時<rt>じゅうよじ</rt></ruby>なら<ruby>空<rt>あ</rt></ruby>いていますよ。そちらで<ruby>調整<rt>ちょうせい</rt></ruby>しましょう！","plain":"水曜日の十四時なら空いていますよ。そちらで調整しましょう！","ko":"수요일 오후 2시면 비어 있어요. 그 시간으로 조율합시다!","note":""}]},{"badge":"트러블·마무리","title":"정중한 제안 거절·확인 부족 사과와 재발 방지","lines":[{"speaker":"상대방","role":"거래처","jp":"<ruby>先日<rt>せんじつ</rt></ruby>ご<ruby>提案<rt>ていあん</rt></ruby>した<ruby>新<rt>あたら</rt></ruby>プランですが、ご<ruby>検討<rt>けんとう</rt></ruby>いただけましたでしょうか？","plain":"先日ご提案した新プランですが、ご検討いただけましたでしょうか？","ko":"지난번에 제안드린 새 플랜, 검토해 보셨을까요?","note":""},{"speaker":"나","role":"담당자","jp":"せっかくのご<ruby>提案<rt>ていあん</rt></ruby>なのですが、<ruby>今回<rt>こんかい</rt></ruby>は<ruby>予算<rt>よさん</rt></ruby>の<ruby>都合<rt>つごう</rt></ruby>で<ruby>見送<rt>みおく</rt></ruby>らせていただきたく、ご<ruby>期待<rt>きたい</rt></ruby>に<ruby>沿<rt>そ</rt></ruby>えず<ruby>恐縮<rt>きょうしゅく</rt></ruby>です。","plain":"せっかくのご提案なのですが、今回は予算の都合で見送らせていただきたく、ご期待に沿えず恐縮です。","ko":"모처럼의 제안이지만 이번에는 예산 사정상 보류하고자 합니다. 기대에 부응하지 못해 송구합니다.","note":"「見送る / ご期待に沿えず」= 상대를 존중하는 부드러운 거절 표현."},{"speaker":"상대방","role":"거래처","jp":"<ruby>承知<rt>しょうち</rt></ruby>しました。また<ruby>別<rt>べつ</rt></ruby>の<ruby>代替案<rt>だいたいあん</rt></ruby>がございましたらぜひご<ruby>提案<rt>ていあん</rt></ruby>しますね。","plain":"承知しました。また別の代替案がございましたらぜひご提案しますね。","ko":"알겠습니다. 또 다른 대안이 있으면 꼭 제안드리겠습니다.","note":""},{"speaker":"나","role":"담당자","jp":"あ、それと<ruby>先週<rt>せんしゅう</rt></ruby>の<ruby>資料<rt>しりょう</rt></ruby>の<ruby>数字<rt>すうじ</rt></ruby>に<ruby>誤<rt>あやま</rt></ruby>りがありました。こちらの<ruby>確認不足<rt>かくにんぶそく</rt></ruby>で<ruby>大変<rt>たいへん</rt></ruby><ruby>失礼<rt>しつれい</rt></ruby>いたしました。","plain":"あ、それと先週の資料の数字に誤りがありました。こちらの確認不足で大変失礼いたしました。","ko":"아, 그리고 지난주 자료 숫자에 오류가 있었습니다. 저희 측 확인 부족으로 대단히 실례했습니다.","note":""},{"speaker":"상대방","role":"거래처","jp":"すぐにご<ruby>連絡<rt>れんらく</rt></ruby>いただきありがとうございます。<ruby>修正版<rt>しゅうせいばん</rt></ruby>を<ruby>確認<rt>かくにん</rt></ruby>しましたので<ruby>大丈夫<rt>だいじょうぶ</rt></ruby>ですよ。","plain":"すぐにご連絡いただきありがとうございます。修正版を確認しましたので大丈夫ですよ。","ko":"바로 연락 주셔서 감사합니다. 수정본 확인했으니 괜찮습니다.","note":""},{"speaker":"나","role":"담당자","jp":"<ruby>寛大<rt>かんだい</rt></ruby>なご<ruby>対応<rt>たいおう</rt></ruby>に<ruby>心<rt>こころ</rt></ruby>より<ruby>感謝申し上<rt>かんしゃもうしあ</rt></ruby>げます。<ruby>今後<rt>こんご</rt></ruby>はチェック<ruby>体制<rt>たいせい</rt></ruby>を<ruby>強化<rt>きょうか</rt></ruby>し<ruby>再発防止<rt>さいはつぼうし</rt></ruby>を<ruby>徹底<rt>てってい</rt></ruby>いたします。","plain":"寛大なご対応に心より感謝申し上げます。今後はチェック体制を強化し再発防止を徹底いたします。","ko":"너그러운 대응에 진심으로 감사드립니다. 앞으로 점검 체계를 강화해 재발 방지를 철저히 하겠습니다.","note":""}]}],"glasses":[{"badge":"응용·옵션","title":"압축 렌즈·변색/김서림 방지·안과 처방전 제작","lines":[{"speaker":"나","role":"손님","jp":"すみません、<ruby>眼科<rt>がんか</rt></ruby>の<ruby>処方箋<rt>しょほうせん</rt></ruby>を<ruby>持<rt>も</rt></ruby>ってきたのですが、この<ruby>度数<rt>どすう</rt></ruby>で<ruby>作<rt>つく</rt></ruby>れますか？","plain":"すみません、眼科の処方箋を持ってきたのですが、この度数で作れますか？","ko":"저기요, 안과 처방전을 가져왔는데 이 도수로 만들 수 있나요?","note":""},{"speaker":"코바야시","role":"안경점 스태프","jp":"はい、<ruby>有効期限<rt>ゆうこうきげん</rt></ruby><ruby>内<rt>ない</rt></ruby>ですのでそのままお<ruby>作<rt>つく</rt></ruby>りできます！<ruby>少<rt>すこ</rt></ruby>し<ruby>近視<rt>きんし</rt></ruby>と<ruby>乱視<rt>らんし</rt></ruby>が<ruby>強<rt>つよ</rt></ruby>めですね。","plain":"はい、有効期限内ですのでそのままお作りできます！少し近視と乱視が強めですね。","ko":"네, 유효기간 안이라서 그대로 제작 가능합니다! 근시와 난시가 조금 있는 편이시네요.","note":""},{"speaker":"나","role":"손님","jp":"レンズが<ruby>厚<rt>あつ</rt></ruby>くならないように<ruby>薄型レンズ<rt>うすがたれんず</rt></ruby>にしたいんですが、<ruby>追加料金<rt>ついかりょうきん</rt></ruby>はかかりますか？","plain":"レンズが厚くならないように薄型レンズにしたいんですが、追加料金はかかりますか？","ko":"렌즈가 두꺼워지지 않게 압축 렌즈로 하고 싶은데 추가 요금이 드나요?","note":""},{"speaker":"코바야시","role":"안경점 스태프","jp":"<ruby>標準<rt>ひょうじゅん</rt></ruby><ruby>セット価格<rt>せっとかかく</rt></ruby>に<ruby>薄型レンズ<rt>うすがたれんず</rt></ruby>とUVカットは<ruby>含<rt>ふく</rt></ruby>まれていますよ！<ruby>調光レンズ<rt>ちょうこうれんず</rt></ruby>や<ruby>曇り止<rt>くもりど</rt></ruby>め<ruby>加工<rt>かこう</rt></ruby>はオプションです。","plain":"標準セット価格に薄型レンズとUVカットは含まれていますよ！調光レンズや曇り止め加工はオプションです。","ko":"기본 세트 가격에 압축 렌즈와 자외선 차단이 포함되어 있어요! 변색 렌즈나 김 서림 방지 가공은 옵션입니다.","note":""},{"speaker":"나","role":"손님","jp":"わあ、お<ruby>得<rt>とく</rt></ruby>ですね！<ruby>外<rt>はず</rt></ruby>でサングラスになる<ruby>調光レンズ<rt>ちょうこうれんず</rt></ruby>と<ruby>二本目<rt>にほんめ</rt></ruby><ruby>割引<rt>わりびき</rt></ruby>も<ruby>気<rt>き</rt></ruby>になります。","plain":"わあ、お得ですね！外でサングラスになる調光レンズと二本目割引も気になります。","ko":"와, 알뜰하네요! 밖에서 선글라스가 되는 변색 렌즈랑 2개째 할인도 궁금해요.","note":""},{"speaker":"코바야시","role":"안경점 스태프","jp":"<ruby>二本目<rt>にほんめ</rt></ruby><ruby>割引<rt>わりびき</rt></ruby>は<ruby>十<rt>じゅう</rt></ruby>パーセントオフになります。パスポートがあれば<ruby>免税手続<rt>めんぜいてつづ</rt></ruby>きもできますよ！","plain":"二本目割引は十パーセントオフになります。パスポートがあれば免税手続きもできますよ！","ko":"2개째 할인은 10% 할인됩니다. 여권이 있으시면 면세 절차도 가능해요!","note":""}]},{"badge":"트러블·마무리","title":"다초점 적응·어지러움 교환 보증과 무료 A/S","lines":[{"speaker":"나","role":"손님","jp":"<ruby>先日<rt>せんじつ</rt></ruby>こちらで<ruby>作<rt>つく</rt></ruby>った<ruby>遠近両用<rt>えんきんりょうよう</rt></ruby>メガネなんですが、<ruby>少<rt>すこ</rt></ruby>し<ruby>度数<rt>どすう</rt></ruby>が<ruby>強<rt>つよ</rt></ruby>くてクラクラする<ruby>感<rt>かん</rt></ruby>じがします。","plain":"先日こちらで作った遠近両用メガネなんですが、少し度数が強くてクラクラする感じがします。","ko":"지난번에 여기서 맞춘 다초점 안경인데 도수가 조금 세서 어지러운 느낌이 들어요.","note":""},{"speaker":"코바야시","role":"안경점 스태프","jp":"お<ruby>不便<rt>ふべん</rt></ruby>をおかけして<ruby>申し訳<rt>もうしわけ</rt></ruby>ございません！<ruby>累進レンズ<rt>るいしんれんず</rt></ruby>は<ruby>慣<rt>な</rt></ruby>れるまで<ruby>端<rt>はし</rt></ruby>にゆがみを<ruby>感<rt>かん</rt></ruby>じやすいんです。","plain":"お不便をおかけして申し訳ございません！累進レンズは慣れるまで端にゆがみを感じやすいんです。","ko":"불편을 드려 죄송합니다! 누진 렌즈는 적응할 때까지 가장자리에 왜곡이 느껴지기 쉬워요.","note":""},{"speaker":"나","role":"손님","jp":"<ruby>手元<rt>てもと</rt></ruby>の<ruby>文字<rt>もじ</rt></ruby>ははっきり<ruby>見<rt>み</rt></ruby>えるんですが、<ruby>階段<rt>かいだん</rt></ruby>を<ruby>降<rt>お</rt></ruby>りるとき<ruby>少<rt>すこ</rt></ruby>し<ruby>怖<rt>こわ</rt></ruby>くて。<ruby>保証期間<rt>ほしょうきかん</rt></ruby><ruby>内<rt>ない</rt></ruby>なら<ruby>交換<rt>こうかん</rt></ruby>できますか？","plain":"手元の文字ははっきり見えるんですが、階段を降りるとき少し怖くて。保証期間内なら交換できますか？","ko":"손앞 글씨는 선명하게 보이는데 계단 내려갈 때 조금 무서워서요. 보증 기간 안이면 교환 되나요?","note":""},{"speaker":"코바야시","role":"안경점 스태프","jp":"もちろんです！<ruby>半年間<rt>はんとしがん</rt></ruby>の<ruby>保証期間<rt>ほしょうきかん</rt></ruby><ruby>内<rt>ない</rt></ruby>ですので、<ruby>無料<rt>むりょう</rt></ruby>で<ruby>度数<rt>どすう</rt></ruby>を<ruby>少<rt>すこ</rt></ruby>し<ruby>弱<rt>よわ</rt></ruby>めるか<ruby>中近両用<rt>ちゅうきんりょうよう</rt></ruby>に<ruby>変更<rt>へんこう</rt></ruby>できます。","plain":"もちろんです！半年間の保証期間内ですので、無料で度数を少し弱めるか中近両用に変更できます。","ko":"물론이죠! 6개월 보증 기간 내라서 무료로 도수를 조금 낮추거나 중근양용으로 변경해 드립니다.","note":""},{"speaker":"나","role":"손님","jp":"<ruby>安心<rt>あんしん</rt></ruby>しました！ついでに<ruby>下<rt>した</rt></ruby>を<ruby>向<rt>む</rt></ruby>くと<ruby>少<rt>すこ</rt></ruby>しズレるので、つるの<ruby>調整<rt>ちょうせい</rt></ruby>とネジ<ruby>締<rt>し</rt></ruby>めもお<ruby>願<rt>ねが</rt></ruby>いできますか？","plain":"安心しました！ついでに下を向くと少しズレるので、つるの調整とネジ締めもお願いできますか？","ko":"안심이 되네요! 김에 고개를 숙이면 조금 흘러내려서 안경다리 조정이랑 나사 조이도 부탁드릴 수 있을까요?","note":""},{"speaker":"코바야시","role":"안경점 스태프","jp":"<ruby>喜<rt>よろこ</rt></ruby>んで！<ruby>無料<rt>むりょう</rt></ruby>で<ruby>超音波洗浄<rt>ちょうおんぱせんじょう</rt></ruby>もしてお<ruby>渡<rt>わた</rt></ruby>ししますね。<ruby>専用<rt>せんよう</rt></ruby>の<ruby>メガネ拭<rt>めがねふ</rt></ruby>きもどうぞ！","plain":"喜んで！無料で超音波洗浄もしてお渡ししますね。専用のメガネ拭きもどうぞ！","ko":"기꺼이요! 무료로 초음파 세척까지 해서 드릴게요. 전용 안경닦이도 챙겨 가세요!","note":""}]}],"graduation":[{"badge":"응용·옵션","title":"31일 완주 회고·실력 변화와 학습 노하우 나누기","lines":[{"speaker":"하루카","role":"졸업 파트너","jp":"<ruby>三十一日間<rt>さんじゅういちにちかん</rt></ruby>のカリキュラム<ruby>完走<rt>かんそう</rt></ruby>、<ruby>本当<rt>ほんとう</rt></ruby>におめでとうございます！<ruby>一番<rt>いちばん</rt></ruby><ruby>成長<rt>せいちょう</rt></ruby>を<ruby>感<rt>かん</rt></ruby>じたのはどんな<ruby>瞬間<rt>しゅんかん</rt></ruby>ですか？","plain":"三十一日間のカリキュラム完走、本当におめでとうございます！一番成長を感じたのはどんな瞬間ですか？","ko":"31일 커리큘럼 완주 정말 축하드려요! 가장 크게 성장을 느낀 건 어떤 순간이었나요?","note":""},{"speaker":"나","role":"학습자","jp":"ありがとうございます！<ruby>三回<rt>さんかい</rt></ruby>リピートを<ruby>続<rt>つづ</rt></ruby>けたおかげで、ネイティブのスピードが<ruby>少<rt>すこ</rt></ruby>しずつ<ruby>聞き取<rt>ききと</rt></ruby>れるようになりました。","plain":"ありがとうございます！三回リピートを続けたおかげで、ネイティブのスピードが少しずつ聞き取れるようになりました。","ko":"감사합니다! 3회 반복을 꾸준히 한 덕분에 원어민 속도가 조금씩 들리기 시작했어요.","note":""},{"speaker":"하루카","role":"졸업 파트너","jp":"<ruby>リスニング力<rt>りすにんぐりょく</rt></ruby>も<ruby>自然な抑揚<rt>しぜんなよくよう</rt></ruby>もすごく<ruby>上達<rt>じょうたつ</rt></ruby>しましたよ！<ruby>場面<rt>ばめん</rt></ruby>ごとの<ruby>語彙力<rt>ごいりょく</rt></ruby>も<ruby>一気<rt>いっき</rt></ruby>に<ruby>増<rt>ふ</rt></ruby>えましたね。","plain":"リスニング力も自然な抑揚もすごく上達しましたよ！場面ごとの語彙力も一気に増えましたね。","ko":"듣기 실력도 자연스러운 억양도 엄청 늘었어요! 상황별 어휘력도 확 늘었네요.","note":""},{"speaker":"나","role":"학습자","jp":"<ruby>以前<rt>いぜん</rt></ruby>は<ruby>言葉<rt>ことば</rt></ruby>に<ruby>詰<rt>つ</rt></ruby>まると<ruby>焦<rt>あせ</rt></ruby>っていましたが、<ruby>今<rt>いま</rt></ruby>は<ruby>別<rt>べつ</rt></ruby>の<ruby>言葉<rt>ことば</rt></ruby>で<ruby>言<rt>い</rt></ruby>い<ruby>換<rt>か</rt></ruby>える<ruby>度胸<rt>どきょう</rt></ruby>がつきました。","plain":"以前は言葉に詰まると焦っていましたが、今は別の言葉で言い換える度胸がつきました。","ko":"예전에는 말이 막히면 당황했는데, 이제는 다른 말로 바꿔 말할 용기가 생겼어요.","note":""},{"speaker":"하루카","role":"졸업 파트너","jp":"<ruby>自然<rt>しぜん</rt></ruby>な<ruby>相槌<rt>あいづち</rt></ruby>を<ruby>打<rt>う</rt></ruby>ちながら<ruby>話<rt>はな</rt></ruby>せるようになると、<ruby>本当<rt>ほんとう</rt></ruby>に<ruby>会話<rt>かいわ</rt></ruby>が<ruby>弾<rt>はず</rt></ruby>みますよね！","plain":"自然な相槌を打ちながら話せるようになると、本当に会話が弾みますよね！","ko":"자연스럽게 맞장구를 치면서 말하게 되면 정말 대화가 술술 풀리죠!","note":"「相槌(あいづち)」= 맞장구."},{"speaker":"나","role":"학습자","jp":"<ruby>毎日<rt>まいにち</rt></ruby><ruby>十二分<rt>じゅうにふん</rt></ruby>の<ruby>学習<rt>がくしゅう</rt></ruby>を<ruby>習慣化<rt>しゅうかんか</rt></ruby>できて、<ruby>継続は力<rt>けいぞくはちから</rt></ruby>なりと<ruby>心<rt>こころ</rt></ruby>から<ruby>実感<rt>じっかん</rt></ruby>しています！","plain":"毎日十二分の学習を習慣化できて、継続は力なりと心から実感しています！","ko":"매일 12분 학습을 습관화할 수 있어서 꾸준함이 힘이라는 걸 진심으로 실감하고 있어요!","note":""}]},{"badge":"트러블·마무리","title":"다음 일본 여행 버킷리스트와 새로운 출발","lines":[{"speaker":"하루카","role":"졸업 파트너","jp":"<ruby>卒業<rt>そつぎょう</rt></ruby>はゴールではなく<ruby>新たなスタート<rt>あらたなすたーと</rt></ruby>ですね！これから<ruby>日本<rt>にほん</rt></ruby>で<ruby>叶<rt>かな</rt></ruby>えたいバケットリストは<ruby>何<rt>なん</rt></ruby>ですか？","plain":"卒業はゴールではなく新たなスタートですね！これから日本で叶えたいバケットリストは何ですか？","ko":"졸업은 끝이 아니라 새로운 출발이네요! 앞으로 일본에서 이루고 싶은 버킷리스트가 뭔가요?","note":""},{"speaker":"나","role":"학습자","jp":"<ruby>次<rt>つぎ</rt></ruby>の<ruby>旅行<rt>りょこう</rt></ruby>では<ruby>翻訳<rt>ほんやく</rt></ruby>アプリに<ruby>頼<rt>たよ</rt></ruby>らず、<ruby>京都<rt>きょうと</rt></ruby>の<ruby>老舗<rt>しにせ</rt></ruby>や<ruby>渋谷<rt>しぶや</rt></ruby>のメガネ<ruby>屋<rt>や</rt></ruby>さんで<ruby>現地交流<rt>げんちこうりゅう</rt></ruby>を<ruby>楽<rt>たの</rt></ruby>しみたいです！","plain":"次の旅行では翻訳アプリに頼らず、京都の老舗や渋谷のメガネ屋さんで現地交流を楽しみたいです！","ko":"다음 여행에서는 번역 앱에 기대지 않고 교토 노포나 시부야 안경점에서 현지 교류를 즐기고 싶어요!","note":"「老舗(しにせ)」= 오래된 전통 가게."},{"speaker":"하루카","role":"졸업 파트너","jp":"<ruby>素敵<rt>すてき</rt></ruby>ですね！<ruby>今<rt>いま</rt></ruby>の<ruby>実力<rt>じつりょく</rt></ruby>ならカフェも<ruby>居酒屋<rt>いざかや</rt></ruby>もビジネス<ruby>会話<rt>かいわ</rt></ruby>も<ruby>自信<rt>じしん</rt></ruby>を<ruby>持<rt>も</rt></ruby>って<ruby>実践<rt>じっせん</rt></ruby>できますよ。","plain":"素敵ですね！今の実力ならカフェも居酒屋もビジネス会話も自信を持って実践できますよ。","ko":"멋지네요! 지금 실력이면 카페도 이자카야도 비즈니스 회화도 자신 있게 실전에 써먹을 수 있어요.","note":""},{"speaker":"나","role":"학습자","jp":"これからも<ruby>普段<rt>ふだん</rt></ruby>から<ruby>日本語<rt>にほんご</rt></ruby>で<ruby>独り言練習<rt>ひとりごとれんしゅう</rt></ruby>をして、<ruby>自由<rt>じゆう</rt></ruby>フリートークにも<ruby>挑戦<rt>ちょうせん</rt></ruby>し<ruby>続<rt>つづ</rt></ruby>けます。","plain":"これからも普段から日本語で独り言練習をして、自由フリートークにも挑戦し続けます。","ko":"앞으로도 평소 일본어로 혼잣말 연습을 하고, 자유 프리토킹에도 계속 도전할 거예요.","note":""},{"speaker":"하루카","role":"졸업 파트너","jp":"<ruby>焦<rt>あせ</rt></ruby>らず<ruby>自分<rt>じぶん</rt></ruby>のペースで<ruby>一歩<rt>いっぽ</rt></ruby>ずつですね！いつでもコトノハでまたおしゃべりしましょう。","plain":"焦らず自分のペースで一歩ずつですね！いつでもコトノハでまたおしゃべりしましょう。","ko":"조급해하지 말고 내 페이스대로 한 걸음씩이에요! 언제든 코토노하에서 또 수다 떨어요.","note":""},{"speaker":"나","role":"학습자","jp":"<ruby>三十一日間<rt>さんじゅういちにちかん</rt></ruby>ずっと<ruby>応援<rt>おうえん</rt></ruby>してくれてありがとう！これからもよろしくお<ruby>願<rt>ねが</rt></ruby>いします！","plain":"三十一日間ずっと応援してくれてありがとう！これからもよろしくお願いします！","ko":"31일 동안 내내 응원해 줘서 고마워요! 앞으로도 잘 부탁합니다!","note":""}]}]};
